    async def digital_twin_execute_gripper_close_test(
        self,
        target: str,
        robot: str,
        origin_resource_location: str,
        part_name: str,
        *,
        confirmed: bool = False,
    ) -> dict[str, Any]:
        """Close the physical RG2 on the selected part, then always reopen it."""
        part_key = str(part_name or "").strip()
        function_name = "Gripper Close Test"
        base = {
            "success": False,
            "target": target,
            "robot": robot,
            "function_name": function_name,
            "origin_resource_location": origin_resource_location,
            "part_name": part_key,
        }
        if not part_key:
            return {**base, "message": "part_name is empty"}
        if confirmed is not True:
            return {
                **base,
                "message": "Explicit operator confirmation is required for Gripper Close Test.",
            }

        execution_lock = self._ur5e_robot_function_execution_lock
        if not execution_lock.acquire(blocking=False):
            active = str(self._ur5e_robot_function_execution_active or "UR5e motion")
            return {
                **base,
                "message": f"UR5e motion is already active: {active}.",
                "active_function": active,
            }
        self._ur5e_robot_function_execution_active = function_name
        self._ur5e_robot_function_execution_stage = "fresh_readiness"
        self._ur5e_robot_function_execution_started_at = time.time()
        release_execution_lock_here = True
        agent_motion_lock: Any | None = None
        release_agent_lock_here = False

        def _finish_cycle(resource_agent: Any, result: dict[str, Any]) -> None:
            if result.get("reopen_success"):
                resource_agent._gripper_state = "open"
            if not result.get("close_success") or not result.get("reopen_success"):
                self._ur5e_robot_function_state_uncertain = True

        try:
            resource_agent, _call_kwargs, readiness, error = (
                await self._digital_twin_robot_function_execution_preflight_async(
                    target,
                    robot,
                    "pick_grasp",
                    origin_resource_location,
                    "",
                    part_key,
                )
            )
            if error or resource_agent is None:
                return {
                    **base,
                    **readiness,
                    "message": error or "Gripper Close Test physical readiness failed.",
                }
            if str(getattr(resource_agent, "_gripper_state", "") or "").strip() != "open":
                return {
                    **base,
                    **readiness,
                    "message": "Gripper Close Test requires the empty RG2 to be open.",
                }

            task_context = dict(getattr(resource_agent, "_task_ctx", {}) or {})
            try:
                gripper_close_position = float(task_context["gripper_close_position"])
            except (KeyError, TypeError, ValueError, OverflowError):
                return {
                    **base,
                    **readiness,
                    "message": (
                        "Gripper Close Test requires the retained gripper_close_position from "
                        "pick_approach."
                    ),
                }
            if not math.isfinite(gripper_close_position):
                return {
                    **base,
                    **readiness,
                    "message": "Gripper Close Test gripper_close_position is not finite.",
                }
            if part_key == "MG" and abs(gripper_close_position - 0.047) > 5e-6:
                return {
                    **base,
                    **readiness,
                    "message": (
                        "MG Gripper Close Test requires gripper_close_position approximately "
                        "0.047."
                    ),
                }

            controller = getattr(resource_agent, "_controller", None)
            close_gripper = getattr(controller, "close_gripper", None)
            open_gripper = getattr(controller, "open_gripper", None)
            if not callable(close_gripper) or not callable(open_gripper):
                return {
                    **base,
                    **readiness,
                    "message": "Gripper Close Test physical RG2 controller is unavailable.",
                }
            try:
                gripper_open_position = float(getattr(controller, "gripper_open"))
            except (TypeError, ValueError, OverflowError):
                gripper_open_position = 0.11
            if (
                not math.isfinite(gripper_open_position)
                or gripper_close_position < 0.0
                or gripper_close_position > gripper_open_position
            ):
                return {
                    **base,
                    **readiness,
                    "message": (
                        "Gripper Close Test gripper_close_position is outside the configured "
                        "RG2 range."
                    ),
                }

            agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
            if agent_motion_lock is not None:
                release_agent_lock_here = bool(agent_motion_lock.acquire(blocking=False))
                if not release_agent_lock_here:
                    return {
                        **base,
                        **readiness,
                        "message": "The ur5e RobotAgent is already executing a robot task.",
                    }

            hold_sec = max(0.0, float(getattr(self, "_MG_CLOSE_TEST_HOLD_S", 3.0)))

            async def _close_and_reopen() -> dict[str, Any]:
                close_success = False
                reopen_success = False
                close_message = ""
                reopen_message = ""
                try:
                    try:
                        close_success = bool(
                            await asyncio.to_thread(
                                close_gripper,
                                position=gripper_close_position,
                            )
                        )
                        if not close_success:
                            close_message = str(
                                getattr(controller, "_last_failure_message", "") or ""
                            ).strip()
                    except Exception as exc:  # noqa: BLE001 - physical RG2 boundary.
                        close_message = f"{type(exc).__name__}: {exc}"
                    if close_success:
                        await asyncio.sleep(hold_sec)
                finally:
                    try:
                        reopen_success = bool(await asyncio.to_thread(open_gripper))
                        if not reopen_success:
                            reopen_message = str(
                                getattr(controller, "_last_failure_message", "") or ""
                            ).strip()
                    except Exception as exc:  # noqa: BLE001 - physical RG2 boundary.
                        reopen_message = f"{type(exc).__name__}: {exc}"
                return {
                    "close_success": close_success,
                    "reopen_success": reopen_success,
                    "close_message": close_message,
                    "reopen_message": reopen_message,
                }

            self._ur5e_robot_function_execution_stage = "executing"
            cycle_task = asyncio.create_task(_close_and_reopen())
            try:
                cycle_result = await asyncio.shield(cycle_task)
            except asyncio.CancelledError:
                release_execution_lock_here = False
                release_agent_lock_here = False

                def _release_after_cycle(task: asyncio.Task[Any]) -> None:
                    try:
                        completed = dict(task.result())
                    except asyncio.CancelledError:
                        completed = {"close_success": False, "reopen_success": False}
                        log.warning("Gripper Close Test cycle was cancelled before completion")
                    except Exception:  # noqa: BLE001 - background physical RG2 boundary.
                        completed = {"close_success": False, "reopen_success": False}
                        log.exception("Gripper Close Test failed after UI cancellation")
                    _finish_cycle(resource_agent, completed)
                    if agent_motion_lock is not None:
                        agent_motion_lock.release()
                    self._ur5e_robot_function_execution_active = None
                    self._ur5e_robot_function_execution_stage = ""
                    self._ur5e_robot_function_execution_started_at = 0.0
                    execution_lock.release()

                cycle_task.add_done_callback(_release_after_cycle)
                raise

            _finish_cycle(resource_agent, cycle_result)
            if not cycle_result["close_success"] or not cycle_result["reopen_success"]:
                failed_actions = []
                if not cycle_result["close_success"]:
                    failed_actions.append(
                        "close"
                        + (
                            f": {cycle_result['close_message']}"
                            if cycle_result["close_message"]
                            else ""
                        )
                    )
                if not cycle_result["reopen_success"]:
                    failed_actions.append(
                        "reopen"
                        + (
                            f": {cycle_result['reopen_message']}"
                            if cycle_result["reopen_message"]
                            else ""
                        )
                    )
                return {
                    **base,
                    **readiness,
                    **cycle_result,
                    "gripper_close_position": gripper_close_position,
                    "message": (
                        f"Gripper Close Test failed ({'; '.join(failed_actions)}). Physical "
                        "state may have changed; inspect the UR5e before retrying."
                    ),
                }
            return {
                **base,
                **readiness,
                **cycle_result,
                "success": True,
                "gripper_close_position": gripper_close_position,
                "hold_sec": hold_sec,
                "message": (
                    f"{part_key} Gripper Close Test closed once to the retained position, "
                    "held for visual inspection, and reopened without moving the arm."
                ),
            }
        finally:
            if release_agent_lock_here and agent_motion_lock is not None:
                agent_motion_lock.release()
            if release_execution_lock_here:
                self._ur5e_robot_function_execution_active = None
                self._ur5e_robot_function_execution_stage = ""
                self._ur5e_robot_function_execution_started_at = 0.0
                execution_lock.release()

    async def digital_twin_execute_mg_close_test(
        self,
        target: str,
        robot: str,
        origin_resource_location: str,
        *,
        confirmed: bool = False,
    ) -> dict[str, Any]:
        """Run the retained MG compatibility entry point."""
        return await self.digital_twin_execute_gripper_close_test(
            target,
            robot,
            origin_resource_location,
            "MG",
            confirmed=confirmed,
        )

    def digital_twin_preview_pick_target(  # noqa: C901, PLR0912 - explicit read-only gates.
        self,
        target: str,
        robot: str,
        part_name: str,
    ) -> dict[str, Any]:
        """Compute a fresh physical UR5e pick target without commanding robot motion."""
        part_key = str(part_name or "").strip()
        base: dict[str, Any] = {
            "success": False,
            "ready": False,
            "part_name": part_key,
            "confidence": None,
            "world_pose": {},
            "travel_z": None,
            "pick_z": None,
            "age_sec": None,
            "rtde_control_required": False,
            "readiness": {
                "ready": False,
                "rtde_receive_connected": False,
                "joint_states_fresh": False,
                "world_tool0_ready": False,
                "detection_ready": False,
                "world_pose_ready": False,
                "calibration_ready": False,
                "table_plane_ready": False,
                "fresh": False,
                "rtde_control_required": False,
            },
        }
        cfg, error = self._robot_function_validate_request(target, robot, "pick_approach")
        if error or cfg is None:
            return {**base, "message": error, "blocked_reason": error}
        if str(robot or "").strip().lower() != "ur5e":
            reason = "Preview Target is implemented for physical ur5e first."
            return {**base, "message": reason, "blocked_reason": reason}
        if self._robot_function_capture_source(target, cfg) != "hardware":
            reason = "Preview Target requires hardware-led monitor mode."
            return {**base, "message": reason, "blocked_reason": reason}
        if not part_key:
            reason = "part_name is empty"
            return {**base, "message": reason, "blocked_reason": reason}

        robot_readiness = self._robot_function_capture_snapshot(target, "ur5e")
        base["readiness"].update(
            {
                "rtde_receive_connected": bool(
                    robot_readiness.get("rtde_receive_connected")
                ),
                "joint_states_fresh": bool(robot_readiness.get("joint_states_fresh")),
                "world_tool0_ready": bool(robot_readiness.get("world_tool0_ready")),
            }
        )
        if not robot_readiness.get("success"):
            reason = str(
                robot_readiness.get("blocked_reason")
                or "UR5e read-only state is not ready."
            )
            return {**base, "message": reason, "blocked_reason": reason}

        detection = self.test_physical_detection(target)
        status = dict(detection.get("status") or {})
        rows = [dict(row) for row in list(detection.get("detections") or [])]
        matching_rows = [row for row in rows if str(row.get("part_name") or "").strip() == part_key]
        if len(matching_rows) != 1:
            detected = sorted(
                {
                    str(row.get("part_name") or "").strip()
                    for row in rows
                    if str(row.get("part_name") or "").strip()
                }
            )
            detail = str(detection.get("message") or "").strip()
            if len(matching_rows) > 1:
                reason = (
                    f"requested part '{part_key}' matched {len(matching_rows)} detections; "
                    "selecting a motion target would be ambiguous"
                )
            elif rows:
                reason = f"requested part '{part_key}' was not detected; detected={detected}"
            else:
                reason = detail or "no parts detected"
            return {**base, "message": reason, "blocked_reason": reason}
        selected = matching_rows[0]

        pose_ready = str(selected.get("frame_id") or "").strip() == "world" and all(
            isinstance(selected.get(field), (int, float)) and math.isfinite(float(selected[field]))
            for field in ("x", "y", "z")
        )
        try:
            confidence = float(selected.get("confidence"))
        except (TypeError, ValueError):
            confidence = float("nan")
        captured_at = selected.get("captured_at") or status.get("updated_at")
        try:
            age_sec = max(0.0, time.time() - float(captured_at))
        except (TypeError, ValueError):
            age_sec = None
        fresh = age_sec is not None and age_sec <= 8.0
        readiness = {
            **dict(base["readiness"]),
            "ready": False,
            "detection_ready": bool(detection.get("success")),
            "world_pose_ready": pose_ready,
            "calibration_ready": bool(status.get("calibration_ready")),
            "table_plane_ready": bool(status.get("table_plane_ready")),
            "fresh": fresh,
            "rtde_control_required": False,
        }
        base.update(
            {
                "confidence": confidence if math.isfinite(confidence) else None,
                "world_pose": (
                    {
                        "frame_id": "world",
                        "x": float(selected["x"]),
                        "y": float(selected["y"]),
                        "z": float(selected["z"]),
                    }
                    if pose_ready
                    else {}
                ),
                "age_sec": age_sec,
                "readiness": readiness,
            }
        )
        blocked_reason = ""
        if not detection.get("success"):
            blocked_reason = str(detection.get("message") or "detection is not ready")
        elif not pose_ready:
            blocked_reason = "selected detection does not have a finite world pose"
        elif not bool(status.get("calibration_ready")):
            blocked_reason = str(status.get("calibration_error") or "calibration is not ready")
        elif not bool(status.get("table_plane_ready")):
            blocked_reason = "table_plane_ready is false"
        elif not fresh:
            blocked_reason = "selected detection is stale"
        elif not math.isfinite(confidence):
            blocked_reason = "selected detection confidence is invalid"
        if blocked_reason:
            return {**base, "message": blocked_reason, "blocked_reason": blocked_reason}

        resource_agent = self._physical_ur5e_robot_agent()
        controller = getattr(resource_agent, "_controller", None)
        compute_pick_targets = getattr(controller, "compute_pick_targets", None)
        if not callable(compute_pick_targets):
            reason = "Start the ur5e robot agent in Physical mode before Preview Target."
            return {**base, "message": reason, "blocked_reason": reason}
        missing_start_pose = object()
        remembered_start_pose = getattr(controller, "_last_start_pose", missing_start_pose)
        try:
            product_geometry = self._robot_function_product_geometry_for_part(part_key)
            computed = compute_pick_targets(
                part_name=part_key,
                product_geometry=product_geometry,
                detected_parts=[deepcopy(selected)],
            )
        except Exception as exc:  # noqa: BLE001 - isolate the read-only controller boundary.
            log.exception("physical pick target preview failed")
            reason = str(exc)
            return {**base, "message": reason, "blocked_reason": reason}
        finally:
            if remembered_start_pose is missing_start_pose:
                try:
                    delattr(controller, "_last_start_pose")
                except AttributeError:
                    pass
            else:
                controller._last_start_pose = remembered_start_pose
        if not isinstance(computed, dict) or not computed.get("success"):
            reason = (
                str(computed.get("message") or "compute_pick_targets failed")
                if isinstance(computed, dict)
                else "compute_pick_targets failed"
            )
            return {**base, "message": reason, "blocked_reason": reason}
        try:
            travel_z = float(computed["travel_z"])
            pick_z = float(computed["pick_z"])
        except (KeyError, TypeError, ValueError):
            reason = "compute_pick_targets returned invalid travel_z or pick_z"
            return {**base, "message": reason, "blocked_reason": reason}
        if not math.isfinite(travel_z) or not math.isfinite(pick_z):
            reason = "compute_pick_targets returned non-finite travel_z or pick_z"
            return {**base, "message": reason, "blocked_reason": reason}
        readiness["ready"] = True
        return {
            **base,
            "success": True,
            "ready": True,
            "travel_z": travel_z,
            "pick_z": pick_z,
            "computed": deepcopy(computed),
            "readiness": readiness,
            "message": "Pick target computed; no robot motion was requested.",
            "blocked_reason": "",
        }

    def _robot_function_relative_reference(  # noqa: C901, PLR0912, PLR0915
        self,
        *,
        resource_agent: Any,
        function_name: str,
        name: str,
        step_name: str,
        part_name: str,
        robot: str = "",
        computed_source: str = "resolve",
    ) -> dict[str, Any]:
        """Resolve the current world reference used by one relative capture."""
        controller = getattr(resource_agent, "_controller", None)
        if controller is None:
            return {"success": False, "message": "Physical robot controller is unavailable."}
        product_geometry = self._robot_function_product_geometry_for_part(part_name)
        missing_start_pose = object()
        remembered_start_pose = getattr(controller, "_last_start_pose", missing_start_pose)
        try:
            if function_name == "pick_approach":
                detect_parts = getattr(controller, "detect_parts", None)
                compute_pick_targets = getattr(controller, "compute_pick_targets", None)
                if not callable(detect_parts) or not callable(compute_pick_targets):
                    return {
                        "success": False,
                        "message": "Physical controller cannot read the selected part reference.",
                    }
                rows = [
                    dict(row)
                    for row in list(detect_parts() or [])
                    if isinstance(row, dict)
                ]
                matching_rows = [
                    row
                    for row in rows
                    if str(row.get("part_name") or "").strip() == part_name
                ]
                if len(matching_rows) != 1:
                    detected = sorted(
                        {
                            str(row.get("part_name") or "").strip()
                            for row in rows
                            if str(row.get("part_name") or "").strip()
                        }
                    )
                    if len(matching_rows) > 1:
                        message = (
                            f"requested part {part_name!r} matched {len(matching_rows)} "
                            "detections; the Cartesian reference is ambiguous"
                        )
                    else:
                        detail = str(getattr(controller, "_last_failure_message", "") or "")
                        if detail:
                            message = detail
                        elif detected:
                            message = (
                                f"Resolving this pose needs one fresh {part_name!r} detection; "
                                f"the latest accepted detections were {detected}. No position "
                                "was buffered and the existing saved position is unchanged."
                            )
                        else:
                            message = (
                                f"Resolving this pose needs one fresh {part_name!r} detection, "
                                "but the latest validated camera frame contained no accepted "
                                "part detections. No position was buffered and the existing "
                                "saved position is unchanged."
                            )
                    return {"success": False, "message": message}
                selected = matching_rows[0]
                computed = compute_pick_targets(
                    part_name=part_name,
                    product_geometry=product_geometry,
                    detected_parts=[deepcopy(selected)],
                )
                if not isinstance(computed, dict) or not computed.get("success"):
                    return {
                        "success": False,
                        "message": str(
                            dict(computed or {}).get("message")
                            or "compute_pick_targets failed"
                        ),
                    }
                try:
                    position_m = {
                        field: float(selected[field]) for field in ("x", "y", "z")
                    }
                    captured_at = float(selected["captured_at"])
                except (KeyError, TypeError, ValueError):
                    return {
                        "success": False,
                        "message": "selected part reference is missing finite world XYZ or captured_at",
                    }
                if (
                    str(selected.get("frame_id") or "").strip() != "world"
                    or not all(math.isfinite(value) for value in position_m.values())
                    or not math.isfinite(captured_at)
                ):
                    return {
                        "success": False,
                        "message": "selected part reference must contain finite XYZ in world",
                    }
                return {
                    "success": True,
                    "reference": {
                        "kind": "detected_part",
                        "frame_id": "world",
                        "name": part_name,
                        "position_m": position_m,
                        "source": str(
                            selected.get("source")
                            or computed.get("target_pose_source")
                            or "live_detection"
                        ),
                        "captured_at": captured_at,
                    },
                    "computed": deepcopy(computed),
                }
            if function_name == "place_approach":
                destination_location = str(name).strip()
                robot_key = str(
                    robot
                    or getattr(resource_agent, "agent_name", "")
                    or str(getattr(resource_agent, "jid", "")).split("@", maxsplit=1)[0]
                ).strip().lower()
                board_status: dict[str, Any] = {}
                if destination_location == "assembly_board-v1":
                    try:
                        board_status = self.perception_manager.assembly_board_v1_aruco_status(
                            robot_key
                        )
                    except (AttributeError, RuntimeError, ValueError) as exc:
                        return {
                            "success": False,
                            "message": (
                                f"assembly_board-v1 ArUco localization is unavailable for "
                                f"{robot_key or 'this robot'}: {exc}"
                            ),
                        }
                    if not board_status.get("accepted"):
                        return {
                            "success": False,
                            "message": (
                                f"Locate & Accept Board for {robot_key} before capturing or "
                                "testing place_approach."
                            ),
                        }
                    if (
                        "accepted_baseline_ready" in board_status
                        and not board_status.get("accepted_baseline_ready")
                    ):
                        detail = str(
                            board_status.get("accepted_baseline_error") or ""
                        ).strip()
                        return {
                            "success": False,
                            "message": detail
                            or (
                                f"The accepted assembly_board-v1 baseline for {robot_key} "
                                "is not usable; use Locate & Accept Board again."
                            ),
                        }
                    accepted_calibration_id = str(
                        board_status.get("accepted_calibration_id") or ""
                    ).strip()
                    current_calibration_id = str(
                        board_status.get("active_calibration_id")
                        or board_status.get("calibration_id")
                        or ""
                    ).strip()
                    if not accepted_calibration_id:
                        return {
                            "success": False,
                            "message": (
                                "The accepted assembly_board-v1 calibration identity is "
                                f"unavailable for {robot_key}; use Locate & Accept Board again."
                            ),
                        }
                    if (
                        current_calibration_id
                        and current_calibration_id != accepted_calibration_id
                    ):
                        return {
                            "success": False,
                            "message": (
                                "The assembly_board-v1 calibration identity changed for "
                                f"{robot_key}; use Locate & Accept Board again."
                            ),
                        }
                    if computed_source == "test_position" and bool(
                        board_status.get("excessive_movement")
                    ):
                        return {
                            "success": False,
                            "message": (
                                "Test Position is blocked because the current passive "
                                "ArUco view differs from the accepted assembly_board-v1 "
                                "pose by more than 10 mm or 2 deg. Use confirmed Run "
                                "place_approach to stage and reaccept a fresh observation."
                            ),
                        }
                    # Capture Pose records a correction against the explicit
                    # accepted board authority, never a passive cross-view sample.
                    capture_uses_accepted_pose = bool(
                        computed_source == "capture"
                        and board_status.get("accepted_baseline_ready")
                    )
                    live_pose_ready = bool(
                        board_status.get("ready_to_accept")
                        and not capture_uses_accepted_pose
                    )
                    if live_pose_ready and board_status.get("movement_blocked"):
                        return {
                            "success": False,
                            "message": (
                                "assembly_board-v1 moved more than 10 mm or 2 deg from the "
                                f"accepted {robot_key} pose; use Locate & Accept Board again."
                            ),
                        }
                    board_pose_source = "live_stable" if live_pose_ready else "accepted"
                    board_pose = dict(
                        board_status.get("pose")
                        if live_pose_ready
                        else board_status.get("accepted_pose")
                        or {}
                    )
                    try:
                        board_pose = {
                            field: float(board_pose[field])
                            for field in ("x", "y", "z", "qx", "qy", "qz", "qw")
                        }
                        board_captured_at = float(
                            board_status.get("frame_captured_at")
                            if live_pose_ready
                            else board_status.get("accepted_frame_captured_at")
                            or board_status.get("accepted_at")
                            or 0.0
                        )
                        accepted_generation = int(
                            board_status.get("accepted_generation", 0) or 0
                        )
                        marker_length_m = float(board_status["marker_length_m"])
                    except (KeyError, TypeError, ValueError):
                        board_pose = {}
                        board_captured_at = 0.0
                        accepted_generation = 0
                        marker_length_m = 0.0
                    if (
                        not board_pose
                        or not all(math.isfinite(value) for value in board_pose.values())
                        or board_captured_at <= 0.0
                        or accepted_generation < 1
                        or not math.isfinite(marker_length_m)
                        or marker_length_m <= 0.0
                    ):
                        return {
                            "success": False,
                            "message": (
                                "The accepted assembly_board-v1 pose is invalid for "
                                f"{robot_key}; make the tag visible and use Locate & Accept "
                                "Board again."
                            ),
                        }
                    frozen_assembly_board_v1_aruco = {
                        "destination_location": "assembly_board-v1",
                        "camera_role": robot_key,
                        "generation": accepted_generation,
                        "captured_at": board_captured_at,
                        "sample_started_at": float(
                            board_status.get("sample_started_at") or 0.0
                        ),
                        "frame_id": "world",
                        "pose": deepcopy(board_pose),
                        "calibration_id": accepted_calibration_id,
                        "marker_dictionary": str(
                            board_status.get("dictionary") or "DICT_ARUCO_ORIGINAL"
                        ),
                        "marker_id": int(board_status.get("marker_id") or 70),
                        "marker_length_m": marker_length_m,
                        "sample_count": int(board_status.get("sample_count") or 0),
                        "translation_delta_m": board_status.get("translation_delta_m"),
                        "rotation_delta_deg": board_status.get("rotation_delta_deg"),
                        "source": "assembly_board-v1_aruco",
                        "observation_source": board_pose_source,
                    }
                    for quality_field in (
                        "reprojection_error_px",
                        "translation_spread_m",
                        "rotation_spread_deg",
                    ):
                        try:
                            quality_value = float(board_status[quality_field])
                        except (KeyError, TypeError, ValueError):
                            continue
                        if math.isfinite(quality_value):
                            frozen_assembly_board_v1_aruco[quality_field] = quality_value
                else:
                    frozen_assembly_board_v1_aruco = {}
                compute_place_targets = getattr(controller, "compute_place_targets", None)
                if not callable(compute_place_targets):
                    return {
                        "success": False,
                        "message": "Physical controller cannot compute the destination target.",
                    }
                computed = compute_place_targets(
                    pick_ctx=deepcopy(getattr(resource_agent, "_task_ctx", {}) or {}),
                    product_geometry=product_geometry,
                    part_name=part_name,
                    destination_location=str(name).strip(),
                    assembly_board_v1_aruco=frozen_assembly_board_v1_aruco,
                )
                if not isinstance(computed, dict) or not computed.get("success"):
                    return {
                        "success": False,
                        "message": str(
                            dict(computed or {}).get("message")
                            or "compute_place_targets failed"
                        ),
                    }
                target_pose = dict(computed.get("target_pose") or {})
                try:
                    position_m = {
                        field: float(target_pose[field]) for field in ("x", "y", "z")
                    }
                except (KeyError, TypeError, ValueError):
                    return {
                        "success": False,
                        "message": "configured destination target is missing finite world XYZ",
                    }
                if not all(math.isfinite(value) for value in position_m.values()):
                    return {
                        "success": False,
                        "message": "configured destination target contains non-finite world XYZ",
                    }
                if destination_location == "assembly_board-v1":
                    position_m = {
                        field: float(board_pose[field]) for field in ("x", "y", "z")
                    }
                    reference = {
                        "kind": "destination_target",
                        "frame_id": "world",
                        "name": "assembly_board-v1",
                        "position_m": position_m,
                        "pose": deepcopy(board_pose),
                        "source": "assembly_board-v1_aruco",
                        "captured_at": board_captured_at,
                        "camera_role": robot_key,
                        "generation": accepted_generation,
                        "calibration_id": accepted_calibration_id,
                        "marker_length_m": marker_length_m,
                        "observation_source": board_pose_source,
                    }
                else:
                    reference = {
                        "kind": "destination_target",
                        "frame_id": "world",
                        "name": destination_location,
                        "position_m": position_m,
                        "source": "computed_destination",
                        "captured_at": time.time(),
                    }
                return {
                    "success": True,
                    "reference": reference,
                    "computed": deepcopy(computed),
                    "assembly_board_v1_aruco": deepcopy(
                        frozen_assembly_board_v1_aruco
                    ),
                }
            return {
                "success": False,
                "message": (
                    f"{function_name}.{step_name} has no relative Cartesian reference."
                ),
            }
        except (AttributeError, RuntimeError, TypeError, ValueError) as exc:
            log.exception("relative Cartesian reference capture failed")
            return {"success": False, "message": str(exc)}
        finally:
            if remembered_start_pose is missing_start_pose:
                try:
                    delattr(controller, "_last_start_pose")
                except AttributeError:
                    pass
            else:
                controller._last_start_pose = remembered_start_pose

    @staticmethod
    def _robot_function_pose_relative_to_reference(
        reference_pose: dict[str, Any],
        world_tool_pose: dict[str, Any],
    ) -> dict[str, float]:
        """Return reference_T_tool for two finite world-frame poses."""
        fields = ("x", "y", "z", "qx", "qy", "qz", "qw")
        try:
            reference = {field: float(reference_pose[field]) for field in fields}
            tool = {field: float(world_tool_pose[field]) for field in fields}
        except (KeyError, TypeError, ValueError):
            return {}
        if not all(math.isfinite(value) for value in (*reference.values(), *tool.values())):
            return {}

        def _normalized_quaternion(pose: dict[str, float]) -> tuple[float, float, float, float]:
            quaternion = tuple(pose[field] for field in ("qx", "qy", "qz", "qw"))
            norm = math.sqrt(sum(value * value for value in quaternion))
            if norm <= 1e-12:
                raise ValueError("quaternion norm is zero")
            return tuple(value / norm for value in quaternion)

        def _multiply(
            left: tuple[float, float, float, float],
            right: tuple[float, float, float, float],
        ) -> tuple[float, float, float, float]:
            lx, ly, lz, lw = left
            rx, ry, rz, rw = right
            return (
                lw * rx + lx * rw + ly * rz - lz * ry,
                lw * ry - lx * rz + ly * rw + lz * rx,
                lw * rz + lx * ry - ly * rx + lz * rw,
                lw * rw - lx * rx - ly * ry - lz * rz,
            )

        try:
            reference_quaternion = _normalized_quaternion(reference)
            tool_quaternion = _normalized_quaternion(tool)
        except ValueError:
            return {}
        inverse_reference = (
            -reference_quaternion[0],
            -reference_quaternion[1],
            -reference_quaternion[2],
            reference_quaternion[3],
        )
        world_delta = (
            tool["x"] - reference["x"],
            tool["y"] - reference["y"],
            tool["z"] - reference["z"],
        )
        rotated = _multiply(
            _multiply(inverse_reference, (*world_delta, 0.0)),
            reference_quaternion,
        )
        relative_quaternion = _multiply(inverse_reference, tool_quaternion)
        relative_norm = math.sqrt(sum(value * value for value in relative_quaternion))
        if relative_norm <= 1e-12:
            return {}
        relative_quaternion = tuple(value / relative_norm for value in relative_quaternion)
        return {
            "x": rotated[0],
            "y": rotated[1],
            "z": rotated[2],
            "qx": relative_quaternion[0],
            "qy": relative_quaternion[1],
            "qz": relative_quaternion[2],
            "qw": relative_quaternion[3],
        }

    @staticmethod
    def _robot_function_pose_from_reference(
        reference_pose: dict[str, Any],
        relative_pose: dict[str, Any],
    ) -> dict[str, float]:
        """Return world_T_tool for finite world_T_reference and reference_T_tool poses."""
        fields = ("x", "y", "z", "qx", "qy", "qz", "qw")
        try:
            reference = {field: float(reference_pose[field]) for field in fields}
            relative = {field: float(relative_pose[field]) for field in fields}
        except (KeyError, TypeError, ValueError):
            return {}
        if not all(
            math.isfinite(value)
            for value in (*reference.values(), *relative.values())
        ):
            return {}

        def _normalized_quaternion(
            pose: dict[str, float],
        ) -> tuple[float, float, float, float]:
            quaternion = tuple(pose[field] for field in ("qx", "qy", "qz", "qw"))
            norm = math.sqrt(sum(value * value for value in quaternion))
            if norm <= 1e-12:
                raise ValueError("quaternion norm is zero")
            return tuple(value / norm for value in quaternion)

        def _multiply(
            left: tuple[float, float, float, float],
            right: tuple[float, float, float, float],
        ) -> tuple[float, float, float, float]:
            lx, ly, lz, lw = left
            rx, ry, rz, rw = right
            return (
                lw * rx + lx * rw + ly * rz - lz * ry,
                lw * ry - lx * rz + ly * rw + lz * rx,
                lw * rz + lx * ry - ly * rx + lz * rw,
                lw * rw - lx * rx - ly * ry - lz * rz,
            )

        try:
            reference_quaternion = _normalized_quaternion(reference)
            relative_quaternion = _normalized_quaternion(relative)
        except ValueError:
            return {}
        rotated = _multiply(
            _multiply(
                reference_quaternion,
                (relative["x"], relative["y"], relative["z"], 0.0),
            ),
            (
                -reference_quaternion[0],
                -reference_quaternion[1],
                -reference_quaternion[2],
                reference_quaternion[3],
            ),
        )
        quaternion = _multiply(reference_quaternion, relative_quaternion)
        quaternion_norm = math.sqrt(sum(value * value for value in quaternion))
        if quaternion_norm <= 1e-12:
            return {}
        quaternion = tuple(value / quaternion_norm for value in quaternion)
        return {
            "x": reference["x"] + rotated[0],
            "y": reference["y"] + rotated[1],
            "z": reference["z"] + rotated[2],
            "qx": quaternion[0],
            "qy": quaternion[1],
            "qz": quaternion[2],
            "qw": quaternion[3],
        }

    def digital_twin_capture_function_step(  # noqa: C901, PLR0912
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        primitive: str = "move_cartesian",
        *,
        part_name: str = "",
        operator_confirmed_held_part: bool = False,
        operator_handoff_origin_resource_location: str = "",
    ) -> dict[str, Any]:
        if not isinstance(operator_confirmed_held_part, bool):
            return {
                "success": False,
                "message": "operator_confirmed_held_part must be an exact boolean.",
            }
        if operator_confirmed_held_part and not (
            str(robot or "") == "ur5e"
            and str(function_name or "") == "place_approach"
            and str(name or "") == "assembly_board-v1"
            and str(part_name or "") in _MOVE_INSERT_SUPPORTED_PARTS
        ):
            return {
                "success": False,
                "message": (
                    "operator_confirmed_held_part Capture Pose is available only for "
                    "physical ur5e place_approach at assembly_board-v1 with exact "
                    "supported part_name."
                ),
            }
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        step_key = self._robot_function_safe_name(step_name)
        primitive = str(primitive or "move_cartesian").strip()
        template_step = self._robot_function_template_step(function_name, step_key)
        if template_step is None:
            return {"success": False, "message": f"unknown step: {function_name}.{step_key}"}
        expected_primitive = str(template_step.get("primitive") or "")
        if primitive != expected_primitive:
            return {
                "success": False,
                "message": (
                    f"primitive mismatch for {function_name}.{step_key}: "
                    f"expected {expected_primitive}, got {primitive}"
                ),
            }
        if not bool(template_step.get("recordable")):
            return {
                "success": False,
                "message": f"{function_name}.{step_key} does not require a physical position.",
            }
        if not str(name or "").strip():
            location_argument = self.digital_twin_function_location_argument(function_name)
            return {
                "success": False,
                "message": f"{location_argument or 'location'} is empty",
            }
        robot_key = str(robot or "").strip().lower()
        source = self._robot_function_capture_source(target, cfg)
        if source != "hardware":
            return {
                "success": False,
                "message": "Physical position capture requires hardware-led monitor mode.",
            }
        execution_lock = self._ur5e_robot_function_execution_lock
        if not execution_lock.acquire(blocking=False):
            active = str(
                self._ur5e_robot_function_execution_active or "Physical robot motion"
            )
            return {
                "success": False,
                "message": f"Physical robot motion is already active: {active}.",
                "active_function": active,
            }
        resource_agent = self._physical_robot_agent(robot_key)
        if resource_agent is None:
            execution_lock.release()
            return {
                "success": False,
                "message": f"No configured physical RobotAgent is available for {robot_key}.",
            }
        agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
        agent_lock_acquired = False
        if agent_motion_lock is not None:
            agent_lock_acquired = bool(agent_motion_lock.acquire(blocking=False))
            if not agent_lock_acquired:
                execution_lock.release()
                return {
                    "success": False,
                    "message": (
                        f"The {robot_key} RobotAgent is already executing a robot task."
                    ),
                }
        self._ur5e_robot_function_execution_active = (
            f"{function_name}.{step_key} Capture Pose"
        )
        readiness: dict[str, Any] = {}
        resolved: dict[str, Any] = {}
        missing_task_context = object()
        remembered_task_context = getattr(
            resource_agent,
            "_task_ctx",
            missing_task_context,
        )
        try:
            with self._ur5e_robot_function_preflight_lock:
                readiness = self._robot_function_capture_snapshot(target, robot_key)
                if readiness.get("success"):
                    if operator_confirmed_held_part:
                        held_part = getattr(resource_agent, "_held_part", None)
                        task_context = dict(
                            getattr(resource_agent, "_task_ctx", {}) or {}
                        )
                        active_pick_context = bool(
                            held_part not in (None, "")
                            or task_context.get("part_name") not in (None, "")
                            or task_context.get("origin_resource_location")
                            not in (None, "")
                        )
                        if active_pick_context:
                            resolved = {
                                "success": False,
                                "message": (
                                    "operator_confirmed_held_part Capture Pose cannot "
                                    "replace existing RobotAgent custody or an active pick "
                                    "context."
                                ),
                            }
                        else:
                            try:
                                product_geometry = (
                                    self._robot_function_product_geometry_for_part(
                                        str(part_name or "")
                                    )
                                )
                            except Exception as exc:  # noqa: BLE001 - manifest boundary.
                                resolved = {
                                    "success": False,
                                    "message": (
                                        "Could not resolve product geometry for "
                                        f"{str(part_name or '')}: "
                                        f"{exc}"
                                    ),
                                }
                            else:
                                handoff, handoff_readiness, handoff_error = (
                                    self._operator_confirmed_mg_held_part_handoff(
                                        target,
                                        resource_agent,
                                        origin_resource_location=(
                                            operator_handoff_origin_resource_location
                                        ),
                                        part_name=str(part_name or ""),
                                        product_geometry=product_geometry,
                                    )
                                )
                                readiness.update(handoff_readiness)
                                if handoff_error:
                                    resolved = {
                                        "success": False,
                                        "message": handoff_error,
                                    }
                                else:
                                    resource_agent._task_ctx = {
                                        "part_name": str(part_name or ""),
                                        "model_name": str(
                                            product_geometry.get("model_name") or ""
                                        ),
                                        "origin_resource_location": handoff[
                                            "origin_resource_location"
                                        ],
                                        "origin_pose": deepcopy(
                                            handoff[
                                                "world_held_part_pose_at_grasp"
                                            ]
                                        ),
                                        "origin_pose_provenance": deepcopy(
                                            handoff["origin_pose_provenance"]
                                        ),
                                        "resolved_cartesian_positions": {
                                            "descend": deepcopy(
                                                handoff["world_tool0_pose_at_grasp"]
                                            )
                                        },
                                        "held_part_handoff": deepcopy(handoff),
                                        "operator_confirmed_held_part": True,
                                        "pick_approach_recording_path": handoff[
                                            "pick_approach_recording_path"
                                        ],
                                        "pick_approach_recording_sha256": handoff[
                                            "pick_approach_recording_sha256"
                                        ],
                                    }
                    if not resolved:
                        resolved = self._resolve_robot_function_position(
                            target,
                            robot_key,
                            function_name,
                            name,
                            step_key,
                            part_name=str(part_name or "").strip(),
                            readiness=readiness,
                            resource_agent=resource_agent,
                            computed_source="capture",
                        )
        finally:
            if remembered_task_context is missing_task_context:
                try:
                    delattr(resource_agent, "_task_ctx")
                except AttributeError:
                    pass
            else:
                resource_agent._task_ctx = remembered_task_context
            self._ur5e_robot_function_execution_active = None
            if agent_lock_acquired:
                agent_motion_lock.release()
            execution_lock.release()
        if not readiness.get("success"):
            return {
                "success": False,
                "message": str(readiness.get("blocked_reason") or "capture is not ready"),
                "readiness": readiness,
            }
        if not resolved.get("success"):
            return {
                "success": False,
                "message": str(
                    resolved.get("message")
                    or f"could not resolve {function_name}.{step_key} for Capture Pose"
                ),
                "readiness": readiness,
            }
        waypoint = dict(readiness.get("waypoint") or {})
        pose = dict(waypoint.get("pose") or {})
        params = {field: float(pose[field]) for field in ("x", "y", "z", "qx", "qy", "qz", "qw")}
        key = self._robot_function_buffer_key(
            target,
            robot_key,
            self._robot_function_safe_function_name(function_name),
            self._robot_function_safe_name(name),
            str(part_name or "").strip(),
        )
        relative_reference = dict(resolved.get("computed_reference") or {})
        try:
            raw_computed_pose = dict(resolved["computed_position"])
            computed_pose = {
                field: float(raw_computed_pose[field])
                for field in ("x", "y", "z", "qx", "qy", "qz", "qw")
            }
            quaternion_norm = math.sqrt(
                sum(
                    computed_pose[field] ** 2
                    for field in ("qx", "qy", "qz", "qw")
                )
            )
            if not math.isfinite(quaternion_norm) or quaternion_norm <= 1e-12:
                raise ValueError("computed quaternion is invalid")
            for field in ("qx", "qy", "qz", "qw"):
                computed_pose[field] /= quaternion_norm
            computed_position_m = {
                field: computed_pose[field] for field in ("x", "y", "z")
            }
            computed_at = float(resolved["computed_at"])
            computed_pose_delta_m = {
                field: float(pose[field]) - computed_position_m[field]
                for field in ("x", "y", "z")
            }
        except (KeyError, TypeError, ValueError):
            return {
                "success": False,
                "message": (
                    f"The computed pose for {function_name}.{step_key} is invalid. "
                    "No pose was buffered."
                ),
                "readiness": readiness,
            }
        relative_pose = self._robot_function_pose_relative_to_reference(
            computed_pose,
            pose,
        )
        if not relative_pose:
            return {
                "success": False,
                "message": (
                    f"The Cartesian correction for {function_name}.{step_key} is invalid. "
                    "No pose was buffered."
                ),
                "readiness": readiness,
            }
        reconstructed_pose = self._robot_function_pose_from_reference(
            computed_pose,
            relative_pose,
        )
        try:
            captured_quaternion = tuple(
                float(pose[field]) for field in ("qx", "qy", "qz", "qw")
            )
            captured_quaternion_norm = math.sqrt(
                sum(value * value for value in captured_quaternion)
            )
            reconstructed_alignment = abs(
                sum(
                    reconstructed_pose[field]
                    * captured_quaternion[index]
                    / captured_quaternion_norm
                    for index, field in enumerate(("qx", "qy", "qz", "qw"))
                )
            )
        except (KeyError, TypeError, ValueError, ZeroDivisionError):
            reconstructed_alignment = -1.0
        if (
            not reconstructed_pose
            or any(
                abs(reconstructed_pose[field] - float(pose[field])) > 1e-6
                for field in ("x", "y", "z")
            )
            or 1.0 - reconstructed_alignment > 1e-6
        ):
            return {
                "success": False,
                "message": (
                    f"The full computed_pose and relative_pose do not reconstruct the "
                    f"captured waypoint for {function_name}.{step_key}. No pose was "
                    "buffered."
                ),
                "readiness": readiness,
            }
        if not all(
            math.isfinite(value)
            for value in (
                *computed_position_m.values(),
                *computed_pose_delta_m.values(),
                computed_at,
            )
        ):
            return {
                "success": False,
                "message": (
                    f"The computed pose for {function_name}.{step_key} is not finite. "
                    "No pose was buffered."
                ),
                "readiness": readiness,
            }
        largest_axis = max(
            computed_pose_delta_m,
            key=lambda field: abs(computed_pose_delta_m[field]),
        )
        largest_axis_offset_m = abs(computed_pose_delta_m[largest_axis])
        if (
            function_name != "place_approach"
            and largest_axis_offset_m > _ROBOT_FUNCTION_CAPTURE_MAX_AXIS_OFFSET_M
        ):
            offset_mm = {
                field: computed_pose_delta_m[field] * 1000.0
                for field in ("x", "y", "z")
            }
            return {
                "success": False,
                "message": (
                    f"Capture Pose did not buffer {function_name}.{step_key}: the current "
                    f"world -> {pose.get('child_frame_id') or 'ee_link'} pose is not "
                    "near its freshly computed pose. "
                    f"Offset X={offset_mm['x']:+.1f} mm, Y={offset_mm['y']:+.1f} mm, "
                    f"Z={offset_mm['z']:+.1f} mm; {largest_axis.upper()} exceeds the "
                    f"{_ROBOT_FUNCTION_CAPTURE_MAX_AXIS_OFFSET_M * 1000.0:.0f} mm "
                    "calibration limit. Move or Test Position at the computed pose, jog the "
                    "small correction, then Capture Pose again. No pose was buffered and the "
                    "existing saved pose is unchanged."
                ),
                "computed_position_m": computed_position_m,
                "current_position_m": {
                    field: float(pose[field]) for field in ("x", "y", "z")
                },
                "relative_position_m": computed_pose_delta_m,
                "readiness": readiness,
            }
        relative_position_m = computed_pose_delta_m
        step = {
            "step_name": step_key,
            "primitive": primitive,
            "params": params,
            "capture_source": source,
            "captured_at": time.time(),
            "position_sources": {
                "x": "captured_relative",
                "y": "captured_relative",
                "z": "captured_relative",
            },
            "relative_position_m": relative_position_m,
            "relative_reference": relative_reference,
            "computed_position_m": computed_position_m,
            "computed_pose": computed_pose,
            "computed_source": str(resolved.get("computed_source") or "capture"),
            "computed_at": computed_at,
            "confirmed": False,
            "waypoint": {
                "joint_names": list(waypoint.get("joint_names") or []),
                "joint_positions": [float(v) for v in (waypoint.get("positions") or [])],
                "pose": pose,
                "gripper_joint": waypoint.get("gripper_joint"),
                "gripper_position": waypoint.get("gripper"),
                "source": source,
            },
        }
        step["relative_pose"] = relative_pose
        with self._digital_twin_record_lock:
            steps = self._digital_twin_function_steps.setdefault(key, [])
            steps[:] = [item for item in steps if str(item.get("step_name") or "") != step_key]
            steps.append(step)
            order = {
                str(item.get("step_name") or ""): index
                for index, item in enumerate(self.digital_twin_function_template(function_name))
            }
            steps.sort(key=lambda item: order.get(str(item.get("step_name") or ""), len(order)))
            count = len(steps)
        return {
            "success": True,
            "message": (
                f"captured robot pose for {robot_key} {function_name}.{step['step_name']} "
                "relative to its computed pose with correction "
                f"X={relative_position_m['x'] * 1000.0:+.1f} mm, "
                f"Y={relative_position_m['y'] * 1000.0:+.1f} mm, "
                f"Z={relative_position_m['z'] * 1000.0:+.1f} mm; use Save/Replace Pose "
                "to persist it"
            ),
            "count": count,
            "computed_position_m": computed_position_m,
            "computed_pose": computed_pose,
            "current_position_m": {
                field: float(pose[field]) for field in ("x", "y", "z")
            },
            "relative_position_m": relative_position_m,
            "relative_pose": relative_pose,
            "step": deepcopy(step),
            "readiness": readiness,
        }

    def digital_twin_add_function_event(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        primitive: str = "release_part",
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        step_key = self._robot_function_safe_name(step_name)
        primitive = str(primitive or "release_part").strip()
        template_step = self._robot_function_template_step(function_name, step_key)
        if template_step is None:
            return {"success": False, "message": f"unknown step: {function_name}.{step_key}"}
        expected_primitive = str(template_step.get("primitive") or "")
        if primitive != expected_primitive:
            return {
                "success": False,
                "message": (
                    f"primitive mismatch for {function_name}.{step_key}: "
                    f"expected {expected_primitive}, got {primitive}"
                ),
            }
        if primitive not in self._ROBOT_FUNCTION_EVENT_PRIMITIVES:
            return {
                "success": False,
                "message": f"{step_key} is a waypoint step; use Capture Pose.",
            }
        robot_key = str(robot or "").strip().lower()
        step = {
            "step_name": step_key,
            "primitive": primitive,
            "capture_source": self._robot_function_capture_source(target, cfg),
            "captured_at": time.time(),
        }
        key = self._robot_function_buffer_key(
            target,
            robot_key,
            self._robot_function_safe_function_name(function_name),
            self._robot_function_safe_name(name),
            str(part_name or "").strip(),
        )
        with self._digital_twin_record_lock:
            steps = self._digital_twin_function_steps.setdefault(key, [])
            steps.append(step)
            count = len(steps)
        return {
            "success": True,
            "message": f"added {step['step_name']} for {robot_key} {function_name}",
            "count": count,
        }

    def _robot_function_payload(
        self,
        target: str,
        cfg: dict[str, Any],
        robot: str,
        function_name: str,
        name: str,
        steps: list[dict[str, Any]],
        *,
        part_name: str = "",
        existing_payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        storage_source = self._robot_function_storage_source(target, cfg)
        replay_targets = ["gazebo"] if storage_source == "gazebo" else ["hardware", "digital_twin"]
        capture_source = self._robot_function_capture_source(target, cfg)
        for step in steps:
            waypoint = dict(step.get("waypoint") or {})
            if waypoint.get("source"):
                capture_source = str(waypoint.get("source") or capture_source)
                break
        robot_key = str(robot or "").strip().lower()
        function_key = self._robot_function_safe_function_name(function_name)
        if function_key in {
            "pick_approach",
            "place_approach",
        }:
            payload = deepcopy(dict(existing_payload or {}))
            payload.update(
                {
                    "function_name": function_key,
                    "capture_source": capture_source,
                    "replay_targets": replay_targets,
                }
            )
            payload.pop("robot", None)
            payload.pop("name", None)
            payload.pop("part_name", None)
            resource_agent = self._physical_robot_agent(robot_key)
            controller = getattr(resource_agent, "_controller", None)
            controller_config = dict(
                getattr(resource_agent, "controller_config", {})
                or getattr(controller, "controller_config", {})
                or {}
            )
            move_group = dict(controller_config.get("move_group") or {})
            first_pose = next(
                (
                    dict(dict(step.get("waypoint") or {}).get("pose") or {})
                    for step in steps
                    if dict(dict(step.get("waypoint") or {}).get("pose") or {})
                ),
                {},
            )
            frame_id = str(
                getattr(controller, "frame_id", "")
                or move_group.get("frame_id")
                or first_pose.get("frame_id")
                or "world"
            ).strip()
            ee_link = str(
                getattr(controller, "ee_link", "")
                or move_group.get("ee_link")
                or first_pose.get("child_frame_id")
            ).strip()
            tcp_link = str(
                getattr(controller, "tcp_link", "")
                or move_group.get("tcp_link")
                or ee_link
            ).strip()
            robots = dict(payload.get("robots") or {})
            robots[robot_key] = {
                "frame_id": frame_id,
                "ee_link": ee_link,
                "tcp_link": tcp_link,
                "steps": deepcopy(steps),
            }
            payload["robots"] = robots
            return payload
        return {
            "robot": robot_key,
            "function_name": function_key,
            "name": str(name or "").strip() or "default",
            "capture_source": capture_source,
            "replay_targets": replay_targets,
            "steps": deepcopy(steps),
        }

    def _refresh_retained_place_approach_descend_after_save(
        self,
        *,
        robot: str,
        function_name: str,
        name: str,
        part_name: str,
        captured: dict[str, Any],
    ) -> bool:
        """Refresh one active UR5e place context after replacing ``descend``.

        Saving a replacement waypoint commands no motion. When the exact held-part
        context is still positioned, the captured hardware pose becomes the repeat
        ``place_approach`` start pose immediately. Board and ``move_insert`` fields
        remain invalid until that repeat finishes.
        """
        if (
            robot != "ur5e"
            or function_name != "place_approach"
            or name != "assembly_board-v1"
            or not part_name
            or str(captured.get("capture_source") or "") != "hardware"
        ):
            return False
        resource_agent = self._physical_ur5e_robot_agent()
        if (
            resource_agent is None
            or str(getattr(resource_agent, "execution_mode", "") or "")
            != "physical"
            or str(getattr(resource_agent, "_current_state", "") or "")
            != "positioned"
            or str(getattr(resource_agent, "_held_part", "") or "")
            != part_name
            or str(getattr(resource_agent, "_gripper_state", "") or "")
            != "closed"
        ):
            return False

        task_context = deepcopy(
            dict(getattr(resource_agent, "_task_ctx", {}) or {})
        )
        if (
            str(task_context.get("destination_location") or "") != name
            or str(task_context.get("part_name") or "") != part_name
            or self._physical_ur5e_place_approach_handoff_error(
                task_context,
                part_name=part_name,
            )
        ):
            return False
        retained_results = (
            task_context.get("move_insert_result"),
            task_context.get("move_insert_trial_result"),
        )
        if any(
            isinstance(result, dict)
            and (
                result.get("state_uncertain") is True
                or result.get("engagement_detected") is True
                or result.get("seated_detected") is True
            )
            for result in retained_results
        ):
            return False

        waypoint = dict(captured.get("waypoint") or {})
        raw_pose = dict(waypoint.get("pose") or {})
        if (
            str(waypoint.get("source") or "") != "hardware"
            or str(raw_pose.get("frame_id") or "") != "world"
            or str(raw_pose.get("child_frame_id") or "") != "tool0"
        ):
            return False
        descend, pose_error = self._insertion_demonstration_pose(
            raw_pose,
            label="saved place_approach.descend world -> tool0 pose",
        )
        if pose_error:
            return False

        retained_positions = deepcopy(
            dict(task_context.get("resolved_cartesian_positions") or {})
        )
        retained_positions["descend"] = descend
        retained_positions.pop("move_insert", None)
        task_context["resolved_cartesian_positions"] = retained_positions
        task_context["pre_insert_pose"] = deepcopy(descend)
        for stale_field in (
            "computed_cartesian_positions",
            "computed_cartesian_reference",
            "computed_cartesian_at",
            "assembly_board_v1_aruco",
            "assembly_board_v1_aruco_generation",
            "move_insert_profile",
            "move_insert_profile_sha256",
            "move_insert_mode",
            "move_insert_timeout_sec",
            "insert_pose",
            "insertion_axis_world",
            "move_insert_hard_caps",
            "move_insert_hard_caps_sha256",
            "move_insert_boundary_ready",
            "move_insert_boundary_error",
            "move_insert_boundary_metrics",
            "move_insert_qualification_error",
        ):
            task_context.pop(stale_field, None)
        resource_agent._task_ctx = task_context
        return True

    def digital_twin_save_function(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        if not str(name or "").strip():
            location_argument = self.digital_twin_function_location_argument(function_name)
            return {
                "success": False,
                "message": f"{location_argument or 'location'} is empty",
            }
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        safe_name = self._robot_function_safe_name(name)
        function_key = self._robot_function_safe_function_name(function_name)
        part_key = str(part_name or "").strip()
        key = self._robot_function_buffer_key(
            target,
            robot,
            function_key,
            safe_name,
            part_key,
        )
        with self._digital_twin_record_lock:
            unsaved_steps = deepcopy(list(self._digital_twin_function_steps.get(key, [])))
        for step in unsaved_steps:
            step["confirmed"] = True
        storage_source = self._robot_function_storage_source(target, cfg)
        path = self._robot_function_path(
            robot,
            function_key,
            safe_name,
            storage_source,
            part_key,
        )
        saved_steps: list[dict[str, Any]] = []
        existing_payload: dict[str, Any] = {}
        if path.is_file():
            try:
                existing = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(existing, dict):
                    existing_payload = dict(existing)
                    identity_error = self._robot_function_payload_identity_error(
                        existing,
                        function_key,
                        name,
                        part_key,
                        robot=robot,
                    )
                    if identity_error:
                        return {"success": False, "message": identity_error}
                    saved_steps = deepcopy(
                        self._robot_function_payload_steps(existing, function_key, robot)
                    )
            except (OSError, json.JSONDecodeError, TypeError):
                saved_steps = []
        by_step_name: dict[str, dict[str, Any]] = {}
        for step in [*saved_steps, *unsaved_steps]:
            step_name = str(dict(step).get("step_name") or "").strip()
            if step_name:
                by_step_name[step_name] = deepcopy(dict(step))
        order = {
            str(step.get("step_name") or ""): index
            for index, step in enumerate(self.digital_twin_function_template(function_key))
        }
        steps = sorted(
            by_step_name.values(),
            key=lambda step: order.get(str(step.get("step_name") or ""), len(order)),
        )
        if not steps:
            return {"success": False, "message": "no function steps captured."}
        payload = self._robot_function_payload(
            target,
            cfg,
            robot,
            function_key,
            str(name or "").strip(),
            steps,
            part_name=part_key,
            existing_payload=existing_payload,
        )
        atomic_json_write(path, payload)
        with self._digital_twin_record_lock:
            self._digital_twin_function_steps.pop(key, None)
        refreshed_descend = False
        saved_descend = next(
            (
                dict(step)
                for step in unsaved_steps
                if str(dict(step).get("step_name") or "") == "descend"
            ),
            None,
        )
        if saved_descend is not None:
            refreshed_descend = (
                self._refresh_retained_place_approach_descend_after_save(
                    robot=str(robot or ""),
                    function_name=function_key,
                    name=str(name or ""),
                    part_name=part_key,
                    captured=saved_descend,
                )
            )
        return {
            "success": True,
            "message": (
                f"saved or replaced {len(unsaved_steps)} position(s) in "
                f"{self._robot_function_display_path(path)}"
                + (
                    "; refreshed the retained place_approach.descend. Run "
                    "place_approach before place_insert."
                    if refreshed_descend
                    else ""
                )
            ),
            "file": str(path),
            "display_path": self._robot_function_display_path(path),
            "saved_steps": len(steps),
            "unsaved_steps": 0,
            "retained_descend_refreshed": refreshed_descend,
        }

    def digital_twin_save_function_position(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        """Save or replace one captured predefined physical position."""
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        if not str(name or "").strip():
            location_argument = self.digital_twin_function_location_argument(function_name)
            return {
                "success": False,
                "message": f"{location_argument or 'location'} is empty",
            }
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        safe_name = self._robot_function_safe_name(name)
        function_key = self._robot_function_safe_function_name(function_name)
        step_key = str(step_name or "").strip()
        part_key = str(part_name or "").strip()
        key = self._robot_function_buffer_key(
            target,
            robot,
            function_key,
            safe_name,
            part_key,
        )
        with self._digital_twin_record_lock:
            buffered = deepcopy(list(self._digital_twin_function_steps.get(key, [])))
        captured = next(
            (dict(step) for step in buffered if str(dict(step).get("step_name") or "") == step_key),
            None,
        )
        if captured is None:
            return {
                "success": False,
                "message": f"Capture {function_key}.{step_key} before saving it.",
            }
        captured["confirmed"] = True

        storage_source = self._robot_function_storage_source(target, cfg)
        path = self._robot_function_path(
            robot,
            function_key,
            safe_name,
            storage_source,
            part_key,
        )
        existing_steps: list[dict[str, Any]] = []
        existing_payload: dict[str, Any] = {}
        if path.is_file():
            try:
                existing = json.loads(path.read_text(encoding="utf-8"))
                existing_payload = dict(existing)
                identity_error = self._robot_function_payload_identity_error(
                    dict(existing),
                    function_key,
                    name,
                    part_key,
                    robot=robot,
                )
                if identity_error:
                    return {"success": False, "message": identity_error}
                existing_steps = self._robot_function_payload_steps(
                    dict(existing),
                    function_key,
                    robot,
                )
            except (OSError, json.JSONDecodeError) as exc:
                return {"success": False, "message": f"could not read {path.name}: {exc}"}
        by_step_name = {
            str(step.get("step_name") or ""): step
            for step in existing_steps
            if str(step.get("step_name") or "").strip()
        }
        by_step_name[step_key] = captured
        order = {
            str(step.get("step_name") or ""): index
            for index, step in enumerate(self.digital_twin_function_template(function_key))
        }
        steps = sorted(
            by_step_name.values(),
            key=lambda step: order.get(str(step.get("step_name") or ""), len(order)),
        )
        payload = self._robot_function_payload(
            target,
            cfg,
            robot,
            function_key,
            str(name or "").strip(),
            steps,
            part_name=part_key,
            existing_payload=existing_payload,
        )
        atomic_json_write(path, payload)
        with self._digital_twin_record_lock:
            remaining = [
                step
                for step in self._digital_twin_function_steps.get(key, [])
                if str(step.get("step_name") or "") != step_key
            ]
            if remaining:
                self._digital_twin_function_steps[key] = remaining
            else:
                self._digital_twin_function_steps.pop(key, None)
        refreshed_descend = bool(
            step_key == "descend"
            and self._refresh_retained_place_approach_descend_after_save(
                robot=str(robot or ""),
                function_name=function_key,
                name=str(name or ""),
                part_name=part_key,
                captured=captured,
            )
        )
        return {
            "success": True,
            "message": (
                f"saved or replaced {function_key}.{step_key} in "
                f"{self._robot_function_display_path(path)}"
                + (
                    "; refreshed the retained place_approach.descend. Run "
                    "place_approach before place_insert."
                    if refreshed_descend
                    else ""
                )
            ),
            "file": str(path),
            "display_path": self._robot_function_display_path(path),
            "saved_steps": len(steps),
            "retained_descend_refreshed": refreshed_descend,
        }

    def digital_twin_update_function_position_axes(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        position_sources: dict[str, str],
        manual_position_m: dict[str, float],
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        """Update one captured Cartesian step's per-axis source without robot motion."""
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        step_key = str(step_name or "").strip()
        template_step = self._robot_function_template_step(function_name, step_key)
        if template_step is None or not bool(template_step.get("recordable")):
            return {
                "success": False,
                "message": f"{function_name}.{step_key} is not a move_cartesian step.",
            }
        if self._robot_function_safe_function_name(function_name) in {
            "pick_approach",
            "place_approach",
        }:
            return {
                "success": False,
                "message": (
                    f"{function_name} uses a computed Cartesian target plus an optional "
                    "captured robot correction. Capture Pose again instead of editing "
                    "absolute position axes."
                ),
            }
        sources = {
            field: str(dict(position_sources or {}).get(field) or "").strip()
            for field in ("x", "y", "z")
        }
        invalid_sources = [
            field
            for field, source in sources.items()
            if source not in {"computed", "captured", "manual"}
        ]
        if invalid_sources:
            return {
                "success": False,
                "message": "position source must be computed, captured, or manual for "
                + ", ".join(invalid_sources),
            }
        manual: dict[str, float] = {}
        for field, source in sources.items():
            if source != "manual":
                continue
            try:
                value = float(dict(manual_position_m or {})[field])
            except (KeyError, TypeError, ValueError):
                return {
                    "success": False,
                    "message": f"manual position is missing for {function_name}.{step_key}.{field}",
                }
            if not math.isfinite(value):
                return {
                    "success": False,
                    "message": f"manual position is not finite for {function_name}.{step_key}.{field}",
                }
            manual[field] = value

        function_key = self._robot_function_safe_function_name(function_name)
        safe_name = self._robot_function_safe_name(name)
        part_key = str(part_name or "").strip()
        key = self._robot_function_buffer_key(
            target,
            robot,
            function_key,
            safe_name,
            part_key,
        )
        with self._digital_twin_record_lock:
            buffered = deepcopy(list(self._digital_twin_function_steps.get(key, [])))
        step = next(
            (item for item in buffered if str(item.get("step_name") or "") == step_key),
            None,
        )
        if step is None:
            storage_source = self._robot_function_storage_source(target, cfg)
            path = self._robot_function_path(
                robot,
                function_key,
                safe_name,
                storage_source,
                part_key,
            )
            payload = self._read_json_file(path)
            if payload:
                identity_error = self._robot_function_payload_identity_error(
                    payload,
                    function_key,
                    name,
                    part_key,
                    robot=robot,
                )
                if identity_error:
                    return {"success": False, "message": identity_error}
            step = next(
                (
                    dict(item)
                    for item in self._robot_function_payload_steps(
                        payload,
                        function_key,
                        robot,
                    )
                    if str(dict(item).get("step_name") or "") == step_key
                ),
                None,
            )
        if step is None:
            return {
                "success": False,
                "message": f"Capture {function_key}.{step_key} before editing its axes.",
            }
        step = deepcopy(step)
        step["position_sources"] = sources
        step["manual_position_m"] = manual
        step["edited_at"] = time.time()
        with self._digital_twin_record_lock:
            steps = self._digital_twin_function_steps.setdefault(key, [])
            steps[:] = [
                item for item in steps if str(item.get("step_name") or "") != step_key
            ]
            steps.append(step)
            order = {
                str(item.get("step_name") or ""): index
                for index, item in enumerate(
                    self.digital_twin_function_template(function_key)
                )
            }
            steps.sort(
                key=lambda item: order.get(
                    str(item.get("step_name") or ""), len(order)
                )
            )
        return {
            "success": True,
            "message": f"updated {function_key}.{step_key}; use Save/Replace Pose to persist it.",
            "step": deepcopy(step),
        }

    def digital_twin_clear_function_position(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        """Clear one exact predefined physical position from memory and disk."""
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        if not str(name or "").strip():
            location_argument = self.digital_twin_function_location_argument(function_name)
            return {
                "success": False,
                "message": f"{location_argument or 'location'} is empty",
            }
        step_key = str(step_name or "").strip()
        template_step = self._robot_function_template_step(function_name, step_key)
        if template_step is None or not bool(template_step.get("recordable")):
            return {
                "success": False,
                "message": f"{function_name}.{step_key} does not have a physical position.",
            }
        safe_name = self._robot_function_safe_name(name)
        function_key = self._robot_function_safe_function_name(function_name)
        part_key = str(part_name or "").strip()
        key = self._robot_function_buffer_key(
            target,
            robot,
            function_key,
            safe_name,
            part_key,
        )
        removed = False
        with self._digital_twin_record_lock:
            buffered = self._digital_twin_function_steps.get(key, [])
            remaining_buffer = [
                step for step in buffered if str(step.get("step_name") or "") != step_key
            ]
            removed = len(remaining_buffer) != len(buffered)
            if remaining_buffer:
                self._digital_twin_function_steps[key] = remaining_buffer
            else:
                self._digital_twin_function_steps.pop(key, None)

        storage_source = self._robot_function_storage_source(target, cfg)
        path = self._robot_function_path(
            robot,
            function_key,
            safe_name,
            storage_source,
            part_key,
        )
        if path.is_file():
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError) as exc:
                return {"success": False, "message": f"could not read {path.name}: {exc}"}
            identity_error = self._robot_function_payload_identity_error(
                dict(payload),
                function_key,
                name,
                part_key,
                robot=robot,
            )
            if identity_error:
                return {"success": False, "message": identity_error}
            saved_steps = self._robot_function_payload_steps(
                dict(payload),
                function_key,
                robot,
            )
            steps = [
                dict(step)
                for step in saved_steps
                if str(dict(step).get("step_name") or "") != step_key
            ]
            removed = removed or len(steps) != len(saved_steps)
            if function_key in {"pick_approach", "place_approach"}:
                robots = dict(dict(payload).get("robots") or {})
                robot_key = str(robot or "").strip().lower()
                entry = dict(robots.get(robot_key) or {})
                if steps:
                    entry["steps"] = steps
                    robots[robot_key] = entry
                else:
                    robots.pop(robot_key, None)
                if robots:
                    payload["robots"] = robots
                    atomic_json_write(path, payload)
                else:
                    path.unlink(missing_ok=True)
            elif steps:
                payload["steps"] = steps
                atomic_json_write(path, payload)
            else:
                path.unlink(missing_ok=True)
        if not removed:
            return {"success": False, "message": f"{function_name}.{step_key} is not saved."}
        return {
            "success": True,
            "message": f"cleared {function_name}.{step_key} for {safe_name}",
        }

    def _resolve_robot_function_position(  # noqa: C901, PLR0912
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        *,
        part_name: str = "",
        readiness: dict[str, Any] | None = None,
        resource_agent: Any | None = None,
        computed_source: str = "resolve",
    ) -> dict[str, Any]:
        """Resolve one taught Cartesian step from one read-only robot snapshot."""
        cfg, request_error = self._robot_function_validate_request(
            target, robot, function_name
        )
        if request_error or cfg is None:
            return {"success": False, "message": request_error}
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        robot_key = str(robot or "").strip().lower()
        if resource_agent is None:
            resource_agent = self._physical_robot_agent(robot_key)
        if resource_agent is None:
            return {
                "success": False,
                "message": (
                    f"Prepare the physical {robot_key} Function Execution runtime before "
                    "resolving a position."
                ),
            }
        if (
            str(getattr(resource_agent, "execution_mode", "") or "").strip().lower()
            != "physical"
        ):
            return {
                "success": False,
                "message": (
                    f"The prepared {robot_key} Function Execution runtime is not in Physical mode."
                ),
            }
        if getattr(resource_agent, "_controller", None) is None:
            return {
                "success": False,
                "message": f"The physical {robot_key} controller is unavailable.",
            }

        from cais_spade_llm.resources.robot.robot_task_runtime import (  # noqa: PLC0415
            _apply_cartesian_overrides_to_targets,
            _load_physical_cartesian_overrides,
            _normalize_pick_targets,
            _normalize_place_targets,
        )

        cartesian_error = self._physical_robot_function_cartesian_error(robot_key)
        if cartesian_error:
            return {"success": False, "message": cartesian_error}
        uncertain_attribute = {
            "ur5e": "_ur5e_robot_function_state_uncertain",
            "xarm6": "_xarm6_robot_function_state_uncertain",
        }.get(robot_key)
        state_uncertain = bool(
            getattr(self, uncertain_attribute, False) if uncertain_attribute else False
        )
        if state_uncertain:
            return {
                "success": False,
                "message": (
                    f"The physical {robot_key} state is uncertain. Inspect the robot and "
                    "complete Robot Functions -> move_home before resolving a position."
                ),
            }
        readiness = (
            deepcopy(readiness)
            if readiness is not None
            else self._robot_function_capture_snapshot(target, robot_key)
        )
        if not readiness.get("success"):
            return {
                "success": False,
                "message": str(
                    readiness.get("blocked_reason")
                    or f"{robot_key} feedback or TF is not ready"
                ),
                "readiness": readiness,
            }

        task = self._robot_task_registry().get(str(function_name or "").strip())
        step_key = str(step_name or "").strip()
        if task is None:
            return {"success": False, "message": f"unknown robot function: {function_name}"}
        cartesian_steps = [step for step in task.program.steps if step.op == "move_cartesian"]
        template_step = next((step for step in cartesian_steps if step.id == step_key), None)
        if template_step is None:
            return {
                "success": False,
                "message": f"{function_name}.{step_key} is not a move_cartesian step.",
            }
        location_argument = self.digital_twin_function_location_argument(function_name)
        recording_args = {location_argument: str(name).strip(), "part_name": part_name}
        overrides, path, recording_error = _load_physical_cartesian_overrides(
            agent=resource_agent,
            task=task,
            args=recording_args,
            allow_missing=True,
        )
        if recording_error:
            return {"success": False, "message": recording_error}
        override = overrides.get(step_key)

        if function_name == "pick_approach":
            reference_result = self._robot_function_relative_reference(
                resource_agent=resource_agent,
                function_name=function_name,
                name=name,
                step_name=step_key,
                part_name=str(part_name or "").strip(),
                robot=robot_key,
                computed_source=computed_source,
            )
            if not reference_result.get("success"):
                return dict(reference_result)
            targets = _normalize_pick_targets(
                dict(reference_result.get("computed") or {})
            )
            step_outputs = {"pick_targets": targets}
        elif function_name == "place_approach":
            reference_result = self._robot_function_relative_reference(
                resource_agent=resource_agent,
                function_name=function_name,
                name=name,
                step_name=step_key,
                part_name=str(part_name or "").strip(),
                robot=robot_key,
                computed_source=computed_source,
            )
            if not reference_result.get("success"):
                return dict(reference_result)
            computed = dict(reference_result.get("computed") or {})
            targets = _normalize_place_targets(
                computed,
                runtime_state={
                    "_task_ctx": deepcopy(
                        getattr(resource_agent, "_task_ctx", {}) or {}
                    )
                },
            )
            step_outputs = {
                "place_targets": targets,
                "assembly_board_v1_aruco": deepcopy(
                    reference_result.get("assembly_board_v1_aruco") or {}
                ),
            }
        else:
            return {
                "success": False,
                "message": f"{function_name} has no computed Cartesian target.",
            }
        step_index = cartesian_steps.index(template_step)
        pose_key = "approach_pose" if step_index == 0 else "target_pose"
        computed_position = dict(targets.get(pose_key) or {})
        computed_at = time.time()
        baseline = self._cache_robot_function_computed_pose(
            target=target,
            robot=robot_key,
            function_name=function_name,
            name=name,
            part_name=str(part_name or "").strip(),
            step_name=step_key,
            computed_position=computed_position,
            relative_reference=dict(reference_result.get("reference") or {}),
            computed_source=computed_source,
            computed_at=computed_at,
            computed_provenance=self._robot_function_computed_pose_provenance(
                target=target,
                robot=robot_key,
                function_name=function_name,
                name=name,
                part_name=str(part_name or "").strip(),
                step_name=step_key,
                readiness=readiness,
            ),
        )
        if not baseline:
            return {
                "success": False,
                "message": f"computed pose is invalid for {function_name}.{step_key}",
            }
        validation_error = ""
        if computed_source != "capture":
            validation_error = _apply_cartesian_overrides_to_targets(
                task=task,
                physical_overrides=overrides,
                step_outputs=step_outputs,
                agent=resource_agent,
            )
        if validation_error:
            return {
                "success": False,
                "message": validation_error,
                "physical_position_file": str(path or ""),
            }
        resolved = dict(targets.get(pose_key) or {})
        if not all(
            isinstance(resolved.get(field), (int, float))
            and math.isfinite(float(resolved[field]))
            for field in ("x", "y", "z")
        ):
            return {
                "success": False,
                "message": f"resolved position is invalid for {function_name}.{step_key}",
            }
        resolved_position = {
            field: float(resolved[field]) for field in ("x", "y", "z")
        }
        orientation_source = dict(
            (override or {}).get("captured_pose") or computed_position
        )
        for field in ("qx", "qy", "qz", "qw"):
            try:
                value = float(orientation_source[field])
            except (KeyError, TypeError, ValueError):
                continue
            if math.isfinite(value):
                resolved_position[field] = value
        return {
            "success": True,
            "message": (
                f"resolved computed and saved pose for {function_name}.{step_key}; "
                "no robot motion was requested."
            ),
            "computed_position": deepcopy(baseline.get("computed_pose") or {}),
            "computed_source": computed_source,
            "computed_at": computed_at,
            "computed_reference": deepcopy(
                baseline.get("relative_reference") or {}
            ),
            "resolved_position": resolved_position,
            "position_sources": deepcopy((override or {}).get("position_sources") or {}),
            "relative_position_m": deepcopy(
                (override or {}).get("relative_position_m") or {}
            ),
            "relative_reference": deepcopy(
                (override or {}).get("relative_reference") or {}
            ),
            "resolved_reference_position_m": deepcopy(
                (override or {}).get("resolved_reference_position_m") or {}
            ),
            "resolved_computed_position_m": deepcopy(
                (override or {}).get("resolved_computed_position_m") or {}
            ),
            "saved_computed_position_m": deepcopy(
                (override or {}).get("computed_position_m") or {}
            ),
            "captured_pose": deepcopy((override or {}).get("captured_pose") or {}),
            "physical_position_file": str(path or ""),
            "diagnostics": {
                key: targets.get(key)
                for key in (
                    "finger_tooth_clearance_m",
                    "finger_hub_overlap_m",
                    "resolved_taught_tool0_z_m",
                )
                if targets.get(key) is not None
            },
        }

    def digital_twin_preview_function_position(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        """Compatibility wrapper for read-only Cartesian position resolution."""
        return self._resolve_robot_function_position(
            target,
            robot,
            function_name,
            name,
            step_name,
            part_name=part_name,
            computed_source="preview",
        )

    def digital_twin_test_function_position(  # noqa: C901, PLR0912
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_name: str,
        *,
        confirmed: bool = False,
        part_name: str = "",
    ) -> dict[str, Any]:
        """Execute one saved position through the active physical move_cartesian primitive."""
        cfg, request_error = self._robot_function_validate_request(
            target,
            robot,
            function_name,
        )
        if request_error or cfg is None:
            return {"success": False, "message": request_error}
        if not confirmed:
            return {"success": False, "message": "Explicit motion confirmation is required."}
        if not str(name or "").strip():
            location_argument = self.digital_twin_function_location_argument(function_name)
            return {
                "success": False,
                "message": f"{location_argument or 'location'} is empty",
            }
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        robot_key = str(robot or "").strip().lower()
        if robot_key == "xarm6" and self._xarm6_cartesian_session_mode() != "off":
            closed, close_message = self.teleop_cartesian_mode("xarm6", "off")
            if not closed:
                return {
                    "success": False,
                    "message": (
                        "xArm6 Cartesian session could not restore Mode 1 before "
                        f"Test Position: {close_message}"
                    ),
                }
        resource_agent = self._physical_robot_agent(robot_key)
        if resource_agent is None:
            return {
                "success": False,
                "message": (
                    f"Prepare the physical {robot_key} Function Execution runtime before "
                    "testing motion."
                ),
            }
        if (
            str(getattr(resource_agent, "execution_mode", "") or "").strip().lower()
            != "physical"
        ):
            return {
                "success": False,
                "message": (
                    f"The prepared {robot_key} Function Execution runtime is not in Physical mode."
                ),
            }
        if getattr(resource_agent, "_controller", None) is None:
            return {
                "success": False,
                "message": f"The physical {robot_key} controller is unavailable.",
            }
        target_error = self._digital_twin_robot_function_target_error(target, cfg)
        if target_error:
            return {"success": False, "message": target_error}
        cartesian_error = self._physical_robot_function_cartesian_error(robot_key)
        if cartesian_error:
            return {"success": False, "message": cartesian_error}

        task = self._robot_task_registry().get(function_name)
        step_key = str(step_name or "").strip()
        if task is None:
            return {"success": False, "message": f"unknown robot function: {function_name}"}
        template_step = next((step for step in task.program.steps if step.id == step_key), None)
        if template_step is None or template_step.op != "move_cartesian":
            return {
                "success": False,
                "message": f"{function_name}.{step_key} is not a move_cartesian step.",
            }
        resolved = self._resolve_robot_function_position(
            target,
            robot,
            function_name,
            name,
            step_key,
            part_name=part_name,
            resource_agent=resource_agent,
            computed_source="test_position",
        )
        if not resolved.get("success"):
            return dict(resolved)
        params = dict(resolved.get("resolved_position") or {})

        if robot_key == "ur5e":
            motion_readiness, motion_error = self._digital_twin_ur5e_motion_readiness(
                target,
                cfg,
                resource_agent,
            )
        elif robot_key == "xarm6":
            motion_readiness, motion_error = self._digital_twin_xarm6_motion_readiness(
                target,
                cfg,
                resource_agent,
            )
        else:
            controller = getattr(resource_agent, "_controller", None)
            is_usable = getattr(controller, "is_usable", None)
            controller_ready = controller is not None and (
                not callable(is_usable) or bool(is_usable())
            )
            motion_readiness = {"controller_ready": controller_ready}
            motion_error = (
                ""
                if controller_ready
                else f"The physical {robot_key} controller is not ready."
            )
        if motion_error:
            return {"success": False, "message": motion_error, **motion_readiness}
        controller = getattr(resource_agent, "_controller", None)
        move_cartesian = getattr(controller, "move_cartesian", None)
        if not callable(move_cartesian):
            return {
                "success": False,
                "message": "The active physical robot controller is not initialized.",
            }
        execution_lock = self._ur5e_robot_function_execution_lock
        if not execution_lock.acquire(blocking=False):
            active = str(
                self._ur5e_robot_function_execution_active or "Physical robot motion"
            )
            return {
                "success": False,
                "message": f"Physical robot motion is already active: {active}.",
                "active_function": active,
            }
        agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
        agent_lock_acquired = False
        if agent_motion_lock is not None:
            agent_lock_acquired = bool(agent_motion_lock.acquire(blocking=False))
            if not agent_lock_acquired:
                execution_lock.release()
                return {
                    "success": False,
                    "message": (
                        f"The {robot_key} RobotAgent is already executing a robot task."
                    ),
                }
        self._ur5e_robot_function_execution_active = (
            f"{function_name}.{step_name} Test Position"
        )
        try:
            result = move_cartesian(**params)
        except Exception as exc:  # noqa: BLE001 - isolate the physical controller boundary.
            log.exception("physical function position test failed")
            if robot_key == "ur5e":
                self._ur5e_robot_function_state_uncertain = True
            elif robot_key == "xarm6":
                self._xarm6_robot_function_state_uncertain = True
            return {"success": False, "message": str(exc)}
        finally:
            self._ur5e_robot_function_execution_active = None
            if agent_lock_acquired:
                agent_motion_lock.release()
            execution_lock.release()
        normalized_result = dict(result) if isinstance(result, dict) else {
            "success": bool(result),
            "message": f"{function_name}.{step_name} {'completed' if result else 'failed'}",
        }
        if not bool(normalized_result.get("success")):
            if robot_key == "ur5e":
                self._ur5e_robot_function_state_uncertain = True
            elif robot_key == "xarm6":
                self._xarm6_robot_function_state_uncertain = True
        return normalized_result

    def digital_twin_delete_function(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        *,
        part_name: str = "",
    ) -> dict[str, Any]:
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return {"success": False, "message": err}
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return {"success": False, "message": part_error}
        storage_source = self._robot_function_storage_source(target, cfg)
        path = self._robot_function_path(
            robot,
            function_name,
            name,
            storage_source,
            part_name,
        )
        if not path.is_file():
            return {"success": False, "message": f"taught function file not found: {path.name}"}
        payload = self._read_json_file(path)
        identity_error = self._robot_function_payload_identity_error(
            payload,
            function_name,
            name,
            part_name,
            robot=robot,
        )
        if identity_error:
            return {"success": False, "message": identity_error}
        function_key = self._robot_function_safe_function_name(function_name)
        if function_key in {"pick_approach", "place_approach"}:
            robots = dict(payload.get("robots") or {})
            robot_key = str(robot or "").strip().lower()
            if robot_key not in robots:
                return {
                    "success": False,
                    "message": f"{robot_key} has no saved correction for {function_key}.",
                }
            robots.pop(robot_key)
            if robots:
                payload["robots"] = robots
                atomic_json_write(path, payload)
            else:
                path.unlink()
            return {
                "success": True,
                "message": (
                    f"deleted {robot_key} correction from "
                    f"{self._robot_function_display_path(path)}"
                ),
            }
        try:
            path.unlink()
        except Exception as exc:
            return {"success": False, "message": str(exc)}
        return {
            "success": True,
            "message": f"deleted {self._robot_function_display_path(path)}",
        }

    @staticmethod
    def _robot_function_step_waypoint(step: dict[str, Any]) -> dict[str, Any] | None:
        return digital_twin.robot_function_step_waypoint(step)

    def _recording_from_function_payload(
        self,
        target: str,
        payload: dict[str, Any],
        *,
        step_index: int | None = None,
    ) -> dict[str, Any] | None:
        robot = str(payload.get("robot") or "").strip().lower()
        steps = list(payload.get("steps") or [])
        if step_index is not None:
            if not (0 <= int(step_index) < len(steps)):
                return None
            steps = [steps[int(step_index)]]
        waypoints = [
            body
            for body in (self._robot_function_step_waypoint(dict(step)) for step in steps)
            if body is not None
        ]
        if not waypoints:
            return None
        first = dict(waypoints[0])
        return {
            "target": target,
            "robot": robot,
            "recording_type": "single_robot",
            "saved_steps": len(steps),
            "joint_names": list(first.get("joint_names") or []),
            "gripper_joint": first.get("gripper_joint"),
            "recovery_metadata": self._digital_twin_recovery_metadata(
                target,
                recording_type="single_robot",
            ),
            "waypoints": [
                {
                    "positions": list(body.get("positions") or []),
                    **({"gripper": body.get("gripper")} if body.get("gripper") is not None else {}),
                }
                for body in waypoints
            ],
        }

    def _robot_function_file_payload(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        *,
        part_name: str = "",
    ) -> tuple[dict[str, Any] | None, Path | None, str]:
        cfg, err = self._robot_function_validate_request(target, robot, function_name)
        if err or cfg is None:
            return None, None, err
        part_error = self._robot_function_part_name_error(function_name, part_name)
        if part_error:
            return None, None, part_error
        storage_source = self._robot_function_storage_source(target, cfg)
        path = self._robot_function_path(
            robot,
            function_name,
            name,
            storage_source,
            part_name,
        )
        payload = self._read_json_file(path)
        if not payload:
            return (
                None,
                path,
                f"taught function file not found: {self._robot_function_display_path(path)}",
            )
        identity_error = self._robot_function_payload_identity_error(
            payload,
            function_name,
            name,
            part_name,
            robot=robot,
        )
        if identity_error:
            return None, path, identity_error
        return payload, path, ""

    def _single_robot_replay_cfg(self, cfg: dict[str, Any], robot: str) -> dict[str, Any]:
        return digital_twin.single_robot_replay_cfg(cfg, robot)

    def digital_twin_replay_function(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        *,
        part_name: str = "",
        replay_target: str = "twin",
        repeat_count: int = 1,
    ) -> dict[str, Any]:
        if self._robot_function_safe_function_name(function_name) in {
            "pick_approach",
            "place_approach",
        }:
            return {
                "success": False,
                "message": (
                    f"Raw waypoint Replay is disabled for {function_name}; use Preview, "
                    "Test Position, or Function Run so current geometry is resolved."
                ),
            }
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        payload, path, err = self._robot_function_file_payload(
            target,
            robot,
            function_name,
            name,
            part_name=part_name,
        )
        if err or payload is None or path is None:
            return {"success": False, "message": err}
        recording = self._recording_from_function_payload(target, payload)
        if recording is None:
            return {"success": False, "message": "function has no waypoint steps to replay."}
        temp_path = Path("/tmp") / (
            f"cais_digital_twin_function_{self._robot_function_safe_name(robot)}_"
            f"{self._robot_function_safe_name(function_name)}_"
            f"{self._robot_function_safe_name(name)}_"
            f"{self._robot_function_safe_name(part_name) if part_name else 'none'}.json"
        )
        atomic_json_write(temp_path, recording)
        replay_cfg = self._single_robot_replay_cfg(cfg, robot)
        return self._replay_recording_file(
            target,
            replay_cfg,
            temp_path,
            replay_target,
            source=f"function_{robot}_{function_name}_{name}_{part_name or 'none'}",
            repeat_count=repeat_count,
        )

    def digital_twin_replay_function_step(
        self,
        target: str,
        robot: str,
        function_name: str,
        name: str,
        step_index: int,
        *,
        part_name: str = "",
        replay_target: str = "twin",
    ) -> dict[str, Any]:
        if self._robot_function_safe_function_name(function_name) in {
            "pick_approach",
            "place_approach",
        }:
            return {
                "success": False,
                "message": (
                    f"Raw waypoint Replay is disabled for {function_name}; use Preview, "
                    "Test Position, or Function Run so current geometry is resolved."
                ),
            }
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        payload, path, err = self._robot_function_file_payload(
            target,
            robot,
            function_name,
            name,
            part_name=part_name,
        )
        if err or payload is None or path is None:
            return {"success": False, "message": err}
        recording = self._recording_from_function_payload(target, payload, step_index=step_index)
        if recording is None:
            return {"success": False, "message": "selected step has no waypoint to replay."}
        temp_path = Path("/tmp") / (
            f"cais_digital_twin_function_step_{self._robot_function_safe_name(robot)}_"
            f"{self._robot_function_safe_name(function_name)}_"
            f"{self._robot_function_safe_name(name)}_"
            f"{self._robot_function_safe_name(part_name) if part_name else 'none'}_"
            f"{int(step_index)}.json"
        )
        atomic_json_write(temp_path, recording)
        replay_cfg = self._single_robot_replay_cfg(cfg, robot)
        return self._replay_recording_file(
            target,
            replay_cfg,
            temp_path,
            replay_target,
            source=(
                f"function_step_{robot}_{function_name}_{name}_"
                f"{part_name or 'none'}_{int(step_index)}"
            ),
        )

    def _paired_recording_from_function_payloads(
        self,
        target: str,
        xarm6_payload: dict[str, Any],
        ur5e_payload: dict[str, Any],
        *,
        xarm6_step_index: int | None = None,
        ur5e_step_index: int | None = None,
    ) -> dict[str, Any] | None:
        def _waypoints(payload: dict[str, Any], step_index: int | None) -> list[dict[str, Any]]:
            steps = list(payload.get("steps") or [])
            if step_index is not None:
                if not (0 <= int(step_index) < len(steps)):
                    return []
                steps = [steps[int(step_index)]]
            return [
                body
                for body in (self._robot_function_step_waypoint(dict(step)) for step in steps)
                if body is not None
            ]

        xarm6_waypoints = _waypoints(xarm6_payload, xarm6_step_index)
        ur5e_waypoints = _waypoints(ur5e_payload, ur5e_step_index)
        if not xarm6_waypoints or not ur5e_waypoints:
            return None
        count = max(len(xarm6_waypoints), len(ur5e_waypoints))
        first_xarm6 = dict(xarm6_waypoints[0])
        first_ur5e = dict(ur5e_waypoints[0])
        return {
            "target": target,
            "robot": "dual robots",
            "recording_type": "paired_dual_robots",
            "robots": {
                "xarm6": {
                    "joint_names": list(first_xarm6.get("joint_names") or []),
                    "gripper_joint": first_xarm6.get("gripper_joint"),
                },
                "ur5e": {
                    "joint_names": list(first_ur5e.get("joint_names") or []),
                    "gripper_joint": first_ur5e.get("gripper_joint"),
                },
            },
            "recovery_metadata": self._digital_twin_recovery_metadata(
                target,
                recording_type="paired_dual_robots",
            ),
            "waypoints": [
                {
                    "robots": {
                        "xarm6": {
                            "positions": list(
                                xarm6_waypoints[min(i, len(xarm6_waypoints) - 1)].get("positions")
                                or []
                            ),
                            **(
                                {
                                    "gripper": xarm6_waypoints[
                                        min(i, len(xarm6_waypoints) - 1)
                                    ].get("gripper")
                                }
                                if xarm6_waypoints[min(i, len(xarm6_waypoints) - 1)].get("gripper")
                                is not None
                                else {}
                            ),
                        },
                        "ur5e": {
                            "positions": list(
                                ur5e_waypoints[min(i, len(ur5e_waypoints) - 1)].get("positions")
                                or []
                            ),
                            **(
                                {
                                    "gripper": ur5e_waypoints[min(i, len(ur5e_waypoints) - 1)].get(
                                        "gripper"
                                    )
                                }
                                if ur5e_waypoints[min(i, len(ur5e_waypoints) - 1)].get("gripper")
                                is not None
                                else {}
                            ),
                        },
                    }
                }
                for i in range(count)
            ],
        }

    def _load_dual_function_payloads(
        self,
        target: str,
        xarm6_function_name: str,
        xarm6_name: str,
        ur5e_function_name: str,
        ur5e_name: str,
    ) -> tuple[dict[str, Any] | None, dict[str, Any] | None, str]:
        xarm6_payload, _xarm6_path, xarm6_err = self._robot_function_file_payload(
            target,
            "xarm6",
            xarm6_function_name,
            xarm6_name,
        )
        if xarm6_err or xarm6_payload is None:
            return None, None, f"xarm6: {xarm6_err}"
        ur5e_payload, _ur5e_path, ur5e_err = self._robot_function_file_payload(
            target,
            "ur5e",
            ur5e_function_name,
            ur5e_name,
        )
        if ur5e_err or ur5e_payload is None:
            return None, None, f"ur5e: {ur5e_err}"
        return xarm6_payload, ur5e_payload, ""

    def digital_twin_replay_dual_function(
        self,
        target: str,
        xarm6_function_name: str,
        xarm6_name: str,
        ur5e_function_name: str,
        ur5e_name: str,
        *,
        replay_target: str = "twin",
        repeat_count: int = 1,
    ) -> dict[str, Any]:
        if {
            self._robot_function_safe_function_name(xarm6_function_name),
            self._robot_function_safe_function_name(ur5e_function_name),
        } & {"pick_approach", "place_approach"}:
            return {
                "success": False,
                "message": (
                    "Raw waypoint Replay is disabled when either dual function is "
                    "pick_approach or place_approach; use Function Run so current "
                    "geometry is resolved."
                ),
            }
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        if not self._digital_twin_is_dual_robots(cfg):
            return {
                "success": False,
                "message": "Replay Dual Taught Function requires dual robots.",
            }
        xarm6_payload, ur5e_payload, err = self._load_dual_function_payloads(
            target,
            xarm6_function_name,
            xarm6_name,
            ur5e_function_name,
            ur5e_name,
        )
        if err or xarm6_payload is None or ur5e_payload is None:
            return {"success": False, "message": err}
        recording = self._paired_recording_from_function_payloads(
            target,
            xarm6_payload,
            ur5e_payload,
        )
        if recording is None:
            return {
                "success": False,
                "message": "both taught function files need at least one waypoint step.",
            }
        temp_path = Path("/tmp") / (
            f"cais_digital_twin_dual_function_"
            f"{self._robot_function_safe_name(xarm6_function_name)}_{self._robot_function_safe_name(xarm6_name)}__"
            f"{self._robot_function_safe_name(ur5e_function_name)}_{self._robot_function_safe_name(ur5e_name)}.json"
        )
        atomic_json_write(temp_path, recording)
        return self._replay_recording_file(
            target,
            cfg,
            temp_path,
            replay_target,
            source=f"dual_function_{xarm6_function_name}_{xarm6_name}_{ur5e_function_name}_{ur5e_name}",
            repeat_count=repeat_count,
        )

    def digital_twin_replay_dual_step(
        self,
        target: str,
        xarm6_function_name: str,
        xarm6_name: str,
        xarm6_step_index: int,
        ur5e_function_name: str,
        ur5e_name: str,
        ur5e_step_index: int,
        *,
        replay_target: str = "twin",
    ) -> dict[str, Any]:
        if {
            self._robot_function_safe_function_name(xarm6_function_name),
            self._robot_function_safe_function_name(ur5e_function_name),
        } & {"pick_approach", "place_approach"}:
            return {
                "success": False,
                "message": (
                    "Raw waypoint Replay is disabled when either selected dual step is "
                    "from pick_approach or place_approach; use Function Run so current "
                    "geometry is resolved."
                ),
            }
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        if not self._digital_twin_is_dual_robots(cfg):
            return {"success": False, "message": "Replay Dual Selected Step requires dual robots."}
        xarm6_payload, ur5e_payload, err = self._load_dual_function_payloads(
            target,
            xarm6_function_name,
            xarm6_name,
            ur5e_function_name,
            ur5e_name,
        )
        if err or xarm6_payload is None or ur5e_payload is None:
            return {"success": False, "message": err}
        recording = self._paired_recording_from_function_payloads(
            target,
            xarm6_payload,
            ur5e_payload,
            xarm6_step_index=xarm6_step_index,
            ur5e_step_index=ur5e_step_index,
        )
        if recording is None:
            return {"success": False, "message": "selected dual steps both need waypoints."}
        temp_path = Path("/tmp") / (
            f"cais_digital_twin_dual_function_step_"
            f"{self._robot_function_safe_name(xarm6_function_name)}_{self._robot_function_safe_name(xarm6_name)}_{int(xarm6_step_index)}__"
            f"{self._robot_function_safe_name(ur5e_function_name)}_{self._robot_function_safe_name(ur5e_name)}_{int(ur5e_step_index)}.json"
        )
        atomic_json_write(temp_path, recording)
        return self._replay_recording_file(
            target,
            cfg,
            temp_path,
            replay_target,
            source=(
                f"dual_function_step_{xarm6_function_name}_{xarm6_name}_{int(xarm6_step_index)}_"
                f"{ur5e_function_name}_{ur5e_name}_{int(ur5e_step_index)}"
            ),
        )

    def _digital_twin_buffer_path(self, target: str, cfg: dict[str, Any]) -> Path:
        slug = self._digital_twin_slug(cfg)
        return Path("/tmp") / f"cais_digital_twin_{slug}_buffer.json"

    @staticmethod
    def _digital_twin_recording_hash(recording: dict[str, Any]) -> str:
        return digital_twin.digital_twin_recording_hash(recording)

    def _digital_twin_prepared_replay_path(
        self,
        target: str,
        cfg: dict[str, Any],
        recording: dict[str, Any],
        replay_target: str,
        source: str,
    ) -> Path:
        return digital_twin.digital_twin_prepared_replay_path(
            cfg,
            recording,
            replay_target,
            source,
            Path("/tmp"),
        )

    @staticmethod
    def _digital_twin_is_dual_robots(cfg: dict[str, Any]) -> bool:
        return digital_twin.digital_twin_is_dual_robots(cfg)

    @staticmethod
    def _digital_twin_dual_robot_keys(cfg: dict[str, Any]) -> list[str]:
        return digital_twin.digital_twin_dual_robot_keys(cfg)

    @staticmethod
    def _digital_twin_recovery_metadata(target: str, *, recording_type: str) -> dict[str, Any]:
        return digital_twin.digital_twin_recovery_metadata(
            target,
            recording_type=recording_type,
        )

    def _waypoints_from_recording(
        self,
        cfg: dict[str, Any],
        recording: dict[str, Any],
    ) -> list[dict[str, Any]]:
        return digital_twin.waypoints_from_recording(cfg, recording)

    def _load_digital_twin_buffer_waypoints(
        self,
        target: str,
        cfg: dict[str, Any],
    ) -> list[dict[str, Any]]:
        path = self._digital_twin_buffer_path(target, cfg)
        data = self._read_json_file(path)
        if not data:
            return []
        return self._waypoints_from_recording(cfg, data)

    def _digital_twin_buffer_waypoints(
        self,
        target: str,
        cfg: dict[str, Any],
    ) -> list[dict[str, Any]]:
        with self._digital_twin_record_lock:
            buf = list(self._digital_twin_waypoints.get(target, []))
        if buf:
            return buf

        persisted = self._load_digital_twin_buffer_waypoints(target, cfg)
        if persisted:
            with self._digital_twin_record_lock:
                if not self._digital_twin_waypoints.get(target):
                    self._digital_twin_waypoints[target] = list(persisted)
                buf = list(self._digital_twin_waypoints.get(target, []))
            return buf
        return []

    def _persist_digital_twin_buffer(
        self,
        target: str,
        cfg: dict[str, Any],
        waypoints: list[dict[str, Any]],
    ) -> None:
        path = self._digital_twin_buffer_path(target, cfg)
        if waypoints:
            atomic_json_write(path, self._recording_from_waypoints(target, cfg, waypoints))
            return
        try:
            path.unlink()
        except FileNotFoundError:
            pass
        except Exception:
            log.exception("failed to clear digital twin buffer %s", path)

    def _snapshot_robot_waypoint(
        self,
        robot: str,
        *,
        source: str = "gazebo",
        hardware_domain_id: int | None = None,
        include_world_tool_pose: bool = False,
    ) -> dict[str, Any]:
        """Snapshot one robot's current gazebo or hardware pose into a waypoint body."""
        source_key = str(source or "gazebo").strip().lower()
        if source_key not in {"gazebo", "hardware"}:
            source_key = "gazebo"
        domains = self._digital_twin_domain_ids()
        resolved_hardware_domain_id = (
            int(domains["hardware"])
            if hardware_domain_id is None
            else int(hardware_domain_id)
        )
        args = [
            "--mode",
            "snapshot",
            "--robot",
            robot,
            "--source",
            source_key,
            "--gazebo-domain-id",
            str(domains["gazebo"]),
            "--hardware-domain-id",
            str(resolved_hardware_domain_id),
        ]
        if include_world_tool_pose:
            args.append("--include-world-tool-pose")
        result = self._run_digital_twin_sync(
            args,
            timeout_sec=20.0,
        )
        if not result.get("success"):
            return {"error": str(result.get("message") or "snapshot failed")}
        return {
            "positions": [float(v) for v in (result.get("positions") or [])],
            "gripper": result.get("gripper_position"),
            "joint_names": list(result.get("joint_names") or []),
            "gripper_joint": result.get("gripper_joint"),
            "source": source_key,
            "pose": deepcopy(result.get("pose")),
            "world_base_pose": deepcopy(result.get("world_base_pose")),
            "world_tool0_ready": bool(result.get("world_tool0_ready")),
        }

    def _snapshot_waypoint(self, target: str, cfg: dict[str, Any]) -> dict[str, Any]:
        """Snapshot the current gazebo pose into a waypoint dict (or {'error': msg})."""
        if self.ros2_proc_status(str(cfg.get("gazebo_process") or "")) != "running":
            return {"error": f"{target} gazebo is not running."}

        if self._digital_twin_is_dual_robots(cfg):
            robots: dict[str, dict[str, Any]] = {}
            for robot in self._digital_twin_dual_robot_keys(cfg):
                waypoint = self._snapshot_robot_waypoint(robot)
                if "error" in waypoint:
                    return {"error": f"{robot}: {waypoint['error']}"}
                robots[robot] = waypoint
            if not robots:
                return {"error": f"{target} has no paired robots configured."}
            return {
                "robots": robots,
                "t": time.time(),
            }

        robot_waypoint = self._snapshot_robot_waypoint(str(cfg.get("robot") or ""))
        if "error" in robot_waypoint:
            return robot_waypoint
        robot_waypoint["t"] = time.time()
        return robot_waypoint

    def digital_twin_capture_waypoint(self, target: str) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        waypoint = self._snapshot_waypoint(target, cfg)
        if "error" in waypoint:
            return {"success": False, "message": waypoint["error"]}
        with self._digital_twin_record_lock:
            buf = self._digital_twin_waypoints.setdefault(target, [])
            buf.append(waypoint)
            persisted_buf = list(buf)
            count = len(buf)
        self._persist_digital_twin_buffer(target, cfg, persisted_buf)
        return {"success": True, "message": f"captured waypoint {count}", "count": count}

    def digital_twin_list_waypoints(self, target: str) -> list[dict[str, Any]]:
        cfg = self._digital_twin_target(target) or {}
        buf = self._digital_twin_buffer_waypoints(target, cfg) if cfg else []
        return [
            {
                "index": i,
                "positions": [float(v) for v in (wp.get("positions") or [])],
                "gripper": wp.get("gripper"),
                "robots": {
                    str(robot): {
                        "positions": [float(v) for v in (body.get("positions") or [])],
                        "gripper": body.get("gripper"),
                    }
                    for robot, body in dict(wp.get("robots") or {}).items()
                    if isinstance(body, dict)
                },
            }
            for i, wp in enumerate(buf)
        ]

    def digital_twin_delete_waypoint(self, target: str, index: int) -> dict[str, Any]:
        cfg = self._digital_twin_target(target) or {}
        if cfg:
            self._digital_twin_buffer_waypoints(target, cfg)
        with self._digital_twin_record_lock:
            buf = self._digital_twin_waypoints.get(target, [])
            if not (0 <= index < len(buf)):
                return {"success": False, "message": "waypoint index out of range."}
            buf.pop(index)
            persisted_buf = list(buf)
            count = len(buf)
        if cfg:
            self._persist_digital_twin_buffer(target, cfg, persisted_buf)
        return {"success": True, "message": f"deleted waypoint {index + 1}", "count": count}

    def digital_twin_move_waypoint(self, target: str, index: int, delta: int) -> dict[str, Any]:
        cfg = self._digital_twin_target(target) or {}
        if cfg:
            self._digital_twin_buffer_waypoints(target, cfg)
        with self._digital_twin_record_lock:
            buf = self._digital_twin_waypoints.get(target, [])
            new_index = index + (1 if delta > 0 else -1)
            if not (0 <= index < len(buf)) or not (0 <= new_index < len(buf)):
                return {"success": False, "message": "cannot move waypoint."}
            buf[index], buf[new_index] = buf[new_index], buf[index]
            persisted_buf = list(buf)
        if cfg:
            self._persist_digital_twin_buffer(target, cfg, persisted_buf)
        return {"success": True, "message": "reordered waypoints."}

    def digital_twin_overwrite_waypoint(self, target: str, index: int) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        self._digital_twin_buffer_waypoints(target, cfg)
        with self._digital_twin_record_lock:
            if not (0 <= index < len(self._digital_twin_waypoints.get(target, []))):
                return {"success": False, "message": "waypoint index out of range."}
        waypoint = self._snapshot_waypoint(target, cfg)
        if "error" in waypoint:
            return {"success": False, "message": waypoint["error"]}
        with self._digital_twin_record_lock:
            buf = self._digital_twin_waypoints.get(target, [])
            if not (0 <= index < len(buf)):
                return {"success": False, "message": "waypoint index out of range."}
            buf[index] = waypoint
            persisted_buf = list(buf)
        self._persist_digital_twin_buffer(target, cfg, persisted_buf)
        return {"success": True, "message": f"updated waypoint {index + 1} to current sim pose"}

    def digital_twin_waypoint_count(self, target: str) -> int:
        cfg = self._digital_twin_target(target) or {}
        return len(self._digital_twin_buffer_waypoints(target, cfg)) if cfg else 0

    def digital_twin_clear_waypoints(self, target: str) -> None:
        with self._digital_twin_record_lock:
            self._digital_twin_waypoints.pop(target, None)
        cfg = self._digital_twin_target(target) or {}
        if cfg:
            self._persist_digital_twin_buffer(target, cfg, [])

    def digital_twin_save_recording(self, target: str, name: str) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        safe = "".join(c if (c.isalnum() or c in "-_") else "_" for c in str(name).strip())
        if not safe:
            return {"success": False, "message": "recording name is empty."}
        buf = self._digital_twin_buffer_waypoints(target, cfg)
        if not buf:
            return {"success": False, "message": "no waypoints captured."}

        recording = self._recording_from_waypoints(target, cfg, buf)
        slug = self._digital_twin_slug(cfg)
        path = self._digital_twin_recordings_dir() / f"{slug}__{safe}.json"
        atomic_json_write(path, recording)
        return {
            "success": True,
            "message": f"saved {len(buf)} waypoints to {path.name}",
            "file": str(path),
        }

    def digital_twin_list_recordings(self, target: str) -> list[str]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return []
        slug = self._digital_twin_slug(cfg)
        prefix = f"{slug}__"
        return sorted(
            p.name[len(prefix) : -len(".json")]
            for p in self._digital_twin_recordings_dir().glob(f"{prefix}*.json")
        )

    def digital_twin_delete_recording(self, target: str, name: str) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        safe = str(name or "").strip()
        if not safe:
            return {"success": False, "message": "no recording selected."}
        slug = self._digital_twin_slug(cfg)
        path = self._digital_twin_recordings_dir() / f"{slug}__{safe}.json"
        if not path.is_file():
            return {"success": False, "message": f"recording not found: {safe}"}
        try:
            path.unlink()
        except Exception as exc:
            return {"success": False, "message": str(exc)}
        return {"success": True, "message": f"deleted recording '{safe}'."}

    def _build_buffer_recording(self, target: str, cfg: dict[str, Any]) -> dict[str, Any] | None:
        """Assemble a recording dict from the in-memory capture buffer (or None if empty)."""
        buf = self._digital_twin_buffer_waypoints(target, cfg)
        if not buf:
            return None
        return self._recording_from_waypoints(target, cfg, buf)

    def _recording_from_waypoints(
        self,
        target: str,
        cfg: dict[str, Any],
        waypoints: list[dict[str, Any]],
    ) -> dict[str, Any]:
        if self._digital_twin_is_dual_robots(cfg):
            robot_meta: dict[str, dict[str, Any]] = {}
            first_robots = dict((waypoints[0] or {}).get("robots") or {})
            for robot in self._digital_twin_dual_robot_keys(cfg):
                body = dict(first_robots.get(robot) or {})
                robot_meta[robot] = {
                    "joint_names": list(body.get("joint_names") or []),
                    "gripper_joint": body.get("gripper_joint"),
                }
            return {
                "target": target,
                "robot": "dual robots",
                "recording_type": "paired_dual_robots",
                "robots": robot_meta,
                "recovery_metadata": self._digital_twin_recovery_metadata(
                    target,
                    recording_type="paired_dual_robots",
                ),
                "waypoints": [
                    {
                        "robots": {
                            robot: {
                                "positions": list(
                                    dict((wp.get("robots") or {}).get(robot) or {}).get("positions")
                                    or []
                                ),
                                "gripper": dict((wp.get("robots") or {}).get(robot) or {}).get(
                                    "gripper"
                                ),
                            }
                            for robot in self._digital_twin_dual_robot_keys(cfg)
                        }
                    }
                    for wp in waypoints
                ],
            }

        return {
            "target": target,
            "robot": str(cfg.get("robot") or ""),
            "recording_type": "single_robot",
            "joint_names": list(waypoints[0].get("joint_names") or []),
            "gripper_joint": waypoints[0].get("gripper_joint"),
            "recovery_metadata": self._digital_twin_recovery_metadata(
                target,
                recording_type="single_robot",
            ),
            "waypoints": [
                {"positions": list(wp.get("positions") or []), "gripper": wp.get("gripper")}
                for wp in waypoints
            ],
        }

    def _prepare_replay_recording_file(
        self,
        target: str,
        cfg: dict[str, Any],
        recording_path: Path,
        replay_target: str,
        *,
        source: str,
    ) -> dict[str, Any]:
        if replay_target not in ("twin", "gazebo", "hardware"):
            return {"success": False, "message": f"unknown replay target: {replay_target}"}
        if not self._digital_twin_is_dual_robots(cfg):
            return {"success": False, "message": "prepare replay only supports dual robots."}
        recording = self._read_json_file(recording_path)
        if not recording:
            return {"success": False, "message": f"recording not found: {recording_path.name}"}
        sync_target = "hardware" if replay_target == "twin" else replay_target
        needs_hardware = replay_target in ("twin", "hardware")
        domains = self._digital_twin_domain_ids()
        if needs_hardware:
            err = self._wait_for_digital_twin_dual_robots_hardware_ready(
                cfg,
                ros_domain_id=int(domains["hardware"]),
                require_moveit=False,
            )
            if err:
                message = f"{target} hardware is not ready: {err}"
                self._write_digital_twin_status(
                    target,
                    {
                        "state": "blocked",
                        "direction": self._digital_twin_direction(target),
                        "message": message,
                        "last_error": message,
                    },
                )
                return {"success": False, "message": message}
        gazebo_process = str(cfg.get("gazebo_process") or "")
        if (
            replay_target in ("twin", "gazebo")
            and self.ros2_proc_status(gazebo_process) != "running"
        ):
            return {"success": False, "message": f"{target} gazebo is not running."}

        prepared_path = self._digital_twin_prepared_replay_path(
            target,
            cfg,
            recording,
            replay_target,
            source,
        )
        with self._digital_twin_prepare_lock:
            self._write_digital_twin_status(
                target,
                {
                    "state": "preparing",
                    "direction": self._digital_twin_direction(target),
                    "message": "preparing replay without moving gazebo or hardware.",
                    "last_error": "",
                },
            )
            result = self._run_digital_twin_sync(
                [
                    "--mode",
                    "prepare-replay",
                    "--robot",
                    str(cfg.get("robot") or ""),
                    "--replay-target",
                    sync_target,
                    "--recording-file",
                    str(recording_path),
                    "--prepared-file",
                    str(prepared_path),
                    "--gazebo-domain-id",
                    str(domains["gazebo"]),
                    "--hardware-domain-id",
                    str(domains["hardware"]),
                    "--max-joint-delta-deg",
                    str(self._DIGITAL_TWIN_MAX_JOINT_DELTA_DEG),
                    "--status-file",
                    str(self._digital_twin_status_path(target)),
                    "--direction-file",
                    str(self._digital_twin_direction_path(target)),
                ],
                timeout_sec=120.0,
            )
        result["prepared_file"] = str(prepared_path)
        result["recording_hash"] = self._digital_twin_recording_hash(recording)
        return result

    def _replay_recording_file(
        self,
        target: str,
        cfg: dict[str, Any],
        recording_path: Path,
        replay_target: str,
        *,
        source: str = "recording",
        repeat_count: int = 1,
    ) -> dict[str, Any]:
        if replay_target not in ("twin", "gazebo", "hardware"):
            return {"success": False, "message": f"unknown replay target: {replay_target}"}
        try:
            repeat_total = int(repeat_count)
        except Exception:
            repeat_total = 1
        repeat_total = max(1, min(999, repeat_total))
        replay_label = (
            "Replay Dual Function" if str(source).startswith("dual_function") else "Replay Function"
        )
        needs_hardware = replay_target in ("twin", "hardware")
        domains = self._digital_twin_domain_ids()
        dual_hardware_replay = needs_hardware and self._digital_twin_is_dual_robots(cfg)
        # For dual Replay in Twin, Gazebo follows the real hardware through the
        # live hardware -> gazebo mirror instead of a separate preplanned publish.
        sync_target = (
            "hardware"
            if replay_target == "twin" and dual_hardware_replay
            else ("both" if replay_target == "twin" else replay_target)
        )

        def _check_dual_replay_ready(message: str) -> str | None:
            self._write_digital_twin_status(
                target,
                {
                    "state": "checking",
                    "direction": "hardware -> gazebo"
                    if replay_target == "twin"
                    else self._digital_twin_direction(target),
                    "message": message,
                    "last_error": "",
                },
            )
            return self._wait_for_digital_twin_dual_robots_replay_ready(
                target,
                cfg,
                ros_domain_id=int(domains["hardware"]),
            )

        def _blocked_dual_replay_result(message: str, **extra: Any) -> dict[str, Any]:
            self._write_digital_twin_status(
                target,
                {
                    "state": "blocked",
                    "direction": "hardware -> gazebo"
                    if replay_target == "twin"
                    else self._digital_twin_direction(target),
                    "message": message,
                    "last_error": message,
                },
            )
            out: dict[str, Any] = {"success": False, "message": message}
            out.update(extra)
            return out

        if dual_hardware_replay:
            self._write_digital_twin_status(
                target,
                {
                    "state": "checking",
                    "direction": "hardware -> gazebo"
                    if replay_target == "twin"
                    else self._digital_twin_direction(target),
                    "message": "checking replay readiness.",
                    "last_error": "",
                },
            )
            err = self._wait_for_digital_twin_dual_robots_replay_ready(
                target,
                cfg,
                ros_domain_id=int(domains["hardware"]),
            )
            if err:
                message = f"{target} hardware is not ready: {err}"
                self._write_digital_twin_status(
                    target,
                    {
                        "state": "blocked",
                        "direction": "hardware -> gazebo"
                        if replay_target == "twin"
                        else self._digital_twin_direction(target),
                        "message": message,
                        "last_error": message,
                    },
                )
                return {"success": False, "message": message}
        elif needs_hardware and self._digital_twin_hardware_status(cfg).get("overall") != "running":
            return {"success": False, "message": f"{target} hardware is not running."}
        if self.ros2_proc_status(str(cfg.get("gazebo_process") or "")) != "running":
            return {"success": False, "message": f"{target} gazebo is not running."}

        prepared_args: list[str] = []
        if replay_target == "twin" and self._digital_twin_is_dual_robots(cfg):
            recording = self._read_json_file(recording_path)
            if recording:
                prepared_path = self._digital_twin_prepared_replay_path(
                    target,
                    cfg,
                    recording,
                    replay_target,
                    source,
                )
                if prepared_path.is_file():
                    prepared_data = self._read_json_file(prepared_path)
                    metadata = dict(prepared_data.get("metadata") or {})
                    expected = {
                        "version": self._DIGITAL_TWIN_PREPARED_REPLAY_VERSION,
                        "recording_hash": self._digital_twin_recording_hash(recording),
                        "replay_target": sync_target,
                        "gazebo_domain_id": int(domains["gazebo"]),
                        "hardware_domain_id": int(domains["hardware"]),
                        "waypoint_count": len(list(recording.get("waypoints") or [])),
                        "robot": str(recording.get("robot") or ""),
                        "recording_type": str(recording.get("recording_type") or ""),
                    }
                    if all(metadata.get(key) == value for key, value in expected.items()):
                        prepared_args = ["--prepared-file", str(prepared_path)]
        gazebo_initialization = "not_required"
        sync_is_healthy = False
        init_before_replay = replay_target == "twin" or (
            replay_target == "gazebo"
            and self._digital_twin_is_dual_robots(cfg)
            and self._digital_twin_sim_mode(target) == "teach"
        )
        if init_before_replay:
            sync_snapshot = self._digital_twin_sync_status_snapshot(target, cfg, time.time())
            status_data = dict(sync_snapshot.get("status_data") or {})
            status_age_ms = sync_snapshot.get("status_age_ms")
            sync_is_healthy = (
                replay_target == "twin"
                and str(sync_snapshot.get("process_status") or "") == "running"
                and str(status_data.get("state") or "") == "mirroring"
                and status_age_ms is not None
                and float(status_age_ms) <= 3000.0
                and self._digital_twin_direction(target) == "hardware -> gazebo"
            )
            if sync_is_healthy:
                init_before_replay = False
                gazebo_initialization = "skipped"
        if init_before_replay:
            init_label = "Replay in Twin" if replay_target == "twin" else "Preview in Gazebo"
            init_failure_word = "replay" if replay_target == "twin" else "preview"
            self._write_digital_twin_status(
                target,
                {
                    "state": "replaying",
                    "direction": "hardware -> gazebo",
                    "message": f"{init_label}: initializing gazebo from hardware.",
                    "last_error": "",
                },
            )
            init_err = self._initialize_digital_twin_gazebo_from_hardware(
                target,
                cfg,
                gazebo_process=str(cfg.get("gazebo_process") or ""),
                domains=domains,
            )
            if init_err:
                return {
                    "success": False,
                    "message": f"could not initialize gazebo from hardware before {init_failure_word}: {init_err}",
                    "gazebo_initialization": "failed",
                }
            gazebo_initialization = "ran"
        if dual_hardware_replay:
            if replay_target == "twin" and not sync_is_healthy:
                self._write_digital_twin_status(
                    target,
                    {
                        "state": "replaying",
                        "direction": "hardware -> gazebo",
                        "message": "Replay in Twin: starting hardware -> gazebo mirror.",
                        "last_error": "",
                    },
                )
                sync_err = self._start_digital_twin_sync_when_ready(
                    target,
                    cfg,
                    gazebo_process=str(cfg.get("gazebo_process") or ""),
                    domains=domains,
                    direction="hardware -> gazebo",
                )
                if sync_err:
                    return _blocked_dual_replay_result(
                        f"hardware -> Gazebo sync start failed before replay: {sync_err}",
                        gazebo_initialization=gazebo_initialization,
                    )
                settle_sec = max(0.0, float(self._DIGITAL_TWIN_MIRROR_STABILIZATION_SEC))
                if settle_sec > 0.0:
                    time.sleep(settle_sec)
            err = _check_dual_replay_ready("checking final replay readiness.")
            if err:
                message = f"{target} hardware is not ready: {err}"
                return _blocked_dual_replay_result(
                    message,
                    gazebo_initialization=gazebo_initialization,
                )
        self._write_digital_twin_status(
            target,
            {
                "state": "replaying",
                "direction": "hardware -> gazebo"
                if replay_target == "twin"
                else self._digital_twin_direction(target),
                "message": (
                    "Replay in Twin: committing prepared sim waypoint through /xarm6/xarm6_traj_controller/follow_joint_trajectory and /cais_ur5e_rtde_trajectory_controller/follow_joint_trajectory while hardware -> gazebo sync mirrors Gazebo."
                    if (
                        prepared_args
                        and replay_target == "twin"
                        and self._digital_twin_is_dual_robots(cfg)
                    )
                    else (
                        "Replay in Twin: committing saved sim waypoint through /xarm6/xarm6_traj_controller/follow_joint_trajectory and /cais_ur5e_rtde_trajectory_controller/follow_joint_trajectory while hardware -> gazebo sync mirrors Gazebo."
                        if replay_target == "twin" and self._digital_twin_is_dual_robots(cfg)
                        else (
                            "Replay in Twin: committing prepared sim waypoint through hardware MoveIt."
                            if prepared_args and replay_target == "twin"
                            else (
                                "Replay in Twin: committing saved sim waypoint through hardware MoveIt."
                                if replay_target == "twin"
                                else "Preview in Gazebo: publishing to Gazebo only."
                            )
                        )
                    )
                ),
                "last_error": "",
            },
        )
        stopped_mirror_workers = False
        sync_args = [
            "--mode",
            "replay",
            "--robot",
            str(cfg.get("robot") or ""),
            "--replay-target",
            sync_target,
            "--recording-file",
            str(recording_path),
            *prepared_args,
            "--gazebo-domain-id",
            str(domains["gazebo"]),
            "--hardware-domain-id",
            str(domains["hardware"]),
            "--max-joint-delta-deg",
            str(self._DIGITAL_TWIN_MAX_JOINT_DELTA_DEG),
            "--waypoint-duration-sec",
            f"{self._DIGITAL_TWIN_REPLAY_WAYPOINT_DURATION_SEC:.6f}",
            "--max-joint-vel-deg-s",
            f"{self._DIGITAL_TWIN_REPLAY_MAX_JOINT_VEL_DEG_S:.6f}",
            "--status-file",
            str(self._digital_twin_status_path(target)),
            "--direction-file",
            str(self._digital_twin_direction_path(target)),
        ]
        result: dict[str, Any] = {}
        for repeat_index in range(repeat_total):
            if repeat_total > 1:
                self._write_digital_twin_status(
                    target,
                    {
                        "state": "replaying",
                        "direction": "hardware -> gazebo"
                        if replay_target == "twin"
                        else self._digital_twin_direction(target),
                        "message": f"executing replay repeat {repeat_index + 1}/{repeat_total}.",
                        "last_error": "",
                    },
                )
            if dual_hardware_replay and repeat_index > 0:
                err = _check_dual_replay_ready(
                    f"checking replay readiness for repeat {repeat_index + 1}/{repeat_total}."
                )
                if err:
                    message = f"{target} hardware is not ready: {err}"
                    result = {
                        "success": False,
                        "message": (
                            f"{replay_label} failed on repeat {repeat_index + 1}/{repeat_total}: {message}"
                            if repeat_total > 1
                            else message
                        ),
                        "repeat_count": repeat_total,
                        "repeat_iteration": repeat_index + 1,
                    }
                    break
            result = self._run_digital_twin_sync(sync_args, timeout_sec=120.0)
            result["repeat_count"] = repeat_total
            result["repeat_iteration"] = repeat_index + 1
            if not result.get("success"):
                if repeat_total > 1:
                    result["message"] = (
                        f"{replay_label} failed on repeat {repeat_index + 1}/{repeat_total}: "
                        f"{str(result.get('message') or '')}"
                    )
                break
        if repeat_total > 1 and result.get("success"):
            result["message"] = (
                f"{replay_label} repeated {repeat_total} times. {str(result.get('message') or '')}"
            )
        result["gazebo_initialization"] = gazebo_initialization
        if replay_target == "twin" and dual_hardware_replay:
            result["sync_remained_active"] = True
            base_message = str(result.get("message") or "")
            result["message"] = (
                f"{base_message}; hardware -> Gazebo sync remained active."
                if base_message
                else "hardware -> Gazebo sync remained active."
            )
            marker_err = self._resync_digital_twin_dual_drag_markers(
                cfg,
                ros_domain_id=domains["hardware"],
            )
            result["paired_markers_refreshed"] = not bool(marker_err)
            result["paired_markers_resynced"] = not bool(marker_err)
            base_message = str(result.get("message") or "")
            if marker_err:
                result["paired_marker_resync_error"] = marker_err
                result["message"] = (
                    f"{base_message}; dual_drag_markers resync failed: {marker_err}"
                    if base_message
                    else f"dual_drag_markers resync failed: {marker_err}"
                )
            else:
                marker_message = (
                    "dual_drag_markers resynced from latest hardware state."
                    if result.get("success")
                    else "dual_drag_markers resynced from latest hardware state after failed replay."
                )
                result["message"] = (
                    f"{base_message}; {marker_message}" if base_message else marker_message
                )
        elif replay_target == "twin" and (result.get("success") or stopped_mirror_workers):
            self._write_digital_twin_status(
                target,
                {
                    "state": "resuming",
                    "direction": "hardware -> gazebo",
                    "message": "resuming hardware -> gazebo mirror.",
                    "last_error": "" if result.get("success") else str(result.get("message") or ""),
                },
            )
            sync_err = self._start_digital_twin_sync_when_ready(
                target,
                cfg,
                gazebo_process=str(cfg.get("gazebo_process") or ""),
                domains=domains,
                direction="hardware -> gazebo",
            )
            result["sync_resumed"] = not bool(sync_err)
            base_message = str(result.get("message") or "")
            if sync_err:
                result["sync_resume_error"] = sync_err
                result["message"] = (
                    f"{base_message}; hardware -> Gazebo sync resume failed: {sync_err}"
                    if base_message
                    else f"hardware -> Gazebo sync resume failed: {sync_err}"
                )
            elif result.get("success"):
                settle_sec = max(0.0, float(self._DIGITAL_TWIN_MIRROR_STABILIZATION_SEC))
                if settle_sec > 0.0:
                    self._write_digital_twin_status(
                        target,
                        {
                            "state": "resuming",
                            "direction": "hardware -> gazebo",
                            "message": (
                                "waiting for hardware -> gazebo mirror to stabilize; "
                                f"mirror_stabilization_sec={settle_sec:.2f}."
                            ),
                            "last_error": "",
                        },
                    )
                    time.sleep(settle_sec)
                result["message"] = (
                    f"{base_message}; hardware -> Gazebo sync resumed."
                    if base_message
                    else "hardware -> Gazebo sync resumed."
                )
            else:
                result["message"] = (
                    f"{base_message}; hardware -> Gazebo sync resumed after failed replay."
                    if base_message
                    else "hardware -> Gazebo sync resumed after failed replay."
                )
        detail_parts: list[str] = []
        if result.get("saved_steps") is not None:
            detail_parts.append(f"saved_steps={int(result.get('saved_steps') or 0)}")
        if result.get("waypoints") is not None:
            detail_parts.append(f"waypoints={int(result.get('waypoints') or 0)}")
        if result.get("approach_time") is not None:
            detail_parts.append(f"approach_time={float(result.get('approach_time') or 0.0):.3f}s")
        if result.get("max_joint_delta_deg") is not None:
            detail_parts.append(
                f"max_joint_delta_deg={float(result.get('max_joint_delta_deg') or 0.0):.3f}"
            )
        if result.get("max_joint_delta_joint"):
            detail_parts.append(
                f"max_joint_delta_joint={str(result.get('max_joint_delta_joint') or '')}"
            )
        if gazebo_initialization != "not_required":
            detail_parts.append(f"gazebo_initialization={gazebo_initialization}")
        if result.get("used_prepared_file") is not None:
            detail_parts.append(f"used_prepared_file={bool(result.get('used_prepared_file'))}")
        if detail_parts:
            base_message = str(result.get("message") or "").rstrip(". ")
            result["message"] = (
                f"{base_message}; {'; '.join(detail_parts)}."
                if base_message
                else f"{'; '.join(detail_parts)}."
            )
        message = str(result.get("message") or "")
        self._write_digital_twin_status(
            target,
            {
                "state": "replayed" if result.get("success") else "blocked",
                "direction": "hardware -> gazebo"
                if replay_target == "twin"
                else self._digital_twin_direction(target),
                "message": message or "replay finished.",
                "last_error": "" if result.get("success") else message,
            },
        )
        return result

    def digital_twin_replay(
        self, target: str, name: str, *, replay_target: str = "twin"
    ) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        slug = self._digital_twin_slug(cfg)
        path = self._digital_twin_recordings_dir() / f"{slug}__{name}.json"
        if not path.is_file():
            return {"success": False, "message": f"recording not found: {name}"}
        return self._replay_recording_file(target, cfg, path, replay_target, source=f"saved_{name}")

    def digital_twin_replay_buffer(
        self, target: str, *, replay_target: str = "twin"
    ) -> dict[str, Any]:
        """Replay the just-captured (unsaved) waypoint buffer, without forcing a Save."""
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        recording = self._build_buffer_recording(target, cfg)
        if recording is None:
            return {"success": False, "message": "No captured waypoints to replay."}
        slug = self._digital_twin_slug(cfg)
        path = Path("/tmp") / f"cais_digital_twin_{slug}_buffer.json"
        atomic_json_write(path, recording)
        return self._replay_recording_file(target, cfg, path, replay_target, source="buffer")

    def digital_twin_prepare_replay(
        self,
        target: str,
        name: str,
        *,
        replay_target: str = "twin",
    ) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        slug = self._digital_twin_slug(cfg)
        path = self._digital_twin_recordings_dir() / f"{slug}__{name}.json"
        if not path.is_file():
            return {"success": False, "message": f"recording not found: {name}"}
        return self._prepare_replay_recording_file(
            target,
            cfg,
            path,
            replay_target,
            source=f"saved_{name}",
        )

    def digital_twin_prepare_replay_buffer(
        self,
        target: str,
        *,
        replay_target: str = "twin",
    ) -> dict[str, Any]:
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        recording = self._build_buffer_recording(target, cfg)
        if recording is None:
            return {"success": False, "message": "No captured waypoints to prepare."}
        slug = self._digital_twin_slug(cfg)
        path = Path("/tmp") / f"cais_digital_twin_{slug}_buffer.json"
        atomic_json_write(path, recording)
        return self._prepare_replay_recording_file(
            target,
            cfg,
            path,
            replay_target,
            source="buffer",
        )

    def digital_twin_go_home(self, target: str, *, replay_target: str = "twin") -> dict[str, Any]:
        """Move the arm to its configured home/initial pose (sim + hardware by default)."""
        cfg = self._digital_twin_target(target)
        if not cfg:
            return {"success": False, "message": f"unknown digital twin target: {target}"}
        robot = str(cfg.get("robot") or "")
        home = self._DIGITAL_TWIN_HOME.get(robot)
        if not home:
            return {"success": False, "message": f"no home pose configured for {robot}."}
        # Omit joint_names so the sync defaults to ROBOTS[robot]["gazebo_joints"].
        recording = {"target": target, "robot": robot, "waypoints": [{"positions": list(home)}]}
        slug = self._digital_twin_slug(cfg)
        path = Path("/tmp") / f"cais_digital_twin_{slug}_home.json"
        atomic_json_write(path, recording)
        return self._replay_recording_file(target, cfg, path, replay_target, source="home")

    def ros2_start_hardware_stack(self, robot: str) -> str | None:
        """Start one Hardware Stack while rejecting concurrent lifecycle requests."""
        key = str(robot).strip().lower()
        if not self._hardware_stack_for_robot(key):
            return f"unknown hardware robot: {robot}"
        lifecycle_lock = getattr(self, "_hardware_stack_lifecycle_lock", None)
        if lifecycle_lock is None:
            lifecycle_lock = threading.Lock()
            self._hardware_stack_lifecycle_lock = lifecycle_lock
        if not lifecycle_lock.acquire(blocking=False):
            return "Hardware Stack start or stop is already running."
        execution_lock = self._get_robot_function_execution_lock()
        execution_lock_acquired = False
        try:
            execution_lock_acquired = bool(
                execution_lock.acquire(blocking=False)
            )
            if not execution_lock_acquired:
                return self._hardware_stack_lifecycle_motion_error(
                    "start",
                    key,
                ) or (
                    "Cannot start Hardware Stack while physical robot motion is active."
                )
            agent_motion_error = self._hardware_stack_agent_motion_error(
                "start"
            )
            if agent_motion_error:
                return agent_motion_error
            selected_stack = str(getattr(self, "_hardware_stack_selected", "") or "")
            lifecycle_state = str(
                getattr(self, "_hardware_stack_lifecycle_state", "stopped") or "stopped"
            )
            if selected_stack and selected_stack != key and lifecycle_state != "stopped":
                return (
                    f"Hardware stack blocked: {selected_stack} Hardware Stack is "
                    f"{lifecycle_state}. Stop or repair it before starting another "
                    "Hardware Stack."
                )
            if selected_stack == key and lifecycle_state == "failed":
                return f"{key} Hardware Stack failed; click Repair Hardware Stack."
            self._next_hardware_stack_generation()
            starting_robots = (
                ("xarm6", "ur5e") if key == "dual robots" else (key,)
            )
            for starting_robot in starting_robots:
                self._hardware_stack_stationary_results.pop(starting_robot, None)
                self._hardware_stack_cartesian_jog_reset_results.pop(
                    starting_robot,
                    None,
                )
            self._hardware_stack_selected = key
            self._hardware_stack_lifecycle_state = "starting"
            self._hardware_stack_last_error = ""
            self._hardware_stack_failed_process = ""
            self._hardware_stack_failed_return_code = None
            self._hardware_stack_process_log_path = ""
            error = self._ros2_start_hardware_stack_locked(key)
            if error:
                self._hardware_stack_lifecycle_state = "failed"
                self._hardware_stack_last_error = error
                self._record_hardware_stack_start_failure(key, error)
                return error
            ownership_error = self._record_hardware_stack_validated_processes(key)
            if ownership_error:
                self._hardware_stack_lifecycle_state = "failed"
                self._hardware_stack_last_error = ownership_error
                self._record_hardware_stack_start_failure(key, ownership_error)
                return ownership_error
            if "ur5e" in starting_robots:
                durable_uncertainty, durable_uncertainty_error = (
                    self._read_ur5e_hardware_state_uncertainty()
                )
                if durable_uncertainty_error or durable_uncertainty is not None:
                    uncertainty_reason = str(
                        durable_uncertainty_error
                        or dict(durable_uncertainty or {}).get("reason")
                        or "UR5e physical state requires fresh stationary validation."
                    )
                    self._ur5e_robot_function_state_uncertain = True
                    self._ur5e_robot_function_state_uncertain_reason = (
                        uncertainty_reason
                    )
                    self._ur5e_cartesian_jog_state_uncertain = True
                    self._ur5e_cartesian_jog_state_uncertain_reason = (
                        uncertainty_reason
                    )
            pending_move_insert = (
                self._move_insert_pending_review()
                if "ur5e" in starting_robots
                else None
            )
            move_insert_repair_pending = bool(
                pending_move_insert is not None
                and str(pending_move_insert.get("robot") or "") == "ur5e"
                and (
                    pending_move_insert.get("hardware_stack_repair_required")
                    or pending_move_insert.get("normal_repair_required")
                )
            )
            if "ur5e" in starting_robots and bool(
                getattr(self, "_ur5e_robot_function_state_uncertain", False)
                or getattr(self, "_ur5e_cartesian_jog_state_uncertain", False)
                or move_insert_repair_pending
            ):
                generation = int(
                    getattr(self, "_hardware_stack_lifecycle_generation", 0)
                    or 0
                )
                stationary_error = self._validate_hardware_stationary(
                    "ur5e",
                    ros_domain_id=self._default_ros_domain_id(),
                )
                readiness = dict(
                    self._hardware_cartesian_readiness_states().get("ur5e")
                    or {}
                )
                if stationary_error:
                    uncertainty_error = (
                        "ur5e stationary feedback validation failed after Hardware "
                        f"Stack startup: {stationary_error}"
                    )
                elif int(readiness.get("generation", -1)) != generation:
                    uncertainty_error = (
                        "ur5e Cartesian frame validation belongs to generation "
                        f"{readiness.get('generation')}, expected {generation}"
                    )
                elif (
                    readiness.get("cartesian_jog_ready") is not True
                    or readiness.get("cartesian_function_ready") is not True
                ):
                    uncertainty_error = str(
                        readiness.get("message")
                        or "ur5e Cartesian frame validation failed"
                    )
                else:
                    uncertainty_error = ""
                if uncertainty_error:
                    self._hardware_stack_lifecycle_state = "failed"
                    self._hardware_stack_last_error = uncertainty_error
                    self._record_hardware_stack_start_failure(
                        key,
                        uncertainty_error,
                    )
                    return uncertainty_error
                uncertainty_clear_error = (
                    self._clear_ur5e_hardware_state_uncertainty()
                )
                if uncertainty_clear_error:
                    self._hardware_stack_lifecycle_state = "failed"
                    self._hardware_stack_last_error = uncertainty_clear_error
                    self._record_hardware_stack_start_failure(
                        key,
                        uncertainty_clear_error,
                    )
                    return uncertainty_clear_error
                self._ur5e_robot_function_state_uncertain = False
                self._ur5e_robot_function_state_uncertain_reason = ""
                self._ur5e_cartesian_jog_state_uncertain = False
                self._ur5e_cartesian_jog_state_uncertain_reason = ""
            if move_insert_repair_pending:
                move_insert_repair_error = (
                    self._clear_move_insert_repair_gate_after_hardware_stack(
                        hardware_stack=key,
                        generation=int(
                            getattr(
                                self,
                                "_hardware_stack_lifecycle_generation",
                                0,
                            )
                            or 0
                        ),
                    )
                )
                if move_insert_repair_error:
                    self._hardware_stack_lifecycle_state = "failed"
                    self._hardware_stack_last_error = move_insert_repair_error
                    self._record_hardware_stack_start_failure(
                        key,
                        move_insert_repair_error,
                    )
                    return move_insert_repair_error
            self._hardware_stack_lifecycle_state = "running"
            return None
        finally:
            if execution_lock_acquired:
                execution_lock.release()
            lifecycle_lock.release()

    def _stop_ur5e_calibration_state_publisher_for_hardware_authority(
        self,
    ) -> str | None:
        """Stop the standalone publisher before the Hardware Stack owns UR5e TF."""
        process_name = "ur5e_calibration_state_publisher"
        process_start_lock = getattr(self, "_ros2_process_start_lock", None)
        if process_start_lock is None:
            process_start_lock = threading.RLock()
            self._ros2_process_start_lock = process_start_lock
        with process_start_lock:
            if self.ros2_proc_status(process_name) == "running":
                tracked_process = getattr(self, "_ros2_procs", {}).get(process_name)
                if tracked_process is None:
                    return (
                        "Hardware Stack cannot verify the tracked process for "
                        f"{process_name}"
                    )
                tracked_pid = int(getattr(tracked_process, "pid", 0) or 0)
                error = self.ros2_stop(
                    process_name,
                    reason="hardware_robot_state_publisher_authority",
                )
                if error:
                    return (
                        "Hardware Stack could not stop "
                        f"{process_name}: {error}"
                    )
                try:
                    return_code = tracked_process.poll()
                except OSError as exc:
                    return (
                        "Hardware Stack could not verify terminal state for "
                        f"{process_name} pid={tracked_pid}: {type(exc).__name__}: {exc}"
                    )
                if return_code is None:
                    return (
                        "Hardware Stack requires exclusive UR5e TF authority, but "
                        f"{process_name} pid={tracked_pid} did not reach terminal state"
                    )
            if self.ros2_proc_status(process_name) == "running":
                return (
                    "Hardware Stack requires exclusive UR5e TF authority, but "
                    f"{process_name} is still running"
                )
        return None

    def _ros2_start_hardware_stack_locked(self, robot: str) -> str | None:
        """Start one Hardware Stack while the lifecycle lock is held."""
        key = str(robot).strip().lower()
        stack = self._hardware_stack_for_robot(key)
        if not stack:
            return f"unknown hardware robot: {robot}"
        if self._any_running(self._GAZEBO_PROCESS_NAMES):
            return "Hardware stack blocked: Gazebo is running. Stop Gazebo first."

        active_stack = self._active_normal_hardware_stack()
        if active_stack and active_stack != key:
            return (
                f"Hardware stack blocked: {active_stack} Hardware Stack is running. "
                "Stop it before starting another Hardware Stack."
            )

        hw_links = self.hardware_connection_statuses(force=True)
        required_robots = ("xarm6", "ur5e") if key == "dual robots" else (key,)
        authority_error = (
            self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
        )
        if authority_error:
            return authority_error
        for required_robot in required_robots:
            self._hardware_cartesian_readiness_states()[required_robot] = {
                "cartesian_jog_ready": False,
                "cartesian_function_ready": False,
                "generation": int(
                    getattr(self, "_hardware_stack_lifecycle_generation", 0) or 0
                ),
                "message": "Cartesian frame validation has not completed",
            }
        for required_robot in required_robots:
            entry = hw_links.get(required_robot, {})
            if not entry.get("reachable", False):
                ip = str(entry.get("ip", "")).strip() or "(unknown IP)"
                msg = str(entry.get("message", "unreachable")).strip()
                return f"{required_robot} hardware is unreachable at {ip} ({msg})"

        self.robot_env = "real"
        self._stop_teleop_server()
        self._clear_ros_action_service_snapshot()
        for agent_attr in (
            "_xarm6_robot_function_agent",
            "_ur5e_robot_function_agent",
        ):
            agent = getattr(self, agent_attr, None)
            controller = getattr(agent, "_controller", None)
            shutdown = getattr(controller, "shutdown", None)
            if callable(shutdown):
                shutdown()
            if agent is not None:
                agent._controller = None
                agent._controller_prewarm_done = False

        if key == "dual robots":
            started_here: list[str] = []

            def _rollback(message: str) -> str:
                for process_name in reversed(started_here):
                    self.ros2_stop(process_name, reason="dual_hardware_start_rollback")
                self._clear_ros_action_service_snapshot()
                return message

            xarm_driver = "hardware_xarm6_driver"
            ur5e_driver = "hardware_ur5e_rtde_trajectory_server"
            ur5e_gripper = "hardware_ur5e_rg2_gripper"
            state_publisher = "hardware_robot_state_publisher"

            if self.ros2_proc_status(xarm_driver) != "running":
                err = self.ros2_start(xarm_driver)
                if err:
                    return _rollback(f"dual robots xarm6 driver startup failed: {err}")
                started_here.append(xarm_driver)
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback(err)
            if self.ros2_proc_status(state_publisher) != "running":
                err = self.ros2_start(state_publisher)
                if err:
                    return _rollback(f"dual robots state publisher startup failed: {err}")
                started_here.append(state_publisher)
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback(err)
            err = self._wait_with_ros2_daemon_retry(
                "dual robots xarm6 controller_manager",
                lambda: self._wait_for_ros_service(
                    "/xarm6/controller_manager/list_controllers",
                    timeout_sec=22.0,
                    process_name=xarm_driver,
                ),
            )
            if err:
                return _rollback(f"dual robots xarm6 driver is not ready: {err}")
            err = self._wait_for_ros_services(
                (
                    "/xarm6/xarm/set_mode",
                    "/xarm6/xarm/set_state",
                ),
                timeout_sec=18.0,
                process_name=xarm_driver,
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 trajectory mode services are not ready: {err}"
                )
            err = self._wait_for_ros_topic_publisher(
                "/xarm6/xarm/robot_states",
                timeout_sec=18.0,
                process_name=xarm_driver,
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 controller TCP feedback is not ready: {err}"
                )
            err = self._prepare_xarm6_trajectory_mode(
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 trajectory Mode 1 is not ready: {err}"
                )
            err = self._wait_for_ros_controllers_active(
                "/xarm6/controller_manager",
                ("joint_state_broadcaster", "xarm6_traj_controller"),
                timeout_sec=40.0,
                process_name=xarm_driver,
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 controllers are not active: {err}"
                )
            err = self._xarm6_hardware_feedback_error(
                process_name=xarm_driver,
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 hardware feedback is not ready: {err}"
                )
            err = self._wait_with_ros2_daemon_retry(
                "dual robots xarm6 trajectory controller",
                lambda: self._wait_for_ros_action(
                    "/xarm6/xarm6_traj_controller/follow_joint_trajectory",
                    timeout_sec=18.0,
                    process_name=xarm_driver,
                ),
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 trajectory controller is not ready: {err}"
                )
            err = self._wait_with_ros2_daemon_retry(
                "dual robots xarm6 gripper action",
                lambda: self._wait_for_ros_action(
                    "/xarm6/xarm_gripper/gripper_action",
                    timeout_sec=18.0,
                    process_name=xarm_driver,
                ),
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 gripper action is not ready: {err}"
                )
            err = self._wait_for_ros_service(
                "/xarm6/xarm/set_position",
                timeout_sec=18.0,
                process_name=xarm_driver,
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 Cartesian control is not ready: {err}"
                )
            err = self._wait_for_ros_services(
                (
                    "/xarm6/xarm/vc_set_cartesian_velocity",
                    "/xarm6/xarm/set_tcp_maxacc",
                    "/xarm6/controller_manager/switch_controller",
                ),
                timeout_sec=18.0,
                process_name=xarm_driver,
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 Cartesian Smooth Hold is not ready: {err}"
                )
            if self.ros2_proc_status(ur5e_driver) != "running":
                err = self._start_ur5e_rtde_trajectory_server(
                    ur5e_driver,
                    wait_for_action=False,
                )
                if err:
                    return _rollback(
                        f"dual robots ur5e RTDE trajectory server is not ready: {err}"
                    )
                started_here.append(ur5e_driver)
            err = self._start_ur5e_rtde_trajectory_server(
                ur5e_driver,
                stop_read_only_monitor=False,
            )
            if err:
                return _rollback(
                    f"dual robots ur5e RTDE trajectory server is not ready: {err}"
                )
            err = self._wait_with_ros2_daemon_retry(
                "dual robots ur5e RTDE /joint_states publisher",
                lambda: self._wait_for_ros_topic_publisher(
                    "/joint_states",
                    timeout_sec=20.0,
                    process_name=ur5e_driver,
                ),
            )
            if err:
                return _rollback(
                    "dual robots ur5e RTDE trajectory server is not publishing "
                    f"/joint_states: {err}"
                )

            if self.ros2_proc_status(ur5e_gripper) != "running":
                err = self.ros2_start(ur5e_gripper)
                if err:
                    return _rollback(f"dual robots RG2 bridge startup failed: {err}")
                started_here.append(ur5e_gripper)
            err = self._wait_with_ros2_daemon_retry(
                "dual robots ur5e RG2 gripper bridge",
                lambda: self._wait_for_ros_action(
                    _UR5E_RG2_GRIPPER_ACTION,
                    timeout_sec=12.0,
                    process_name=ur5e_gripper,
                ),
            )
            if err:
                return _rollback(f"dual robots RG2 gripper bridge is not ready: {err}")

            err = self._wait_for_xarm6_relayed_tf_ready(
                driver_process_name=xarm_driver,
                state_publisher_process_name=state_publisher,
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback(
                    "dual robots xarm6 hardware feedback or TF world -> "
                    f"link_eef is not ready: {err}"
                )
            err = self._wait_for_ur5e_hardware_snapshot_ready(
                driver_process_name=ur5e_driver,
                state_publisher_process_name=state_publisher,
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback(
                    "dual robots ur5e feedback or TF world -> tool0 is not ready: "
                    f"{err}"
                )
            err = self._validate_xarm6_cartesian_frames(
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback(
                    f"dual robots xarm6 Cartesian frame validation failed: {err}"
                )
            err = self._wait_for_ur5e_cartesian_frame_ready(
                ur5e_driver,
                timeout_sec=15.0,
            )
            if err:
                return _rollback(
                    f"dual robots ur5e Cartesian frame validation failed: {err}"
                )
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback(err)
            return None

        if key == "xarm6":
            driver_name = "hardware_xarm6_driver"
            state_publisher = "hardware_robot_state_publisher"
            started_here: list[str] = []

            def _rollback_xarm6(message: str) -> str:
                for process_name in reversed(started_here):
                    self.ros2_stop(process_name, reason="xarm6_hardware_start_rollback")
                self._clear_ros_action_service_snapshot()
                return message

            if self.ros2_proc_status(driver_name) != "running":
                err = self.ros2_start(driver_name)
                if err:
                    return err
                started_here.append(driver_name)
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback_xarm6(err)
            if self.ros2_proc_status(state_publisher) != "running":
                err = self.ros2_start(state_publisher)
                if err:
                    return _rollback_xarm6(
                        f"xArm6 state publisher startup failed: {err}"
                    )
                started_here.append(state_publisher)
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback_xarm6(err)
            err = self._wait_for_ros_service(
                "/xarm6/controller_manager/list_controllers",
                timeout_sec=22.0,
                process_name=driver_name,
            )
            if err:
                return _rollback_xarm6(f"xArm6 hardware driver is not ready: {err}")
            err = self._wait_for_ros_services(
                (
                    "/xarm6/xarm/set_mode",
                    "/xarm6/xarm/set_state",
                ),
                timeout_sec=18.0,
                process_name=driver_name,
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 trajectory mode services are not ready: {err}"
                )
            err = self._wait_for_ros_topic_publisher(
                "/xarm6/xarm/robot_states",
                timeout_sec=18.0,
                process_name=driver_name,
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 controller TCP feedback is not ready: {err}"
                )
            err = self._prepare_xarm6_trajectory_mode(
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 trajectory Mode 1 is not ready: {err}"
                )
            err = self._wait_for_ros_controllers_active(
                "/xarm6/controller_manager",
                ("joint_state_broadcaster", "xarm6_traj_controller"),
                timeout_sec=40.0,
                process_name=driver_name,
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 hardware controllers are not active: {err}"
                )
            err = self._xarm6_hardware_feedback_error(
                process_name=driver_name,
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback_xarm6(f"xArm6 hardware feedback is not ready: {err}")
            err = self._wait_with_ros2_daemon_retry(
                "xarm6 trajectory controller",
                lambda: self._wait_for_ros_action(
                    "/xarm6/xarm6_traj_controller/follow_joint_trajectory",
                    timeout_sec=18.0,
                    process_name=driver_name,
                ),
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 trajectory controller is not ready: {err}"
                )
            err = self._wait_with_ros2_daemon_retry(
                "xarm6 gripper action",
                lambda: self._wait_for_ros_action(
                    "/xarm6/xarm_gripper/gripper_action",
                    timeout_sec=18.0,
                    process_name=driver_name,
                ),
            )
            if err:
                return _rollback_xarm6(f"xArm6 gripper action is not ready: {err}")
            err = self._wait_for_ros_service(
                "/xarm6/xarm/set_position",
                timeout_sec=18.0,
                process_name=driver_name,
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 Cartesian control is not ready: {err}"
                )
            err = self._wait_for_ros_services(
                (
                    "/xarm6/xarm/vc_set_cartesian_velocity",
                    "/xarm6/xarm/set_tcp_maxacc",
                    "/xarm6/controller_manager/switch_controller",
                ),
                timeout_sec=18.0,
                process_name=driver_name,
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 Cartesian Smooth Hold is not ready: {err}"
                )
            err = self._wait_for_xarm6_relayed_tf_ready(
                driver_process_name=driver_name,
                state_publisher_process_name=state_publisher,
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback_xarm6(
                    "xArm6 hardware feedback or TF world -> link_eef is not ready: "
                    f"{err}"
                )
            err = self._validate_xarm6_cartesian_frames(
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback_xarm6(
                    f"xArm6 Cartesian frame validation failed: {err}"
                )
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback_xarm6(err)
            return None

        driver_name = stack[0]
        gripper_names = tuple(name for name in stack[1:-1] if "rg2_gripper" in name)
        state_publisher = stack[-1]
        if key == "ur5e":
            started_here: list[str] = []

            def _rollback_ur5e(message: str) -> str:
                for process_name in reversed(started_here):
                    self.ros2_stop(process_name, reason="ur5e_hardware_start_rollback")
                self._clear_ros_action_service_snapshot()
                return message

            driver_was_running = self.ros2_proc_status(driver_name) == "running"
            if not driver_was_running:
                err = self._start_ur5e_rtde_trajectory_server(
                    driver_name,
                    wait_for_action=False,
                )
                if err:
                    return f"{key} RTDE trajectory server is not ready: {err}"
                started_here.append(driver_name)
            err = self._start_ur5e_rtde_trajectory_server(
                driver_name,
                stop_read_only_monitor=False,
            )
            if err:
                return _rollback_ur5e(
                    f"{key} RTDE trajectory server is not ready: {err}"
                )
            err = self._wait_with_ros2_daemon_retry(
                f"{key} RTDE /joint_states publisher",
                lambda: self._wait_for_ros_topic_publisher(
                    "/joint_states",
                    timeout_sec=20.0,
                    process_name=driver_name,
                ),
            )
            if err:
                return _rollback_ur5e(
                    f"{key} RTDE trajectory server is not publishing /joint_states: {err}"
                )
            for gripper_name in gripper_names:
                if self.ros2_proc_status(gripper_name) != "running":
                    err = self.ros2_start(gripper_name)
                    if err:
                        return _rollback_ur5e(err)
                    started_here.append(gripper_name)
                err = self._wait_with_ros2_daemon_retry(
                    f"{key} RG2 gripper bridge",
                    lambda gripper_name=gripper_name: self._wait_for_ros_action(
                        _UR5E_RG2_GRIPPER_ACTION,
                        timeout_sec=12.0,
                        process_name=gripper_name,
                    ),
                )
                if err:
                    return _rollback_ur5e(
                        f"{key} RG2 gripper bridge is not ready: {err}"
                    )
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback_ur5e(err)
            if self.ros2_proc_status(state_publisher) != "running":
                err = self.ros2_start(state_publisher)
                if err:
                    return _rollback_ur5e(f"{key} state publisher startup failed: {err}")
                started_here.append(state_publisher)
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback_ur5e(err)
            err = self._wait_for_ur5e_hardware_snapshot_ready(
                driver_process_name=driver_name,
                state_publisher_process_name=state_publisher,
                ros_domain_id=self._default_ros_domain_id(),
            )
            if err:
                return _rollback_ur5e(
                    "ur5e hardware feedback or TF world -> tool0 is not ready: "
                    f"{err}"
                )
            err = self._wait_for_ur5e_cartesian_frame_ready(
                driver_name,
                timeout_sec=15.0,
            )
            if err:
                return _rollback_ur5e(
                    f"ur5e Cartesian frame validation failed: {err}"
                )
            err = self._stop_ur5e_calibration_state_publisher_for_hardware_authority()
            if err:
                return _rollback_ur5e(err)
            return None
        return f"unknown hardware robot: {robot}"

    def ros2_stop_hardware_stack(self, robot: str) -> str | None:
        """Stop one Hardware Stack while rejecting concurrent lifecycle requests."""
        key = str(robot).strip().lower()
        if not self._hardware_stack_for_robot(key):
            return f"unknown hardware robot: {robot}"
        lifecycle_lock = getattr(self, "_hardware_stack_lifecycle_lock", None)
        if lifecycle_lock is None:
            lifecycle_lock = threading.Lock()
            self._hardware_stack_lifecycle_lock = lifecycle_lock
        if not lifecycle_lock.acquire(blocking=False):
            return "Hardware Stack start or stop is already running."
        execution_lock = self._get_robot_function_execution_lock()
        execution_lock_acquired = False
        try:
            execution_lock_acquired = bool(
                execution_lock.acquire(blocking=False)
            )
            if not execution_lock_acquired:
                return self._hardware_stack_lifecycle_motion_error(
                    "stop",
                    key,
                ) or (
                    "Cannot stop Hardware Stack while physical robot motion is active."
                )
            demonstration_error = (
                self._hardware_stack_active_insertion_error(
                    "stop",
                    key,
                )
            )
            if demonstration_error:
                return demonstration_error
            agent_motion_error = self._hardware_stack_agent_motion_error("stop")
            if agent_motion_error:
                return agent_motion_error
            smooth_stop_result = self._stop_cartesian_smooth_for_repair(key)
            if "stop was not confirmed" in smooth_stop_result:
                return smooth_stop_result
            if (
                key in {"xarm6", "dual robots"}
                and self._xarm6_cartesian_session_mode() != "off"
            ):
                session_closed, session_message = self.teleop_cartesian_mode(
                    "xarm6",
                    "off",
                )
                if not session_closed:
                    return session_message
            selected_stack = str(getattr(self, "_hardware_stack_selected", "") or "")
            if selected_stack and selected_stack != key:
                return (
                    f"Cannot stop {key} Hardware Stack while {selected_stack} Hardware "
                    "Stack is selected."
                )
            self._next_hardware_stack_generation()
            self._hardware_stack_selected = key
            self._hardware_stack_lifecycle_state = "stopping"
            error = self._ros2_stop_hardware_stack_locked(key)
            if error:
                self._hardware_stack_lifecycle_state = "failed"
                self._hardware_stack_last_error = error
                return error
            self._hardware_stack_selected = ""
            self._hardware_stack_lifecycle_state = "stopped"
            self._hardware_stack_last_error = ""
            self._hardware_stack_failed_process = ""
            self._hardware_stack_failed_return_code = None
            self._hardware_stack_process_log_path = ""
            stopped_robots = (
                ("xarm6", "ur5e") if key == "dual robots" else (key,)
            )
            for stopped_robot in stopped_robots:
                self._hardware_stack_stationary_results.pop(stopped_robot, None)
                self._hardware_stack_cartesian_jog_reset_results.pop(
                    stopped_robot,
                    None,
                )
            return None
        finally:
            if execution_lock_acquired:
                execution_lock.release()
            lifecycle_lock.release()

    def _hardware_stack_motion_error(self) -> str:
        """Return the active physical motion that prevents Hardware Stack repair."""
        execution_lock = getattr(self, "_ur5e_robot_function_execution_lock", None)
        if execution_lock is not None and execution_lock.locked():
            active = str(
                getattr(self, "_ur5e_robot_function_execution_active", None)
                or "UR5e motion"
            )
            return f"Cannot repair Hardware Stack while motion is active: {active}."
        return self._hardware_stack_agent_motion_error("repair")

    def _hardware_stack_agent_motion_error(self, operation: str) -> str:
        """Return a retained RobotAgent motion blocking one lifecycle operation."""
        for agent_attr in (
            "_xarm6_robot_function_agent",
            "_ur5e_robot_function_agent",
        ):
            agent = getattr(self, agent_attr, None)
            motion_lock = getattr(agent, "_robot_motion_lock", None)
            if motion_lock is not None and motion_lock.locked():
                return (
                    f"Cannot {operation} Hardware Stack while a RobotAgent motion "
                    "is active."
                )
        return ""

    def _hardware_stack_active_insertion_error(
        self,
        operation: str,
        robot: str,
    ) -> str:
        """Prevent UR5e teardown while an insertion action is actually active."""
        if str(robot or "").strip().lower() not in {"ur5e", "dual robots"}:
            return ""
        rtde_process_name = "hardware_ur5e_rtde_trajectory_server"
        rtde_running = self.ros2_proc_status(rtde_process_name) == "running"
        rtde_status = (
            dict(self._ur5e_rtde_trajectory_status() or {})
            if rtde_running
            else {}
        )
        if rtde_status.get("insertion_demonstration_active") is True:
            recording_id = str(
                rtde_status.get("insertion_demonstration_recording_id")
                or "<unknown>"
            )
            return (
                f"Cannot {operation} Hardware Stack while insertion demonstration "
                f"{recording_id} is active. Use Save Recording or Cancel "
                "Recording first."
            )
        if (
            str(rtde_status.get("state") or "").strip().lower()
            in {"checking", "executing"}
            and (
                str(rtde_status.get("trial_id") or "")
                or str(rtde_status.get("insert_phase") or "")
            )
        ):
            trial_id = str(rtde_status.get("trial_id") or "<unknown>")
            return (
                f"Cannot {operation} Hardware Stack while supervised move_insert "
                f"{trial_id} is active. Wait for terminal settlement."
            )
        with self._get_insertion_demonstration_lock():
            recording = getattr(self, "_insertion_demonstration", None)
            recording = deepcopy(recording) if isinstance(recording, dict) else None
        if (
            not rtde_running
            or recording is None
            or not bool(recording.get("active"))
        ):
            return ""
        if rtde_status.get("insertion_demonstration_active") is False:
            return ""
        recording_id = str(recording.get("recording_id") or "<unknown>")
        part_name = str(recording.get("part_name") or "<unknown>")
        return (
            f"Cannot {operation} Hardware Stack while insertion demonstration "
            f"{recording_id} for {part_name} is active. Use Save Recording or "
            "Cancel Recording first."
        )

    def _hardware_stack_lifecycle_motion_error(
        self,
        operation: str,
        robot: str,
    ) -> str:
        """Protect active physical work during stack lifecycle changes."""
        if operation in {"stop", "repair"}:
            demonstration_error = (
                self._hardware_stack_active_insertion_error(
                    operation,
                    robot,
                )
            )
            if demonstration_error:
                return demonstration_error
        motion_error = self._hardware_stack_motion_error()
        if motion_error:
            return motion_error.replace(
                "Cannot repair Hardware Stack",
                f"Cannot {operation} Hardware Stack",
                1,
            )
        return ""

    def _stop_cartesian_smooth_for_repair(self, robot: str) -> str:
        """Stop and release the selected stack's Smooth Hold before repair checks."""
        selected_robots = (
            {"xarm6", "ur5e"}
            if robot == "dual robots"
            else {str(robot or "").strip().lower()}
        )
        session_lock = getattr(self, "_teleop_smooth_session_lock", None)
        if session_lock is None:
            return "No Cartesian Smooth Hold session was active"
        with session_lock:
            session = getattr(self, "_teleop_smooth_session", None)
            if not session or str(session.get("robot") or "") not in selected_robots:
                return "No Cartesian Smooth Hold session was active"
            session_robot = str(session.get("robot") or "")
            ok, message, response_payload = self._teleop_request_payload(
                {
                    "op": "cartesian_smooth",
                    "robot": session_robot,
                    "command": "stop",
                    "axis": str(session.get("axis") or "x"),
                    "speed_mm_s": 0.0,
                    "watchdog_sec": 0.30,
                },
                timeout_sec=(
                    _XARM6_CARTESIAN_SMOOTH_HANDOFF_TIMEOUT_SEC
                    if session_robot == "xarm6"
                    else 4.0
                ),
                ros_domain_id=session.get("ros_domain_id"),
            )
            self._release_teleop_smooth_session()
        if ok:
            return f"Cartesian Smooth Hold stop confirmed: {message}"
        if response_payload.get("state_uncertain") is False:
            return (
                "Cartesian Smooth Hold stop confirmed; trajectory readiness failed: "
                f"{message}"
            )
        reason = f"Cartesian Smooth Hold stop was not confirmed: {message}"
        if session_robot == "ur5e":
            self._ur5e_cartesian_jog_state_uncertain = True
            self._ur5e_cartesian_jog_state_uncertain_reason = reason
        else:
            self._xarm6_cartesian_jog_state_uncertain = True
            self._xarm6_cartesian_jog_state_uncertain_reason = reason
        return reason

    def ros2_repair_hardware_stack(  # noqa: C901, PLR0912, PLR0915 - guarded lifecycle.
        self,
        robot: str,
    ) -> str | None:
        """Stop and restart one failed Hardware Stack under one lifecycle lock."""
        key = str(robot).strip().lower()
        if not self._hardware_stack_for_robot(key):
            return f"unknown hardware robot: {robot}"
        lifecycle_motion_error = self._hardware_stack_lifecycle_motion_error(
            "repair",
            key,
        )
        if lifecycle_motion_error:
            return lifecycle_motion_error
        smooth_stop_result = self._stop_cartesian_smooth_for_repair(key)
        if key in {"xarm6", "dual robots"} and self._xarm6_cartesian_session_mode() != "off":
            session_closed, session_message = self.teleop_cartesian_mode(
                "xarm6",
                "off",
            )
            smooth_stop_result = f"{smooth_stop_result}; {session_message}"
            if not session_closed and self._xarm6_cartesian_jog_state_uncertain:
                return session_message
        motion_error = self._hardware_stack_motion_error()
        if motion_error:
            return motion_error
        lifecycle_lock = getattr(self, "_hardware_stack_lifecycle_lock", None)
        if lifecycle_lock is None:
            lifecycle_lock = threading.Lock()
            self._hardware_stack_lifecycle_lock = lifecycle_lock
        if not lifecycle_lock.acquire(blocking=False):
            return "Hardware Stack start, stop, or repair is already running."
        execution_lock = getattr(self, "_ur5e_robot_function_execution_lock", None)
        execution_lock_acquired = False
        try:
            if execution_lock is not None:
                execution_lock_acquired = bool(execution_lock.acquire(blocking=False))
                if not execution_lock_acquired:
                    return self._hardware_stack_motion_error()
            selected_stack = str(getattr(self, "_hardware_stack_selected", "") or "")
            if selected_stack and selected_stack != key:
                return (
                    f"Cannot repair {key} Hardware Stack while {selected_stack} "
                    "Hardware Stack is selected."
                )
            self._next_hardware_stack_generation()
            self._hardware_stack_selected = key
            self._hardware_stack_lifecycle_state = "stopping"
            stop_error = self._ros2_stop_hardware_stack_locked(key)
            if stop_error:
                self._hardware_stack_lifecycle_state = "failed"
                self._hardware_stack_last_error = stop_error
                return stop_error
            self._hardware_stack_lifecycle_state = "starting"
            self._hardware_stack_last_error = ""
            self._hardware_stack_failed_process = ""
            self._hardware_stack_failed_return_code = None
            self._hardware_stack_process_log_path = ""
            affected_robots = (
                ("xarm6", "ur5e") if key == "dual robots" else (key,)
            )
            jog_reset_results = getattr(
                self,
                "_hardware_stack_cartesian_jog_reset_results",
                None,
            )
            if not isinstance(jog_reset_results, dict):
                jog_reset_results = {}
                self._hardware_stack_cartesian_jog_reset_results = jog_reset_results
            for affected_robot in affected_robots:
                self._hardware_stack_stationary_results.pop(affected_robot, None)
                jog_reset_results[affected_robot] = (
                    f"pending; {smooth_stop_result}"
                )
            start_error = self._ros2_start_hardware_stack_locked(key)
            if start_error:
                self._hardware_stack_lifecycle_state = "failed"
                self._hardware_stack_last_error = start_error
                self._record_hardware_stack_start_failure(key, start_error)
                return start_error
            ownership_error = self._record_hardware_stack_validated_processes(key)
            if ownership_error:
                self._hardware_stack_lifecycle_state = "failed"
                self._hardware_stack_last_error = ownership_error
                self._record_hardware_stack_start_failure(key, ownership_error)
                return ownership_error
            for affected_robot in affected_robots:
                stationary_error = self._validate_hardware_stationary(
                    affected_robot,
                    ros_domain_id=self._default_ros_domain_id(),
                )
                readiness = dict(
                    self._hardware_cartesian_readiness_states().get(affected_robot)
                    or {}
                )
                generation = int(
                    getattr(self, "_hardware_stack_lifecycle_generation", 0) or 0
                )
                if stationary_error:
                    repair_error = (
                        f"{affected_robot} stationary feedback validation failed: "
                        f"{stationary_error}"
                    )
                elif int(readiness.get("generation", -1)) != generation:
                    repair_error = (
                        f"{affected_robot} Cartesian frame validation belongs to "
                        f"generation {readiness.get('generation')}, expected {generation}"
                    )
                elif (
                    readiness.get("cartesian_jog_ready") is not True
                    or readiness.get("cartesian_function_ready") is not True
                ):
                    repair_error = str(
                        readiness.get("message")
                        or f"{affected_robot} Cartesian frame validation failed"
                    )
                else:
                    repair_error = ""
                if repair_error:
                    self._hardware_stack_lifecycle_state = "failed"
                    self._hardware_stack_last_error = repair_error
                    jog_reset_results[affected_robot] = f"failed: {repair_error}"
                    return repair_error
                if affected_robot == "ur5e":
                    uncertainty_clear_error = (
                        self._clear_ur5e_hardware_state_uncertainty()
                    )
                    if uncertainty_clear_error:
                        self._hardware_stack_lifecycle_state = "failed"
                        self._hardware_stack_last_error = uncertainty_clear_error
                        jog_reset_results[affected_robot] = (
                            f"failed: {uncertainty_clear_error}"
                        )
                        return uncertainty_clear_error
                    self._ur5e_cartesian_jog_state_uncertain = False
                    self._ur5e_cartesian_jog_state_uncertain_reason = ""
                    self._ur5e_robot_function_state_uncertain = False
                    self._ur5e_robot_function_state_uncertain_reason = ""
                else:
                    self._xarm6_cartesian_jog_state_uncertain = False
                    self._xarm6_cartesian_jog_state_uncertain_reason = ""
                jog_reset_results[affected_robot] = (
                    f"cleared at generation {generation}; {smooth_stop_result}"
                )
            if "ur5e" in affected_robots:
                move_insert_repair_error = (
                    self._clear_move_insert_repair_gate_after_hardware_stack(
                        hardware_stack=key,
                        generation=int(
                            getattr(
                                self,
                                "_hardware_stack_lifecycle_generation",
                                0,
                            )
                            or 0
                        ),
                    )
                )
                if move_insert_repair_error:
                    self._hardware_stack_lifecycle_state = "failed"
                    self._hardware_stack_last_error = move_insert_repair_error
                    return move_insert_repair_error
            self._hardware_stack_lifecycle_state = "running"
            return None
        finally:
            if execution_lock_acquired:
                execution_lock.release()
            lifecycle_lock.release()

    def _ros2_stop_hardware_stack_locked(self, robot: str) -> str | None:
        """Stop one Hardware Stack while the lifecycle lock is held."""
        key = str(robot).strip().lower()
        stack = self._hardware_stack_for_robot(key)
        if not stack:
            return f"unknown hardware robot: {robot}"
        active_stack = self._active_normal_hardware_stack()
        selected_stack = str(getattr(self, "_hardware_stack_selected", "") or "")
        if active_stack and active_stack != key and selected_stack != key:
            return (
                f"Cannot stop {key} Hardware Stack while {active_stack} Hardware Stack "
                "owns the active hardware processes."
            )
        if len(stack) == 1:
            self.ros2_stop(stack[0])
            # Also stop potential legacy standalone driver if user launched it.
            self.ros2_stop("hardware_xarm6_driver")
        else:
            for process_name in reversed(stack):
                self.ros2_stop(process_name)
        validated_processes = getattr(
            self,
            "_hardware_stack_validated_process_pids",
            None,
        )
        if isinstance(validated_processes, dict):
            for process_name in stack:
                validated_processes.pop(process_name, None)
        self._stop_teleop_server()
        self._clear_ros_action_service_snapshot()
        stopped_robots = ("xarm6", "ur5e") if key == "dual robots" else (key,)
        for stopped_robot in stopped_robots:
            self._hardware_cartesian_readiness_states()[stopped_robot] = {
                "cartesian_jog_ready": False,
                "cartesian_function_ready": False,
                "generation": int(
                    getattr(self, "_hardware_stack_lifecycle_generation", 0) or 0
                ),
                "message": "Hardware Stack is stopped",
            }
        for agent_attr in (
            "_xarm6_robot_function_agent",
            "_ur5e_robot_function_agent",
        ):
            agent = getattr(self, agent_attr, None)
            controller = getattr(agent, "_controller", None)
            shutdown = getattr(controller, "shutdown", None)
            if callable(shutdown):
                shutdown()
            if agent is not None:
                agent._controller = None
                agent._controller_prewarm_done = False
        return None

    def _load_gazebo_controller_settings(
        self, robot: str
    ) -> tuple[dict[str, Any], dict[str, Any]] | None:
        robot_key = str(robot or "").strip().lower()
        path_map = {
            "xarm6": _XARM6_RESOURCE,
            "ur5e": _UR5E_RESOURCE,
        }
        cfg_path = path_map.get(robot_key)
        if not cfg_path or not cfg_path.exists():
            log.warning("Gazebo prewarm skipped; config file missing for %s", robot_key)
            return None

        try:
            raw = self.load_config(str(cfg_path))
        except Exception:
            log.exception("Gazebo prewarm failed reading config for %s", robot_key)
            return None

        block = raw.get(robot_key, {}) if isinstance(raw, dict) else {}
        gazebo_block = block.get("gazebo", {}) if isinstance(block, dict) else {}
        controller = gazebo_block.get("controller", {}) if isinstance(gazebo_block, dict) else {}
        named_positions = (
            gazebo_block.get("named_positions", {}) if isinstance(gazebo_block, dict) else {}
        )
        if not controller:
            log.warning("Gazebo prewarm skipped; controller config empty for %s", robot_key)
            return None
        if not isinstance(named_positions, dict):
            named_positions = {}
        return controller, named_positions

    def _prewarm_gazebo_controller(self, robot: str) -> tuple[bool, float, str]:
        start_ts = time.monotonic()
        robot_key = str(robot or "").strip().lower()
        settings = self._load_gazebo_controller_settings(robot_key)
        if settings is None:
            return False, time.monotonic() - start_ts, "controller config missing"
        controller_cfg, named_positions = settings
        keep_controller_alive = str(
            os.environ.get("CAIS_KEEP_GAZEBO_PREWARM_CONTROLLERS", "0")
        ).strip().lower() not in {"0", "false", "no", "off"}

        with self._gazebo_prewarm_lock:
            existing = self._gazebo_prewarm_controllers.get(robot_key)
        if existing is not None:
            if keep_controller_alive:
                try:
                    if existing.wait_for_services(timeout_sec=1.0):
                        log.info("Gazebo prewarm already ready for %s", robot_key)
                        return True, time.monotonic() - start_ts, "reused existing controller"
                except Exception:
                    pass
            try:
                existing.shutdown()
            except Exception:
                pass
            with self._gazebo_prewarm_lock:
                self._gazebo_prewarm_controllers.pop(robot_key, None)

        try:
            from cais_spade_llm.resources.robot.gazebo_pick_place_controller import (
                UR5E_JOINT_NAMES,
                UR5E_JOINT_STATES_TOPIC,
                XARM6_JOINT_NAMES,
                XARM6_JOINT_STATES_TOPIC,
                GazeboPickPlaceController,
            )
        except Exception:
            log.exception("Gazebo prewarm failed importing controller modules for %s", robot_key)
            return False, time.monotonic() - start_ts, "controller import failure"

        controller = None
        detail = ""
        try:
            if robot_key == "xarm6":
                prewarm_node = f"xarm6_prewarm_controller_{os.getpid()}_{int(time.monotonic() * 1000) % 1000000}"
                controller = GazeboPickPlaceController(
                    robot_name="xarm6",
                    node_name=prewarm_node,
                    controller_config=controller_cfg,
                    named_positions=named_positions,
                    execution_mode="simulation",
                    arm_joint_names=XARM6_JOINT_NAMES,
                    arm_trajectory_topic=None,
                    joint_states_topic=XARM6_JOINT_STATES_TOPIC,
                )
            elif robot_key == "ur5e":
                prewarm_node = f"ur5e_prewarm_controller_{os.getpid()}_{int(time.monotonic() * 1000) % 1000000}"
                controller = GazeboPickPlaceController(
                    robot_name="ur5e",
                    node_name=prewarm_node,
                    controller_config=controller_cfg,
                    named_positions=named_positions,
                    execution_mode="simulation",
                    arm_joint_names=UR5E_JOINT_NAMES,
                    arm_trajectory_topic=_UR5E_GAZEBO_ARM_TRAJECTORY_TOPIC,
                    joint_states_topic=UR5E_JOINT_STATES_TOPIC,
                )
            else:
                return False, time.monotonic() - start_ts, f"unknown robot {robot_key}"

            start = time.monotonic()
            ok = bool(controller.wait_for_services(timeout_sec=self._GAZEBO_PREWARM_TIMEOUT_S))
            elapsed = time.monotonic() - start
            if ok:
                if keep_controller_alive:
                    with self._gazebo_prewarm_lock:
                        old = self._gazebo_prewarm_controllers.pop(robot_key, None)
                        self._gazebo_prewarm_controllers[robot_key] = controller
                    if old is not None and old is not controller:
                        try:
                            old.shutdown()
                        except Exception:
                            pass
                    controller = None  # kept alive for reuse; cleaned up when Gazebo stops
                else:
                    try:
                        controller.shutdown()
                    except Exception:
                        log.exception("Gazebo prewarm cleanup failed for %s", robot_key)
                    controller = None
                log.info("Gazebo prewarm ready for %s in %.2fs", robot_key, elapsed)
                return True, time.monotonic() - start_ts, "controller ready"
            else:
                log.warning("Gazebo prewarm not ready for %s after %.2fs", robot_key, elapsed)
                detail = str(
                    getattr(controller, "_last_failure_message", "")
                    or "wait_for_services returned false"
                ).strip()
                return False, time.monotonic() - start_ts, detail
        except Exception:
            log.exception("Gazebo prewarm exception for %s", robot_key)
            detail = "exception during controller prewarm"
            return False, time.monotonic() - start_ts, detail
        finally:
            if controller is not None:
                try:
                    controller.shutdown()
                except Exception:
                    log.exception("Gazebo prewarm cleanup failed for %s", robot_key)

    def _shutdown_gazebo_prewarm_controllers(self) -> None:
        # Signal any in-progress prewarm wait to stop immediately.
        self._gazebo_prewarm_cancel.set()
        prewarm_thread = None
        with self._gazebo_prewarm_lock:
            controllers = dict(self._gazebo_prewarm_controllers)
            self._gazebo_prewarm_controllers.clear()
            self._gazebo_prewarm_pending.clear()
            prewarm_thread = self._gazebo_prewarm_thread
        # Wait for the prewarm worker to exit (it checks cancel_event).
        if prewarm_thread is not None:
            prewarm_thread.join(timeout=5.0)
        for robot_key, controller in controllers.items():
            try:
                controller.shutdown()
            except Exception:
                log.exception("Gazebo prewarm controller shutdown failed for %s", robot_key)

    def _gazebo_prewarm_worker(self) -> None:
        try:
            # Use interruptible wait instead of blocking sleep.
            if self._gazebo_prewarm_cancel.wait(timeout=self._GAZEBO_PREWARM_START_DELAY_S):
                log.info("Gazebo prewarm cancelled during initial delay.")
                return
            while True:
                if self._gazebo_prewarm_cancel.is_set():
                    log.info("Gazebo prewarm cancelled.")
                    return

                with self._gazebo_prewarm_lock:
                    targets = sorted(self._gazebo_prewarm_pending)
                    self._gazebo_prewarm_pending.clear()

                if not targets:
                    return
                if not self._any_running(self._GAZEBO_PROCESS_NAMES):
                    log.info("Gazebo prewarm skipped; no Gazebo stack running.")
                    return
                launch = self._simulation_launch_key()

                # Phase 1: Wait only for the lightweight, consistently visible
                # MoveIt service via `ros2 service list`.  Custom Gazebo world
                # plugins like ATTACHLINK/DETACHLINK can be slow or flaky to
                # appear in shell probes under WSL even when direct ROS clients
                # can already connect, so those are verified in phase 2 by the
                # controller's actual service clients.
                phase1_targets = list(self._SIM_PREWARM_SHELL_SERVICES)
                self._gazebo_phase1_begin(phase1_targets)
                wait_err = self._wait_for_ros_services(
                    phase1_targets,
                    timeout_sec=self._GAZEBO_PREWARM_READY_WAIT_S,
                    cancel_event=self._gazebo_prewarm_cancel,
                    progress_cb=self._gazebo_note_service_ready,
                    pending_cb=self._gazebo_note_services_pending,
                )
                if wait_err:
                    self._gazebo_phase1_failed(wait_err)
                    log.info("Gazebo prewarm skipped (service not ready): %s", wait_err)
                    return

                self._gazebo_phase1_complete()
                probe_result = self._run_sim_ready_probe(launch)
                if launch != self._simulation_launch_key():
                    return
                if probe_result[1]:
                    log.info("Gazebo prewarm: %s", probe_result[1])
                log.info(
                    "Gazebo prewarm: all required services detected for %s — "
                    "creating controllers...",
                    ", ".join(targets),
                )

                # Phase 2: Create controllers now that services are confirmed
                # available.  This pre-initialises ROS2 nodes, spin threads,
                # MoveIt / TF clients so that REQ_1_T1 doesn't pay the startup
                # cost when "Start System" is pressed.
                if self._gazebo_prewarm_cancel.is_set():
                    return
                ready_count = 0
                failures: list[str] = []
                for robot_key in targets:
                    if self._gazebo_prewarm_cancel.is_set():
                        return
                    self._gazebo_note_prewarm_start(robot_key)
                    ok, elapsed, detail = self._prewarm_gazebo_controller(robot_key)
                    if ok:
                        ready_count += 1
                    else:
                        detail_text = (
                            str(detail or "controller not ready").strip() or "controller not ready"
                        )
                        failures.append(f"{robot_key}: {detail_text}")
                    self._gazebo_note_prewarm_result(robot_key, ok, elapsed, detail)

                if ready_count == len(targets):
                    # Signal that prewarm is done so simulation_start_ready() unblocks.
                    with self._gazebo_prewarm_lock:
                        if launch != self._simulation_launch_key():
                            return
                        self._gazebo_prewarm_launch = launch
                        self._gazebo_prewarm_done.set()
                        self._sim_ready_cache_launch = launch
                        self._sim_ready_cache = (True, self._simulation_perception_warning())
                        self._sim_ready_cache_ts = time.monotonic()
                    self._gazebo_launch_complete(ready_count, len(targets))
                    continue

                with self._gazebo_prewarm_lock:
                    if launch != self._simulation_launch_key():
                        return
                    self._sim_ready_cache_launch = launch
                    self._sim_ready_cache = (
                        False,
                        self._simulation_prewarm_failure_message(failures),
                    )
                    self._sim_ready_cache_ts = time.monotonic()
                meta = self._gazebo_launch_timing_snapshot()
                if meta:
                    self._gazebo_timing_emit(
                        f"launch#{meta.get('id', 0)} prewarm incomplete "
                        f"targets_ready={ready_count}/{len(targets)} detail={' | '.join(failures)}"
                    )
                return
        except Exception:
            log.exception("Gazebo prewarm worker crashed.")
        finally:
            with self._gazebo_prewarm_lock:
                self._gazebo_prewarm_thread = None
                if self._gazebo_prewarm_pending and not self._gazebo_prewarm_cancel.is_set():
                    self._gazebo_prewarm_thread = threading.Thread(
                        target=self._gazebo_prewarm_worker,
                        daemon=True,
                    )
                    self._gazebo_prewarm_thread.start()

    def _queue_gazebo_prewarm(self, launch_name: str) -> None:
        launch_key = str(launch_name or "").strip().lower()
        targets_by_launch = {
            "gazebo_dual": {"xarm6", "ur5e"},
            "gazebo_xarm6": {"xarm6"},
            "gazebo_ur5e": {"ur5e"},
        }
        if (
            launch_key == "gazebo_dual"
            and "world_file:=table_recovery_framework.world"
            in self.ROS2_LAUNCH_CMDS.get(launch_key, "")
        ):
            return
        targets = targets_by_launch.get(launch_key)
        if not targets:
            return

        with self._gazebo_prewarm_lock:
            self._gazebo_prewarm_cancel.clear()
            self._gazebo_prewarm_done.clear()
            self._gazebo_prewarm_pending.update(targets)
            if self._gazebo_prewarm_thread and self._gazebo_prewarm_thread.is_alive():
                return
            self._gazebo_prewarm_thread = threading.Thread(
                target=self._gazebo_prewarm_worker,
                daemon=True,
            )
            self._gazebo_prewarm_thread.start()
        log.info("Queued Gazebo controller prewarm for %s", ",".join(sorted(targets)))
        meta = self._gazebo_launch_timing_snapshot()
        if meta:
            launch_elapsed = time.monotonic() - float(meta.get("t0", time.monotonic()))
            self._gazebo_timing_emit(
                f"launch#{meta.get('id', 0)} prewarm queued targets={','.join(sorted(targets))} "
                f"launch_elapsed={launch_elapsed:.2f}s"
            )

    @staticmethod
    def _kill_stale_gazebo_helpers() -> None:
        """Best-effort cleanup for helper nodes that can survive ros2 launch shutdown."""
        for cmd in [
            "pkill -9 -f auto_link_attacher_node.py 2>/dev/null",
            "pkill -9 -f gazebo_camera_detector.py 2>/dev/null",
        ]:
            subprocess.run(["bash", "-c", cmd], capture_output=True)

    @staticmethod
    def _force_kill_digital_twin_helpers() -> None:
        """Hard-kill digital-twin stragglers that survive ros2 launch shutdown.

        Teach mode spawns sim + hardware MoveIt (two move_group + two rviz2); killing the
        tracked launch process group does not always take these down. Safe to pattern-kill
        here because a running digital twin blocks all other stacks (see
        _digital_twin_blocked_reason), so no unrelated move_group/rviz2 is expected.
        """
        for cmd in [
            "pkill -9 -f move_group 2>/dev/null",
            "pkill -9 -f rviz2 2>/dev/null",
            "pkill -9 -f dual_drag_markers.py 2>/dev/null",
            "pkill -9 -f digital_twin_sync.py 2>/dev/null",
            "pkill -9 -f physical_part_twin_sync.py 2>/dev/null",
            "pkill -9 -f xarm6_hardware_driver.launch.py 2>/dev/null",
            "pkill -9 -f XArm6JointStateRelay 2>/dev/null",
            "pkill -9 -f dual_robots_hardware_moveit.launch.py 2>/dev/null",
            "pkill -9 -f ur5e_rg2_hardware_moveit.launch.py 2>/dev/null",
            "pkill -9 -f xarm6_hardware_moveit.launch.py 2>/dev/null",
            "pkill -9 -f xarm6_moveit_realmove.launch.py 2>/dev/null",
            "pkill -9 -f ur5e_rg2_rtde_gripper.py 2>/dev/null",
            "pkill -9 -f ur5e_rtde_trajectory_server.py 2>/dev/null",
        ]:
            subprocess.run(["bash", "-c", cmd], capture_output=True)

    @staticmethod
    def _force_kill_gazebo_core(reason: str = "unspecified") -> None:
        """Hard-kill gzserver/gzclient and clean DDS shared memory.

        Called after stopping a Gazebo simulation and before starting a new one
        so that a surviving gzserver from a previous session does not hold port
        11345 or stale shared memory that would prevent the new simulation from
        spawning robots.
        """
        log.info("ROS2/Gazebo hard cleanup requested reason=%s", reason)
        for cmd in [
            "killall -9 gzserver gzclient 2>/dev/null",
            "pkill -9 -f gazebo 2>/dev/null",
            "pkill -9 -f spawn_entity.py 2>/dev/null",
            "pkill -9 -f 'spawner' 2>/dev/null",
        ]:
            subprocess.run(["bash", "-c", cmd], capture_output=True)
        for pattern in [
            "/dev/shm/fastrtps_*",
            "/dev/shm/cyclonedds_*",
            "/tmp/gazebo-*",
            "/tmp/.gazebo-*",
        ]:
            subprocess.run(
                ["bash", "-c", f"rm -rf {pattern} 2>/dev/null"],
                capture_output=True,
                timeout=5,
            )
        time.sleep(2)

    def ros2_start(self, name: str) -> str | None:
        """Start a ROS2 process by name. Returns error string or None on success."""
        if name not in self.ROS2_LAUNCH_CMDS:
            return f"Unknown process: {name}"
        if self.ros2_proc_status(name) == "running":
            return f"{name} is already running"
        prereq_err = self._ros2_launch_prereq_error(name)
        if prereq_err:
            return prereq_err
        if name == "perception":
            backend = (
                str(os.environ.get("PERCEPTION_BACKEND", self._perception_backend_for_mode()))
                .strip()
                .lower()
            )
            if backend != "gazebo_gt":
                return (
                    "Perception ROS2 process is simulation-only (gazebo_gt). "
                    "Use physical_perception for the RealSense backend 'yolo'."
                )
        if name == "physical_perception":
            if not str(os.environ.get("ROBOFLOW_API_KEY", "")).strip():
                return "ROBOFLOW_API_KEY is not configured in the ignored .env file."
            camera = self.perception_manager.config()["cameras"]["ur5e"]
            calibration = Path(str(camera["calibration_path"])).expanduser()
            if not calibration.is_file():
                return (
                    f"Hand-eye calibration is missing at {calibration}. "
                    "Run the ChArUco calibration command first."
                )

        # Keep simulation and hardware stacks mutually exclusive.
        if name in self._HARDWARE_PROCESS_NAMES and self._any_running(self._GAZEBO_PROCESS_NAMES):
            return "Hardware stack blocked: Gazebo is running. Stop Gazebo first."
        if name in self._GAZEBO_PROCESS_NAMES and self._any_running(self._HARDWARE_PROCESS_NAMES):
            return "Gazebo stack blocked: hardware processes are running. Stop hardware first."

        # Switching environments should restart teleop backend on next command.
        # Hardware Stack startup already performs one reset before starting its
        # component processes; keep that backend alive while the remaining dual
        # robot processes start so its xArm6 RobotMsg subscription stays warm.
        if name in self._HARDWARE_PROCESS_NAMES:
            environment_changed = str(getattr(self, "robot_env", "")) != "real"
            self.robot_env = "real"
            if environment_changed:
                self._stop_teleop_server()
        elif name in self._GAZEBO_PROCESS_NAMES:
            self.robot_env = "gazebo"
            self._stop_teleop_server()
            # Always purge any surviving gzserver/gzclient and stale shared
            # memory before launching a new simulation.  Without this, a
            # previous session that was not cleanly stopped leaves gzserver
            # holding port 11345, causing spawn_entity.py to time out and the
            # robot to never appear in the new Gazebo window.
            self._shutdown_gazebo_prewarm_controllers()
            self._kill_stale_gazebo_helpers()
            self._force_kill_gazebo_core(reason="prelaunch_restart")

        if name == "hardware_ur5e_moveit" or name == "hardware_dual_robots_moveit":
            err = self._start_ur5e_rtde_trajectory_server("hardware_ur5e_rtde_trajectory_server")
            if err:
                return f"UR5e RTDE trajectory server is not ready: {err}"

        cmd = self._ROS2_ENV + self._render_ros2_launch_cmd(name)
        process_start_lock = getattr(self, "_ros2_process_start_lock", None)
        if process_start_lock is None:
            process_start_lock = threading.RLock()
            self._ros2_process_start_lock = process_start_lock
        with process_start_lock:
            if self.ros2_proc_status(name) == "running":
                return f"{name} is already running"
            process_log = None
            try:
                getattr(self, "_ros2_process_return_codes", {}).pop(name, None)
                stdout: Any = subprocess.DEVNULL
                stderr: Any = subprocess.DEVNULL
                if name in self._BASE_HARDWARE_PROCESS_NAMES:
                    _LOG_DIR.mkdir(parents=True, exist_ok=True)
                    process_log = self._new_hardware_process_log_path(name).open(
                        "a",
                        encoding="utf-8",
                    )
                    stdout = process_log
                    stderr = subprocess.STDOUT
                proc = subprocess.Popen(
                    ["bash", "-c", cmd],
                    stdout=stdout,
                    stderr=stderr,
                    preexec_fn=os.setsid,  # New process group for clean shutdown.
                )
                self._ros2_procs[name] = proc
                if name in self._BASE_HARDWARE_PROCESS_NAMES:
                    generations = getattr(
                        self,
                        "_hardware_stack_process_generations",
                        None,
                    )
                    if not isinstance(generations, dict):
                        generations = {}
                        self._hardware_stack_process_generations = generations
                    generations[name] = int(
                        getattr(self, "_hardware_stack_lifecycle_generation", 0) or 0
                    )
                self._register_ui_process(name, proc, cmd)
                log.info("Started ROS2 process %s (pid=%d)", name, proc.pid)
                if name in self._GAZEBO_PROCESS_NAMES:
                    self._begin_gazebo_launch_timing(name, proc.pid)
                    self._queue_gazebo_prewarm(name)
                return None
            except Exception as exc:
                return str(exc)
            finally:
                if process_log is not None:
                    process_log.close()

    def ros2_stop(self, name: str, *, reason: str = "explicit_stop") -> str | None:
        """Stop a tracked ROS2 process without racing another process start."""
        process_start_lock = getattr(self, "_ros2_process_start_lock", None)
        if process_start_lock is None:
            process_start_lock = threading.RLock()
            self._ros2_process_start_lock = process_start_lock
        with process_start_lock:
            return self._ros2_stop_locked(name, reason=reason)

    def _ros2_stop_locked(
        self,
        name: str,
        *,
        reason: str = "explicit_stop",
    ) -> str | None:
        """Stop a tracked ROS2 process. Returns error string or None on success."""
        proc = self._ros2_procs.get(name)
        return_code = None if proc is None else proc.poll()
        if proc is None or return_code is not None:
            if return_code is not None:
                return_codes = getattr(self, "_ros2_process_return_codes", None)
                if return_codes is None:
                    return_codes = {}
                    self._ros2_process_return_codes = return_codes
                return_codes[name] = int(return_code)
            self._ros2_procs.pop(name, None)
            if proc is not None:
                self._cleanup_exited_ui_process(name, proc)
            else:
                self._unregister_ui_process(name, proc)
            if return_code is not None and (
                name == "hardware_ur5e_rtde_trajectory_server"
                or name == "digital_twin_ur5e_only_hardware_ur5e_rtde_trajectory_server"
                or name
                == "digital_twin_dual_robots_hardware_ur5e_rtde_trajectory_server"
            ):
                self._record_ur5e_rtde_trajectory_process_exit(name, int(return_code))
            if name in self._GAZEBO_PROCESS_NAMES and not self._any_running(
                self._GAZEBO_PROCESS_NAMES
            ):
                self._shutdown_gazebo_prewarm_controllers()
                self._kill_stale_gazebo_helpers()
            return None
        intentional_stops = getattr(self, "_ros2_intentional_stops", None)
        if intentional_stops is None:
            intentional_stops = set()
            self._ros2_intentional_stops = intentional_stops
        intentional_stops.add(name)
        try:
            try:
                os.killpg(os.getpgid(proc.pid), signal.SIGINT)
                try:
                    proc.wait(timeout=8)
                except subprocess.TimeoutExpired:
                    os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
                    proc.wait(timeout=3)
                log.info("Stopped ROS2 process %s", name)
            except Exception as exc:
                log.warning("Error stopping %s: %s", name, exc)
            self._ros2_procs.pop(name, None)
            self._unregister_ui_process(name, proc)
        finally:
            intentional_stops.discard(name)
        if name in self._GAZEBO_PROCESS_NAMES and not self._any_running(self._GAZEBO_PROCESS_NAMES):
            self._shutdown_gazebo_prewarm_controllers()
            self._kill_stale_gazebo_helpers()
            self._force_kill_gazebo_core(reason=reason)
        return None

    def ros2_stop_all(self, *, reason: str = "explicit_stop") -> None:
        """Stop all tracked ROS2 processes."""
        self._stop_teleop_server()
        for name in list(self._ros2_procs):
            self.ros2_stop(name, reason=reason)
        self._hardware_stack_selected = ""
        self._hardware_stack_lifecycle_state = "stopped"
        self._hardware_stack_last_error = ""
        self._hardware_stack_failed_process = ""
        self._hardware_stack_failed_return_code = None
        self._hardware_stack_process_log_path = ""
        self._shutdown_gazebo_prewarm_controllers()
        self._kill_stale_gazebo_helpers()
        self._force_kill_gazebo_core(reason=reason)

    def ros2_kill_gazebo(self) -> None:
        """Kill any orphan Gazebo / ROS2 processes (cleanup helper)."""
        self._stop_teleop_server()
        self._shutdown_gazebo_prewarm_controllers()
        log.info("ROS2/Gazebo hard cleanup requested reason=explicit_cleanup")
        for cmd in [
            (
                "killall -9 gzserver gzclient robot_state_publisher spawner spawn_entity.py "
                "rviz2 move_group static_transform_publisher ros2 2>/dev/null"
            ),
            "pkill -9 -f gazebo 2>/dev/null",
            "pkill -9 -f keyboard_teleop.py 2>/dev/null",
            "pkill -9 -f dual_drag_markers.py 2>/dev/null",
            "pkill -9 -f digital_twin_sync.py 2>/dev/null",
            "pkill -9 -f physical_part_twin_sync.py 2>/dev/null",
            "pkill -9 -f xarm6_hardware_driver.launch.py 2>/dev/null",
            "pkill -9 -f XArm6JointStateRelay 2>/dev/null",
            "pkill -9 -f ur5e_rg2_rtde_gripper.py 2>/dev/null",
        ]:
            subprocess.run(["bash", "-c", cmd], capture_output=True)
        self._kill_stale_gazebo_helpers()
        self._cleanup_shm_and_tmp()

    def ros2_cleanup_processes(self) -> None:
        """Aggressively clean stale ROS2/MoveIt/driver processes without killing the UI."""
        self._stop_teleop_server()
        self._shutdown_gazebo_prewarm_controllers()
        for name in list(self._ros2_procs):
            self.ros2_stop(name, reason="explicit_cleanup")
        self._hardware_stack_selected = ""
        self._hardware_stack_lifecycle_state = "stopped"
        self._hardware_stack_last_error = ""
        self._hardware_stack_failed_process = ""
        self._hardware_stack_failed_return_code = None
        self._hardware_stack_process_log_path = ""

        # Kill common stale processes that often block hardware reconnection.
        log.info("ROS2/Gazebo hard cleanup requested reason=explicit_cleanup")
        for cmd in [
            "killall -9 gzserver gzclient 2>/dev/null",
            "killall -9 move_group rviz2 robot_state_publisher joint_state_publisher static_transform_publisher ros2_control_node 2>/dev/null",
            "pkill -9 -f keyboard_teleop.py 2>/dev/null",
            "pkill -9 -f dual_drag_markers.py 2>/dev/null",
            "pkill -9 -f physical_part_twin_sync.py 2>/dev/null",
            "pkill -9 -f spawn_entity.py 2>/dev/null",
            "pkill -9 -f xarm_driver_node 2>/dev/null",
            "pkill -9 -f controller_manager 2>/dev/null",
            "pkill -9 -f 'spawner' 2>/dev/null",
            "pkill -9 -f xarm6_hardware_driver.launch.py 2>/dev/null",
            "pkill -9 -f XArm6JointStateRelay 2>/dev/null",
            "pkill -9 -f xarm6_hardware_moveit.launch.py 2>/dev/null",
            "pkill -9 -f xarm6_moveit_realmove.launch.py 2>/dev/null",
            "pkill -9 -f dual_robots_hardware_moveit.launch.py 2>/dev/null",
            "pkill -9 -f ur_moveit.launch.py 2>/dev/null",
            "pkill -9 -f ur5e_rg2_hardware_moveit.launch.py 2>/dev/null",
            "pkill -9 -f ur5e_rg2_rtde_gripper.py 2>/dev/null",
            "pkill -9 -f ur5e_rtde_trajectory_server.py 2>/dev/null",
            "pkill -9 -f gazebo 2>/dev/null",
        ]:
            subprocess.run(["bash", "-c", cmd], capture_output=True)
        self._kill_stale_gazebo_helpers()
        self._cleanup_shm_and_tmp()

        self._ros2_procs = {k: p for k, p in self._ros2_procs.items() if p.poll() is None}

    @staticmethod
    def _cleanup_shm_and_tmp() -> None:
        """Remove stale DDS shared-memory and Gazebo temp/lock files (WSL2)."""
        import time

        for pattern in [
            "/dev/shm/fastrtps_*",
            "/dev/shm/cyclonedds_*",
            "/tmp/gazebo-*",
            "/tmp/.gazebo-*",
        ]:
            subprocess.run(
                ["bash", "-c", f"rm -rf {pattern} 2>/dev/null"],
                capture_output=True,
                timeout=5,
            )
        time.sleep(3)

    @staticmethod
    def _tail_output(text: str) -> str:
        lines = [line.strip() for line in (text or "").splitlines() if line.strip()]
        if not lines:
            return ""
        return lines[-1]

    def ros2_exec(self, command: str, timeout_sec: float = 20.0) -> tuple[bool, str]:
        """Execute a short ROS2 shell command in a sourced environment."""
        full_cmd = self._ROS2_ENV + command
        try:
            cp = subprocess.run(
                ["bash", "-c", full_cmd],
                capture_output=True,
                text=True,
                timeout=max(1.0, float(timeout_sec)),
            )
        except subprocess.TimeoutExpired:
            return False, f"command timed out after {timeout_sec:.0f}s"

        if cp.returncode != 0:
            detail = self._tail_output(cp.stderr) or self._tail_output(cp.stdout)
            if detail:
                return False, detail
            return False, f"command failed (exit {cp.returncode})"

        return True, self._tail_output(cp.stdout) or "OK"

    def reset_plan_runtime_state(self) -> tuple[bool, str]:
        """
        Reset runtime plan/product/resource snapshots kept under monitor/.

        This archives current monitor files (plan/state/history/debug) so the
        next run starts from a clean runtime state.
        """
        if self.system_running or self._starting:
            return (
                False,
                "Stop the agent system before resetting plan/runtime state.",
            )
        if self._stopping:
            return False, "System stop is in progress. Wait before reset."

        self._clear_cached_plan_safety_alerts()
        counts = self._archive_monitors()
        total = sum(int(v) for v in counts.values()) if isinstance(counts, dict) else 0
        if total <= 0:
            return True, "Plan/runtime state already clean."
        return True, f"Plan/runtime state reset ({total} file(s) archived)."

    def _load_gazebo_reset_model_poses(
        self,
    ) -> dict[str, tuple[float, float, float, float, float, float]]:
        if self._gazebo_reset_pose_cache is not None:
            return dict(self._gazebo_reset_pose_cache)
        if not _GAZEBO_WORLD_FILE.exists():
            return {}

        poses: dict[str, tuple[float, float, float, float, float, float]] = {}
        try:
            root = ET.parse(_GAZEBO_WORLD_FILE).getroot()
            for model in [*root.findall(".//world/model"), *root.findall(".//world/include")]:
                name = str(
                    model.get("name", "") if model.tag == "model" else model.findtext("name", "")
                ).strip()
                if not name or not any(
                    name.startswith(prefix) for prefix in _RESETTABLE_GAZEBO_MODEL_PREFIXES
                ):
                    continue
                pose_text = str(model.findtext("pose", default="")).strip()
                if not pose_text:
                    continue
                parts = [float(v) for v in pose_text.split()]
                if len(parts) != 6:
                    continue
                poses[name] = tuple(parts)  # type: ignore[assignment]
        except Exception:
            log.exception("Failed parsing Gazebo world reset poses from %s", _GAZEBO_WORLD_FILE)
            poses = {}

        self._gazebo_reset_pose_cache = dict(poses)
        return poses

    @staticmethod
    def _quaternion_from_rpy(
        roll: float, pitch: float, yaw: float
    ) -> tuple[float, float, float, float]:
        cr = math.cos(roll * 0.5)
        sr = math.sin(roll * 0.5)
        cp = math.cos(pitch * 0.5)
        sp = math.sin(pitch * 0.5)
        cy = math.cos(yaw * 0.5)
        sy = math.sin(yaw * 0.5)
        return (
            sr * cp * cy - cr * sp * sy,
            cr * sp * cy + sr * cp * sy,
            cr * cp * sy - sr * sp * cy,
            cr * cp * cy + sr * sp * sy,
        )

    def _acquire_gazebo_reset_controller(self, robot: str) -> tuple[Any | None, bool, str]:
        robot_key = str(robot or "").strip().lower()
        with self._gazebo_prewarm_lock:
            existing = self._gazebo_prewarm_controllers.get(robot_key)
        if existing is not None:
            try:
                if bool(getattr(existing, "is_usable", lambda: False)()):
                    return existing, False, ""
            except Exception:
                pass
            with self._gazebo_prewarm_lock:
                self._gazebo_prewarm_controllers.pop(robot_key, None)
            try:
                existing.shutdown()
            except Exception:
                pass

        settings = self._load_gazebo_controller_settings(robot_key)
        if settings is None:
            return None, False, f"{robot_key}: controller config unavailable"
        controller_cfg, named_positions = settings

        try:
            from cais_spade_llm.resources.robot.gazebo_pick_place_controller import (
                UR5E_JOINT_NAMES,
                UR5E_JOINT_STATES_TOPIC,
                XARM6_JOINT_NAMES,
                XARM6_JOINT_STATES_TOPIC,
                GazeboPickPlaceController,
            )
        except Exception as exc:
            return None, False, f"{robot_key}: controller import failed ({exc})"

        try:
            if robot_key == "xarm6":
                controller = GazeboPickPlaceController(
                    robot_name="xarm6",
                    node_name=f"xarm6_reset_controller_{os.getpid()}_{int(time.monotonic() * 1000) % 1000000}",
                    controller_config=controller_cfg,
                    named_positions=named_positions,
                    execution_mode="simulation",
                    arm_joint_names=XARM6_JOINT_NAMES,
                    arm_trajectory_topic=None,
                    joint_states_topic=XARM6_JOINT_STATES_TOPIC,
                )
            elif robot_key == "ur5e":
                controller = GazeboPickPlaceController(
                    robot_name="ur5e",
                    node_name=f"ur5e_reset_controller_{os.getpid()}_{int(time.monotonic() * 1000) % 1000000}",
                    controller_config=controller_cfg,
                    named_positions=named_positions,
                    execution_mode="simulation",
                    arm_joint_names=UR5E_JOINT_NAMES,
                    arm_trajectory_topic=_UR5E_GAZEBO_ARM_TRAJECTORY_TOPIC,
                    joint_states_topic=UR5E_JOINT_STATES_TOPIC,
                )
            else:
                return None, False, f"unknown robot: {robot_key}"
        except Exception as exc:
            return None, False, f"{robot_key}: controller init failed ({exc})"

        if not controller.wait_for_services(timeout_sec=15.0):
            detail = getattr(controller, "_last_failure_message", "") or "services not ready"
            try:
                controller.shutdown()
            except Exception:
                pass
            return None, False, f"{robot_key}: {detail}"
        return controller, True, ""

    def _restore_gazebo_scene_in_place(self) -> tuple[list[str], list[str]]:
        success_messages: list[str] = []
        warning_messages: list[str] = []
        part_poses = self._load_gazebo_reset_model_poses()
        part_names = sorted(part_poses.keys())

        controllers: list[tuple[str, Any, bool]] = []
        try:
            for robot_key in ("xarm6", "ur5e"):
                controller, owned, err = self._acquire_gazebo_reset_controller(robot_key)
                if controller is None:
                    warning_messages.append(err or f"{robot_key}: controller unavailable")
                    continue
                controllers.append((robot_key, controller, owned))

            primary_controller = controllers[0][1] if controllers else None

            for robot_key, controller, _owned in controllers:
                try:
                    try:
                        controller.open_gripper()
                    except Exception:
                        pass

                    detached_count = 0
                    for model_name in part_names:
                        try:
                            out = controller.detach_model(model_name, quiet=True)
                            if bool(out.get("success", False)):
                                detached_count += 1
                        except Exception:
                            continue
                    if detached_count > 0:
                        success_messages.append(f"{robot_key}: detached {detached_count} part(s)")

                    home_out = controller.move_home()
                    if bool(home_out.get("success", False)):
                        success_messages.append(f"{robot_key}: moved home")
                    else:
                        warning_messages.append(
                            f"{robot_key}: {str(home_out.get('message', 'move_home failed')).strip()}"
                        )
                except Exception as exc:
                    warning_messages.append(f"{robot_key}: reset failed ({exc})")

            if primary_controller and part_poses:
                restored = 0
                for model_name, pose in sorted(part_poses.items()):
                    x, y, z, roll, pitch, yaw = pose
                    qx, qy, qz, qw = self._quaternion_from_rpy(roll, pitch, yaw)
                    out = primary_controller.set_entity_pose(
                        model_name,
                        x=x,
                        y=y,
                        z=z,
                        qx=qx,
                        qy=qy,
                        qz=qz,
                        qw=qw,
                    )
                    if bool(out.get("success", False)):
                        restored += 1
                    else:
                        warning_messages.append(
                            f"{model_name}: {str(out.get('message', 'set_entity_pose failed')).strip()}"
                        )
                if restored > 0:
                    success_messages.append(f"restored {restored} part pose(s)")
            elif part_poses:
                warning_messages.append("No Gazebo controller available to restore part poses.")
        finally:
            for _robot_key, controller, owned in controllers:
                if not owned:
                    continue
                try:
                    controller.shutdown()
                except Exception:
                    pass

        return success_messages, warning_messages

    def ros2_reset_gazebo_environment(self) -> tuple[bool, str]:
        """
        Reset Gazebo to a clean initial scene.

        Sequence:
        1. Detach any gripped parts and open grippers.
        2. Move both robots home via MoveIt (before the world reset so
           the controllers and MoveIt state are still in sync).
        3. Call /reset_world to reset Gazebo physics/sim time.
        4. Restore loose parts to their initial poses.
        """
        if not self._any_running(self._GAZEBO_PROCESS_NAMES):
            return False, "Gazebo is not running."
        if self.system_running or self._starting:
            return (
                False,
                "Stop the agent system before resetting Gazebo to avoid state mismatch.",
            )

        # ── Discover the Gazebo reset service ──────────────────────
        ok, out = self._ros2_command_output(
            "ros2 service list",
            timeout_sec=5.0,
            emit_slow_diag=False,
            emit_failure_diag=False,
            emit_timeout_diag=False,
        )
        if not ok:
            return False, f"Failed to query ROS services: {out}"

        services = [line.strip() for line in out.splitlines() if line.strip()]
        candidates = (
            "/reset_world",
            "/gazebo/reset_world",
            "/reset_simulation",
            "/gazebo/reset_simulation",
        )
        selected = next(
            (
                svc
                for svc in candidates
                if any(name == svc or name.endswith(svc) for name in services)
            ),
            None,
        )
        if not selected:
            return (
                False,
                "No Gazebo reset service found (expected /reset_world or /reset_simulation).",
            )

        # ── Step 1+2: Detach parts, open grippers, move robots home ──
        success_messages, warning_messages = self._restore_gazebo_scene_in_place()

        # ── Step 3: Reset the Gazebo world ─────────────────────────
        call_ok, call_msg = self.ros2_exec(
            f'ros2 service call {selected} std_srvs/srv/Empty "{{}}"',
            timeout_sec=10.0,
        )
        if not call_ok:
            warning_messages.append(f"Gazebo reset failed via {selected}: {call_msg}")

        headline = f"Gazebo environment reset via {selected}."
        if warning_messages:
            detail = " ; ".join([headline] + success_messages + warning_messages)
            return False, detail
        detail = " ; ".join([headline] + success_messages) if success_messages else headline
        return True, detail

    def _stop_teleop_server_locked(self) -> None:
        proc = self._teleop_server_proc
        if proc is None:
            self._teleop_server_ros_domain_id = None
            return
        try:
            if proc.poll() is None:
                os.killpg(os.getpgid(proc.pid), signal.SIGINT)
                try:
                    proc.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
                    proc.wait(timeout=2)
        except Exception:
            pass
        self._teleop_server_proc = None
        self._teleop_server_ros_domain_id = None
        self._unregister_ui_process("interactive_teleop_server", proc)

    def _stop_teleop_server(self) -> None:
        session = self._teleop_smooth_session
        if session is not None:
            self.teleop_cartesian_smooth(
                str(session.get("robot") or ""),
                str(session.get("axis") or ""),
                0.0,
                "stop",
            )
        if self._xarm6_cartesian_session_mode() != "off":
            self.teleop_cartesian_mode("xarm6", "off")
        with self._teleop_server_lock:
            self._stop_teleop_server_locked()
        if self._teleop_smooth_session is not None:
            self._release_teleop_smooth_session()

    def _teleop_stderr_excerpt_locked(self, max_chars: int = 2000) -> str:
        proc = self._teleop_server_proc
        if proc is None or proc.stderr is None:
            return ""
        try:
            fd = proc.stderr.fileno()
            ready, _, _ = select.select([fd], [], [], 0)
            if not ready:
                return ""
            data = os.read(fd, max(1, int(max_chars)))
            return data.decode("utf-8", errors="replace").strip()
        except Exception:
            return ""

    def _read_teleop_response_locked(
        self,
        timeout_sec: float,
        *,
        expected_request_id: str | None = None,
    ) -> tuple[bool, str, dict[str, Any]]:
        proc = self._teleop_server_proc
        if proc is None or proc.stdout is None:
            return False, "teleop server not running", {}
        deadline = time.monotonic() + max(0.1, float(timeout_sec))
        while True:
            if proc.poll() is not None:
                code = proc.returncode
                stderr = self._teleop_stderr_excerpt_locked()
                self._stop_teleop_server_locked()
                detail = f"teleop server exited ({code})"
                if stderr:
                    detail = f"{detail}: {stderr}"
                return False, detail, {}

            remaining_sec = deadline - time.monotonic()
            if remaining_sec <= 0.0:
                stderr = self._teleop_stderr_excerpt_locked()
                detail = f"teleop response timeout after {timeout_sec:.1f}s"
                if expected_request_id:
                    detail = (
                        f"{detail}; command outcome is still pending for "
                        f"request_id={expected_request_id}"
                    )
                if stderr:
                    detail = f"{detail}: {stderr}"
                return False, detail, {}

            ready, _, _ = select.select(
                [proc.stdout.fileno()],
                [],
                [],
                max(0.1, remaining_sec),
            )
            if not ready:
                continue

            line = proc.stdout.readline()
            if not line:
                self._stop_teleop_server_locked()
                return False, "teleop server closed stdout", {}
            try:
                payload = json.loads(line)
            except Exception:
                return False, f"invalid teleop response: {line.strip()}", {}

            response_request_id = str(payload.get("request_id") or "").strip()
            if expected_request_id and response_request_id != expected_request_id:
                if not response_request_id:
                    return (
                        False,
                        "teleop response is missing request_id; restart the UI teleop backend",
                        payload,
                    )
                log.warning(
                    "Discarding late teleop response request_id=%s while waiting for %s",
                    response_request_id,
                    expected_request_id,
                )
                continue

            ok = bool(payload.get("ok"))
            msg = str(payload.get("msg", "")).strip()
            return ok, (msg or ("OK" if ok else "teleop command failed")), payload

    def _ensure_teleop_server_locked(self, ros_domain_id: int | None) -> str | None:
        try:
            resolved_domain_id = (
                int(ros_domain_id) if ros_domain_id is not None else self._default_ros_domain_id()
            )
        except (TypeError, ValueError):
            resolved_domain_id = self._default_ros_domain_id()
        proc = self._teleop_server_proc
        if (
            proc is not None
            and proc.poll() is None
            and self._teleop_server_ros_domain_id == resolved_domain_id
        ):
            return None
        self._stop_teleop_server_locked()

        quoted_script = shlex.quote(self._TELEOP_SCRIPT)
        trajectory_action = shlex.quote(_UR5E_RTDE_TRAJECTORY_ACTION)
        cmd = (
            f"python3.10 {quoted_script} --server --service-timeout-sec 8 "
            f"--tf-warmup-sec 0.2 --ur5e-hardware-trajectory-action {trajectory_action} "
            "--ur5e-hardware-result-timeout-sec "
            f"{_UR5E_RTDE_CLIENT_RESULT_TIMEOUT_SEC}"
        )
        try:
            proc = subprocess.Popen(
                ["bash", "-c", self._ROS2_ENV + self._ros2_domain_export(resolved_domain_id) + cmd],
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                bufsize=1,
                preexec_fn=os.setsid,
            )
        except Exception as exc:
            return f"failed to start teleop server: {exc}"

        self._teleop_server_proc = proc
        self._teleop_server_ros_domain_id = resolved_domain_id
        self._register_ui_process("interactive_teleop_server", proc, cmd)
        ok, msg, _payload = self._read_teleop_response_locked(timeout_sec=25.0)
        if not ok:
            self._stop_teleop_server_locked()
            return msg
        if msg.lower() != "ready":
            self._stop_teleop_server_locked()
            return f"unexpected teleop startup response: {msg}"
        return None

    def _teleop_request_payload(
        self,
        payload: dict[str, Any],
        timeout_sec: float,
        ros_domain_id: int | None = None,
    ) -> tuple[bool, str, dict[str, Any]]:
        with self._teleop_server_lock:
            err = self._ensure_teleop_server_locked(ros_domain_id)
            if err:
                return False, err, {}

            proc = self._teleop_server_proc
            if proc is None or proc.stdin is None:
                return False, "teleop server stdin unavailable", {}

            self._teleop_request_sequence = int(
                getattr(self, "_teleop_request_sequence", 0)
            ) + 1
            request_id = f"teleop-{self._teleop_request_sequence}"
            request_payload = dict(payload)
            request_payload["request_id"] = request_id

            try:
                proc.stdin.write(
                    json.dumps(request_payload, separators=(",", ":")) + "\n"
                )
                proc.stdin.flush()
            except Exception as exc:
                self._stop_teleop_server_locked()
                return False, f"failed to send teleop command: {exc}", {}

            ok, msg, response_payload = self._read_teleop_response_locked(
                timeout_sec=timeout_sec,
                expected_request_id=request_id,
            )
            return ok, msg, response_payload

    def _teleop_preflight(self, robot: str, op: str) -> dict[str, Any]:
        target = self.teleop_target(robot, op)
        warning = str(target.get("warning") or "")
        if warning:
            return target
        recording_cartesian_jog = bool(
            str(robot or "").strip().lower() == "ur5e"
            and str(op or "").strip().lower()
            in {"cartesian", "cartesian_smooth"}
            and (
                current_recording := self._current_insertion_demonstration()
            )
            is not None
            and bool(current_recording.get("active"))
            and not bool(current_recording.get("recovery_required"))
        )
        recording_read_only_state = bool(
            str(robot or "").strip().lower() == "ur5e"
            and str(op or "").strip().lower() == "state"
        )
        demonstration_error = (
            ""
            if recording_read_only_state
            else self._insertion_demonstration_blocking_error(
                allow_ur5e_cartesian_jog=recording_cartesian_jog
            )
        )
        if demonstration_error:
            target = dict(target)
            target["ready"] = False
            target["warning"] = demonstration_error
            if recording_cartesian_jog:
                self._insertion_demonstration_cartesian_blocker = (
                    demonstration_error
                )
            return target
        if (
            str(robot or "").strip().lower() == "ur5e"
            and target.get("environment") == "real"
        ):
            pending_review_error = (
                ""
                if recording_cartesian_jog or recording_read_only_state
                else self._move_insert_pending_review_error()
            )
            if pending_review_error:
                target = dict(target)
                target["ready"] = False
                target["warning"] = pending_review_error
                return target
        if (
            str(robot or "").strip().lower() == "ur5e"
            and str(op or "").strip().lower() == "joint"
            and target.get("environment") == "real"
        ):
            ready, message = self.teleop_named_position_readiness("ur5e")
            if not ready:
                target = dict(target)
                target["ready"] = False
                target["warning"] = message
                return target
            if (
                bool(
                    getattr(
                        self,
                        "_ur5e_robot_function_state_uncertain",
                        False,
                    )
                )
                and str(
                    getattr(
                        self,
                        "_ur5e_robot_function_state_uncertain_reason",
                        "",
                    )
                    or ""
                ).strip()
                == _UR5E_RTDE_RESET_UNCERTAINTY_REASON
            ):
                self._ur5e_robot_function_state_uncertain = False
                self._ur5e_robot_function_state_uncertain_reason = ""
        op_key = str(op or "").strip().lower()
        if target.get("environment") == "real" and op_key in {
            "cartesian",
            "cartesian_smooth",
        }:
            uncertain = bool(
                getattr(
                    self,
                    (
                        "_ur5e_robot_function_state_uncertain"
                        if str(robot).strip().lower() == "ur5e"
                        else "_xarm6_robot_function_state_uncertain"
                    ),
                    False,
                )
            )
            if uncertain and str(robot).strip().lower() != "ur5e":
                reason = str(
                    getattr(
                        self,
                        (
                            "_ur5e_robot_function_state_uncertain_reason"
                            if str(robot).strip().lower() == "ur5e"
                            else "_xarm6_robot_function_state_uncertain_reason"
                        ),
                        "",
                    )
                    or ""
                ).strip()
                target = dict(target)
                target["ready"] = False
                recovery_action = (
                    "Inspect the robot and click Repair Hardware Stack before "
                    "Cartesian motion."
                    if str(robot).strip().lower() == "ur5e"
                    else (
                        "Inspect the robot and complete Robot Functions -> move_home "
                        "before Cartesian motion."
                    )
                )
                target["warning"] = (
                    f"The physical {robot} state is uncertain. {recovery_action}"
                    + (f" Last failure: {reason}" if reason else "")
                )
                return target
            jog_uncertain = bool(
                getattr(
                    self,
                    (
                        "_ur5e_cartesian_jog_state_uncertain"
                        if str(robot).strip().lower() == "ur5e"
                        else "_xarm6_cartesian_jog_state_uncertain"
                    ),
                    False,
                )
            )
            if jog_uncertain and str(robot).strip().lower() != "ur5e":
                reason = str(
                    getattr(
                        self,
                        (
                            "_ur5e_cartesian_jog_state_uncertain_reason"
                            if str(robot).strip().lower() == "ur5e"
                            else "_xarm6_cartesian_jog_state_uncertain_reason"
                        ),
                        "",
                    )
                    or ""
                ).strip()
                target = dict(target)
                target["ready"] = False
                target["warning"] = (
                    f"The physical {robot} Cartesian jog state is uncertain. "
                    "Click Repair Hardware Stack before Cartesian motion."
                    + (f" Last failure: {reason}" if reason else "")
                )
                return target
            readiness = dict(
                target.get("hardware_cartesian_readiness")
                or self._hardware_cartesian_readiness_states().get(
                    str(robot).strip().lower()
                )
                or {}
            )
            if readiness.get("cartesian_jog_ready") is not True:
                target = dict(target)
                target["ready"] = False
                target["warning"] = str(
                    readiness.get("message")
                    or "Cartesian frame validation has not completed"
                )
        if recording_cartesian_jog:
            self._insertion_demonstration_cartesian_blocker = ""
        return target

    def _release_xarm6_cartesian_session_locked(self) -> None:
        timer = getattr(self, "_teleop_xarm6_cartesian_idle_timer", None)
        self._teleop_xarm6_cartesian_idle_timer = None
        if timer is not None:
            timer.cancel()
        session = getattr(self, "_teleop_xarm6_cartesian_session", None)
        self._teleop_xarm6_cartesian_session = None
        self._teleop_cartesian_modes["xarm6"] = "off"
        if not session:
            return
        agent_lock = session.get("agent_motion_lock")
        if session.get("agent_lock_acquired") and agent_lock is not None:
            with suppress(RuntimeError):
                agent_lock.release()
        if session.get("execution_lock_acquired"):
            with suppress(RuntimeError):
                self._ur5e_robot_function_execution_lock.release()
        self._ur5e_robot_function_execution_active = None

    def _schedule_xarm6_cartesian_idle_locked(self, delay_sec: float | None = None) -> None:
        timer = getattr(self, "_teleop_xarm6_cartesian_idle_timer", None)
        if timer is not None:
            timer.cancel()
        session = getattr(self, "_teleop_xarm6_cartesian_session", None)
        if not session:
            self._teleop_xarm6_cartesian_idle_timer = None
            return
        delay = max(
            0.1,
            float(
                _XARM6_CARTESIAN_SESSION_IDLE_SEC
                if delay_sec is None
                else delay_sec
            ),
        )
        timer = threading.Timer(delay, self._expire_xarm6_cartesian_session)
        timer.daemon = True
        self._teleop_xarm6_cartesian_idle_timer = timer
        timer.start()

    def _touch_xarm6_cartesian_session_locked(self) -> None:
        session = getattr(self, "_teleop_xarm6_cartesian_session", None)
        if not session:
            return
        session["last_activity_monotonic"] = time.monotonic()
        self._schedule_xarm6_cartesian_idle_locked()

    def _expire_xarm6_cartesian_session(self) -> None:
        lock = getattr(self, "_teleop_xarm6_cartesian_session_lock", None)
        if lock is None:
            return
        with lock:
            session = getattr(self, "_teleop_xarm6_cartesian_session", None)
            if not session:
                return
            if session.get("busy"):
                self._schedule_xarm6_cartesian_idle_locked(0.5)
                return
            idle_sec = time.monotonic() - float(
                session.get("last_activity_monotonic") or time.monotonic()
            )
            if idle_sec < _XARM6_CARTESIAN_SESSION_IDLE_SEC:
                self._schedule_xarm6_cartesian_idle_locked(
                    _XARM6_CARTESIAN_SESSION_IDLE_SEC - idle_sec
                )
                return
            ok, message = self.teleop_cartesian_mode("xarm6", "off")
            if not ok:
                log.warning("xArm6 Cartesian idle restoration failed: %s", message)

    def _xarm6_cartesian_session_mode(self) -> str:
        lock = getattr(self, "_teleop_xarm6_cartesian_session_lock", None)
        if lock is None:
            return "off"
        with lock:
            session = getattr(self, "_teleop_xarm6_cartesian_session", None)
            return str(session.get("mode") or "off") if session else "off"

    def teleop_cartesian_mode(  # noqa: C901 - explicit session and safety gates.
        self,
        robot: str,
        mode: str,
    ) -> tuple[bool, str]:
        """Prepare or close the explicit Interactive Teleop Cartesian mode."""
        key = str(robot or "").strip().lower()
        requested = str(mode or "").strip().lower()
        if key not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {key}"
        if requested not in {"off", "step", "smooth"}:
            return False, f"unknown Cartesian mode: {requested}"
        target = self.teleop_target(key, "cartesian")
        if str(target.get("environment") or "") != "real":
            self._teleop_cartesian_modes[key] = requested
            return True, f"{key} Cartesian {requested} selected for Gazebo"
        if key == "ur5e":
            if requested == "off":
                self._teleop_cartesian_modes[key] = requested
                return True, f"UR5e Cartesian {requested} ready"
            preflight = self._teleop_preflight(
                key,
                "cartesian_smooth" if requested == "smooth" else "cartesian",
            )
            warning = str(preflight.get("warning") or "")
            if warning:
                return False, warning
            ok, message, payload = self._teleop_request_payload(
                {
                    "op": "cartesian_readiness",
                    "robot": "ur5e",
                },
                timeout_sec=5.0,
                ros_domain_id=preflight.get("ros_domain_id"),
            )
            if not ok or payload.get("cartesian_jog_ready") is not True:
                return False, message or "UR5e Cartesian jog service is unavailable"
            self._teleop_cartesian_modes[key] = requested
            return True, f"UR5e Cartesian {requested} ready"

        lock = self._teleop_xarm6_cartesian_session_lock
        with lock:
            session = self._teleop_xarm6_cartesian_session
            if session is not None and session.get("busy"):
                return False, (
                    "xArm6 Cartesian command is still executing; wait for it to finish "
                    f"before selecting {requested}."
                )
            if requested == "off":
                if session is not None:
                    session["busy"] = True
                ros_domain_id = (
                    session.get("ros_domain_id")
                    if session is not None
                    else target.get("ros_domain_id")
                )
                ok, message, response = self._teleop_request_payload(
                    {
                        "op": "cartesian_mode",
                        "robot": "xarm6",
                        "mode": "off",
                    },
                    timeout_sec=_XARM6_CARTESIAN_SMOOTH_HANDOFF_TIMEOUT_SEC,
                    ros_domain_id=ros_domain_id,
                )
                self._release_xarm6_cartesian_session_locked()
                if not ok and response.get("state_uncertain") is not False:
                    reason = f"xArm6 Cartesian session close failed: {message}"
                    self._xarm6_cartesian_jog_state_uncertain = True
                    self._xarm6_cartesian_jog_state_uncertain_reason = reason
                self._teleop_cartesian_modes["xarm6"] = "off"
                return ok, message

            preflight = self._teleop_preflight("xarm6", "cartesian")
            warning = str(preflight.get("warning") or "")
            if warning:
                return False, warning
            if session is None:
                if not self._ur5e_robot_function_execution_lock.acquire(
                    timeout=_UR5E_TELEOP_HANDOFF_TIMEOUT_SEC
                ):
                    active = str(
                        self._ur5e_robot_function_execution_active
                        or "Physical robot motion"
                    )
                    return False, f"Physical robot motion is already active: {active}."
                resource_agent = self._physical_xarm6_robot_agent()
                agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
                agent_lock_acquired = False
                if agent_motion_lock is not None:
                    agent_lock_acquired = bool(
                        agent_motion_lock.acquire(
                            timeout=_UR5E_TELEOP_HANDOFF_TIMEOUT_SEC
                        )
                    )
                    if not agent_lock_acquired:
                        self._ur5e_robot_function_execution_lock.release()
                        return False, "The xarm6 RobotAgent is already executing motion."
                session = {
                    "mode": "off",
                    "ros_domain_id": preflight.get("ros_domain_id"),
                    "execution_lock_acquired": True,
                    "agent_motion_lock": agent_motion_lock,
                    "agent_lock_acquired": agent_lock_acquired,
                    "last_activity_monotonic": time.monotonic(),
                    "busy": True,
                }
                self._teleop_xarm6_cartesian_session = session
            else:
                session["busy"] = True
            self._ur5e_robot_function_execution_active = (
                f"Interactive Teleop xarm6 Cartesian {requested} session"
            )
            ok, message, response = self._teleop_request_payload(
                {
                    "op": "cartesian_mode",
                    "robot": "xarm6",
                    "mode": requested,
                },
                timeout_sec=_XARM6_CARTESIAN_SMOOTH_HANDOFF_TIMEOUT_SEC,
                ros_domain_id=session.get("ros_domain_id"),
            )
            if not ok:
                self._release_xarm6_cartesian_session_locked()
                if response.get("state_uncertain") is not False:
                    reason = f"xArm6 Cartesian {requested} preparation failed: {message}"
                    self._xarm6_cartesian_jog_state_uncertain = True
                    self._xarm6_cartesian_jog_state_uncertain_reason = reason
                return False, message
            session["mode"] = requested
            self._teleop_cartesian_modes["xarm6"] = requested
            session["busy"] = False
            self._touch_xarm6_cartesian_session_locked()
            return True, message

    def _teleop_request(self, payload: dict[str, Any], timeout_sec: float) -> tuple[bool, str]:
        robot = str(payload.get("robot") or "").strip().lower()
        op = str(payload.get("op") or "").strip().lower()
        xarm6_session_mode = self._xarm6_cartesian_session_mode()
        if xarm6_session_mode != "off" and not (
            robot == "xarm6" and op == "cartesian"
        ):
            closed, close_message = self.teleop_cartesian_mode("xarm6", "off")
            if not closed:
                return False, (
                    "xArm6 Cartesian session could not restore Mode 1 before "
                    f"{op}: {close_message}"
                )
            xarm6_session_mode = "off"
        if (
            robot == "xarm6"
            and op == "cartesian"
            and xarm6_session_mode not in {"off", "step"}
        ):
            return False, "Select xArm6 Cartesian Step before using World X/Y/Z Step."
        xarm6_session_owns_locks = bool(
            robot == "xarm6"
            and op == "cartesian"
            and xarm6_session_mode == "step"
        )
        execution_lock_acquired = False
        agent_motion_lock = None
        agent_lock_acquired = False
        if xarm6_session_owns_locks:
            with self._teleop_xarm6_cartesian_session_lock:
                session = self._teleop_xarm6_cartesian_session
                if session is None:
                    return False, "xArm6 Cartesian Step session expired; select Step again."
                session["busy"] = True
                self._touch_xarm6_cartesian_session_locked()
        elif robot in {"xarm6", "ur5e"}:
            if not self._ur5e_robot_function_execution_lock.acquire(
                timeout=_UR5E_TELEOP_HANDOFF_TIMEOUT_SEC
            ):
                active = str(
                    self._ur5e_robot_function_execution_active
                    or "Physical robot motion"
                )
                return False, (
                    f"{robot} motion handoff did not finish within "
                    f"{_UR5E_TELEOP_HANDOFF_TIMEOUT_SEC:.1f}s: {active}."
                )
            execution_lock_acquired = True
            resource_agent = (
                self._physical_ur5e_robot_agent()
                if robot == "ur5e"
                else self._physical_xarm6_robot_agent()
            )
            agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
            if agent_motion_lock is not None:
                agent_lock_acquired = bool(
                    agent_motion_lock.acquire(
                        timeout=_UR5E_TELEOP_HANDOFF_TIMEOUT_SEC
                    )
                )
                if not agent_lock_acquired:
                    self._ur5e_robot_function_execution_lock.release()
                    return False, (
                        f"The {robot} RobotAgent did not finish its motion handoff within "
                        f"{_UR5E_TELEOP_HANDOFF_TIMEOUT_SEC:.1f}s."
                    )
            self._ur5e_robot_function_execution_active = f"Interactive Teleop {op}"
        try:
            target = self._teleop_preflight(robot, op)
            warning = str(target.get("warning") or "")
            if warning:
                return False, warning
            ok, msg, response_payload = self._teleop_request_payload(
                payload=payload,
                timeout_sec=timeout_sec,
                ros_domain_id=target.get("ros_domain_id"),
            )
            completed_physical_ur5e_home = bool(
                ok
                and robot == "ur5e"
                and str(target.get("environment") or "") == "real"
                and (
                    op == "home"
                    or (
                        op == "move_joints"
                        and str(payload.get("named_position") or "") == "home"
                    )
                )
            )
            if completed_physical_ur5e_home:
                recovered, recovery_message = self._complete_ur5e_home_recovery()
                if not recovered:
                    return False, f"{msg}. {recovery_message}"
                msg = f"{msg}. {recovery_message}"
            if (
                not ok
                and str(target.get("environment") or "") == "real"
                and response_payload.get("state_uncertain") is not False
            ):
                failure_reason = f"Interactive Teleop {op} failed: {msg}"
                if op in {"cartesian", "cartesian_smooth"}:
                    if robot == "ur5e":
                        self._ur5e_cartesian_jog_state_uncertain = True
                        self._ur5e_cartesian_jog_state_uncertain_reason = failure_reason
                    elif robot == "xarm6":
                        self._xarm6_cartesian_jog_state_uncertain = True
                        self._xarm6_cartesian_jog_state_uncertain_reason = failure_reason
                elif op in {"home", "joint", "move_joints"} and robot == "ur5e":
                    self._ur5e_robot_function_state_uncertain = True
                    self._ur5e_robot_function_state_uncertain_reason = failure_reason
                elif op in {"home", "joint", "move_joints"} and robot == "xarm6":
                    self._xarm6_robot_function_state_uncertain = True
                    self._xarm6_robot_function_state_uncertain_reason = failure_reason
            return ok, msg
        finally:
            if xarm6_session_owns_locks:
                with self._teleop_xarm6_cartesian_session_lock:
                    session = self._teleop_xarm6_cartesian_session
                    if session is not None:
                        session["busy"] = False
                        self._touch_xarm6_cartesian_session_locked()
            if agent_lock_acquired:
                agent_motion_lock.release()
            if execution_lock_acquired:
                self._ur5e_robot_function_execution_active = None
                self._ur5e_robot_function_execution_lock.release()

    def _run_teleop_once(
        self,
        args: list[str],
        timeout_sec: float,
        ros_domain_id: int | None = None,
    ) -> tuple[bool, str]:
        quoted_script = shlex.quote(self._TELEOP_SCRIPT)
        quoted_args = " ".join(shlex.quote(str(arg)) for arg in args)
        trajectory_action = shlex.quote(_UR5E_RTDE_TRAJECTORY_ACTION)
        cmd = (
            f"python3.10 {quoted_script} --ur5e-hardware-trajectory-action "
            f"{trajectory_action} --ur5e-hardware-result-timeout-sec "
            f"{_UR5E_RTDE_CLIENT_RESULT_TIMEOUT_SEC} {quoted_args}"
        ).strip()
        return self.ros2_exec(
            self._ros2_domain_export(ros_domain_id) + cmd,
            timeout_sec=timeout_sec,
        )

    def teleop_jog(
        self,
        robot: str,
        axis: str,
        step_mm: float,
        velocity_scale: float = 1.0,
        *,
        speed_mm_s: float | None = None,
    ) -> tuple[bool, str]:
        robot = str(robot).strip().lower()
        axis = str(axis).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}"
        if axis not in {"x", "y", "z"}:
            return False, f"unknown axis: {axis}"
        if speed_mm_s is not None:
            try:
                exact_speed_mm_s = float(speed_mm_s)
            except (TypeError, ValueError):
                return False, f"{robot} Cartesian speed is not finite"
            settings = self.teleop_motion_settings(robot)
            minimum = float(settings["cartesian_speed_min_mm_s"])
            maximum = float(settings["cartesian_speed_max_mm_s"])
            if not math.isfinite(exact_speed_mm_s):
                return False, f"{robot} Cartesian speed is not finite"
            if not minimum <= exact_speed_mm_s <= maximum:
                return False, (
                    f"{robot} Cartesian speed {exact_speed_mm_s:.3f} mm/s is outside "
                    f"[{minimum:.3f}, {maximum:.3f}] mm/s"
                )
            if exact_speed_mm_s == 0.0:
                return False, f"{robot} Cartesian speed is 0; no motion was commanded"
            speed_mm_s = exact_speed_mm_s
        estimated_motion_sec = (
            abs(float(step_mm)) / float(speed_mm_s)
            if speed_mm_s is not None
            else 0.0
        )
        payload: dict[str, Any] = {
            "op": "cartesian",
            "robot": robot,
            "axis": axis,
            "step_mm": float(step_mm),
            "velocity_scale": float(velocity_scale),
        }
        if speed_mm_s is not None:
            payload["speed_mm_s"] = float(speed_mm_s)
        return self._teleop_request(
            payload=payload,
            timeout_sec=(
                max(
                    _UR5E_RTDE_CLIENT_RESULT_TIMEOUT_SEC + 5.0,
                    estimated_motion_sec + 15.0,
                )
                if robot == "ur5e"
                else max(18.0, estimated_motion_sec + 15.0)
            ),
        )

    def teleop_motion_settings(self, robot: str) -> dict[str, Any]:
        """Return the selected robot's explicit Interactive Teleop speed limits."""
        key = str(robot or "").strip().lower()
        if key not in {"xarm6", "ur5e"}:
            return {"robot": key, "error": f"unknown robot: {key}"}
        environment = str(self.teleop_target(key, "state").get("environment") or "")
        if key == "xarm6":
            cartesian_default = _XARM6_CARTESIAN_SPEED_MM_S
            cartesian_max = _XARM6_CARTESIAN_MAX_SPEED_MM_S
            cartesian_acceleration = _XARM6_CARTESIAN_ACCELERATION_MM_S2
            joint_max = _XARM6_MAX_JOINT_SPEED_DEG_S
            joint_default = 2.0 / (0.08 * 3.0769230769)
        else:
            cartesian_default = _UR5E_CARTESIAN_SPEED_MM_S
            cartesian_max = _UR5E_CARTESIAN_MAX_SPEED_MM_S
            cartesian_acceleration = _UR5E_CARTESIAN_ACCELERATION_MM_S2
            joint_max = _UR5E_MAX_JOINT_SPEED_DEG_S
            joint_default = 2.0 / 0.08
        return {
            "robot": key,
            "environment": environment,
            "physical_units": environment == "real",
            "cartesian_speed_min_mm_s": 0.0,
            "cartesian_speed_default_mm_s": cartesian_default,
            "cartesian_speed_max_mm_s": cartesian_max,
            "cartesian_acceleration_mm_s2": cartesian_acceleration,
            "joint_speed_min_deg_s": 0.0,
            "joint_speed_default_deg_s": min(joint_default, joint_max),
            "joint_speed_max_deg_s": joint_max,
        }

    def teleop_cartesian_smooth_active(self, robot: str) -> bool:
        """Return whether one robot owns the current Cartesian Smooth Hold session."""
        key = str(robot or "").strip().lower()
        lock = getattr(self, "_teleop_smooth_session_lock", None)
        if lock is None:
            session = getattr(self, "_teleop_smooth_session", None)
            return bool(session and session.get("robot") == key)
        with lock:
            session = getattr(self, "_teleop_smooth_session", None)
            return bool(session and session.get("robot") == key)

    def teleop_cartesian_readiness(self, robot: str) -> dict[str, Any]:
        """Return fail-closed Cartesian readiness for Interactive Teleop."""
        key = str(robot or "").strip().lower()
        target = self._teleop_preflight(key, "cartesian")
        warning = str(target.get("warning") or "").strip()
        readiness = dict(self._hardware_cartesian_readiness_states().get(key) or {})
        state_uncertain = bool(
            getattr(
                self,
                (
                    "_ur5e_robot_function_state_uncertain"
                    if key == "ur5e"
                    else "_xarm6_robot_function_state_uncertain"
                ),
                False,
            )
        )
        if key == "ur5e":
            state_uncertain = False
        cartesian_jog_state_uncertain = bool(
            getattr(
                self,
                (
                    "_ur5e_cartesian_jog_state_uncertain"
                    if key == "ur5e"
                    else "_xarm6_cartesian_jog_state_uncertain"
                ),
                False,
            )
        )
        if key == "ur5e":
            cartesian_jog_state_uncertain = False
        cartesian_mode = str(self._teleop_cartesian_modes.get(key) or "off")
        cartesian_mode_ready = bool(cartesian_mode in {"step", "smooth"})
        cartesian_mode_idle_remaining_sec = 0.0
        if key == "xarm6" and str(target.get("environment") or "") == "real":
            with self._teleop_xarm6_cartesian_session_lock:
                session = self._teleop_xarm6_cartesian_session
                if session is not None:
                    cartesian_mode = str(session.get("mode") or "off")
                    cartesian_mode_ready = bool(
                        cartesian_mode in {"step", "smooth"}
                        and not session.get("busy")
                    )
                    idle_sec = time.monotonic() - float(
                        session.get("last_activity_monotonic") or time.monotonic()
                    )
                    cartesian_mode_idle_remaining_sec = max(
                        0.0,
                        _XARM6_CARTESIAN_SESSION_IDLE_SEC - idle_sec,
                    )
        return {
            "robot": key,
            "environment": str(target.get("environment") or ""),
            "cartesian_jog_ready": bool(
                not warning and readiness.get("cartesian_jog_ready") is True
            ),
            "cartesian_function_ready": bool(
                not warning and readiness.get("cartesian_function_ready") is True
            ),
            "smooth_hold_active": bool(
                self._teleop_smooth_session
                and self._teleop_smooth_session.get("robot") == key
            ),
            "cartesian_mode": cartesian_mode,
            "cartesian_mode_ready": cartesian_mode_ready,
            "cartesian_mode_idle_remaining_sec": cartesian_mode_idle_remaining_sec,
            "state_uncertain": state_uncertain,
            "cartesian_jog_state_uncertain": cartesian_jog_state_uncertain,
            "message": warning or str(
                readiness.get("message")
                or "Cartesian frame validation has not completed"
            ),
            "diagnostics": dict(readiness.get("diagnostics") or {}),
        }

    def _release_teleop_smooth_session(self) -> None:
        session = self._teleop_smooth_session
        self._teleop_smooth_session = None
        xarm6_mode = self._xarm6_cartesian_session_mode()
        self._ur5e_robot_function_execution_active = (
            f"Interactive Teleop xarm6 Cartesian {xarm6_mode} session"
            if xarm6_mode != "off"
            else None
        )
        if not session:
            return
        agent_lock = session.get("agent_motion_lock")
        if session.get("agent_lock_acquired") and agent_lock is not None:
            with suppress(RuntimeError):
                agent_lock.release()
        if session.get("execution_lock_acquired"):
            with suppress(RuntimeError):
                self._ur5e_robot_function_execution_lock.release()

    def teleop_cartesian_smooth(  # noqa: C901, PLR0912 - guarded Smooth Hold lifecycle.
        self,
        robot: str,
        axis: str,
        speed_mm_s: float,
        command: str,
        *,
        watchdog_sec: float = 0.50,
    ) -> tuple[bool, str]:
        """Start, refresh, or stop one locked Cartesian Smooth Hold session."""
        key = str(robot or "").strip().lower()
        axis_key = str(axis or "").strip().lower()
        command_key = str(command or "").strip().lower()
        if key not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {key}"
        if command_key not in {"start", "update", "stop"}:
            return False, f"unknown Cartesian Smooth Hold command: {command_key}"
        if command_key != "stop" and axis_key not in {"x", "y", "z"}:
            return False, f"unknown axis: {axis_key}"
        with self._teleop_smooth_session_lock:
            session = self._teleop_smooth_session
            if command_key == "start":
                if session is not None:
                    return False, (
                        "Cartesian Smooth Hold is already active for "
                        f"{session.get('robot')} World {str(session.get('axis')).upper()}."
                    )
                target = self._teleop_preflight(key, "cartesian_smooth")
                warning = str(target.get("warning") or "")
                if warning:
                    return False, warning
                if str(target.get("environment") or "") != "real":
                    return False, "Cartesian Smooth Hold is available only for Hardware Stack."
                xarm6_session_owns_locks = bool(
                    key == "xarm6"
                    and self._xarm6_cartesian_session_mode() == "smooth"
                )
                if key == "xarm6" and not xarm6_session_owns_locks:
                    return False, (
                        "Select xArm6 Cartesian Smooth Hold and wait for Mode 5 ready."
                    )
                execution_lock_acquired = False
                agent_motion_lock = None
                agent_lock_acquired = False
                if not xarm6_session_owns_locks:
                    if not self._ur5e_robot_function_execution_lock.acquire(
                        blocking=False
                    ):
                        active = str(
                            self._ur5e_robot_function_execution_active
                            or "Physical robot motion"
                        )
                        return False, f"Physical robot motion is already active: {active}."
                    execution_lock_acquired = True
                    resource_agent = self._physical_ur5e_robot_agent()
                    agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
                    if agent_motion_lock is not None:
                        agent_lock_acquired = bool(
                            agent_motion_lock.acquire(blocking=False)
                        )
                        if not agent_lock_acquired:
                            self._ur5e_robot_function_execution_lock.release()
                            return False, f"The {key} RobotAgent is already executing motion."
                self._ur5e_robot_function_execution_active = (
                    f"Interactive Teleop {key} Cartesian Smooth Hold"
                )
                self._teleop_smooth_session = {
                    "robot": key,
                    "axis": axis_key,
                    "speed_mm_s": float(speed_mm_s),
                    "ros_domain_id": target.get("ros_domain_id"),
                    "execution_lock_acquired": execution_lock_acquired,
                    "agent_motion_lock": agent_motion_lock,
                    "agent_lock_acquired": agent_lock_acquired,
                    "xarm6_session_owns_locks": xarm6_session_owns_locks,
                }
                session = self._teleop_smooth_session
            elif session is None:
                return True, "Cartesian Smooth Hold already stopped"
            elif session.get("robot") != key:
                return False, (
                    f"Cartesian Smooth Hold belongs to {session.get('robot')}, not {key}."
                )
            elif command_key == "update" and session.get("axis") != axis_key:
                return False, "Release the active Cartesian axis before selecting another axis."

            payload = {
                "op": "cartesian_smooth",
                "robot": key,
                "command": command_key,
                "axis": axis_key or str(session.get("axis") or ""),
                "speed_mm_s": float(speed_mm_s),
                "watchdog_sec": min(0.50, max(0.10, float(watchdog_sec))),
            }
            if key == "xarm6":
                with self._teleop_xarm6_cartesian_session_lock:
                    xarm6_session = self._teleop_xarm6_cartesian_session
                    if xarm6_session is not None:
                        xarm6_session["busy"] = True
                        self._touch_xarm6_cartesian_session_locked()
            ok, message, response_payload = self._teleop_request_payload(
                payload,
                timeout_sec=(
                    _XARM6_CARTESIAN_SMOOTH_HANDOFF_TIMEOUT_SEC
                    if key == "xarm6" and command_key in {"start", "stop"}
                    else 4.0
                ),
                ros_domain_id=session.get("ros_domain_id"),
            )
            if command_key == "stop":
                self._release_teleop_smooth_session()
                if key == "xarm6":
                    with self._teleop_xarm6_cartesian_session_lock:
                        xarm6_session = self._teleop_xarm6_cartesian_session
                        if xarm6_session is not None:
                            xarm6_session["busy"] = False
                            self._touch_xarm6_cartesian_session_locked()
                if (
                    not ok
                    and response_payload.get("state_uncertain") is not False
                ):
                    failure_reason = f"Cartesian Smooth Hold stop failed: {message}"
                    if key == "ur5e":
                        self._ur5e_cartesian_jog_state_uncertain = True
                        self._ur5e_cartesian_jog_state_uncertain_reason = failure_reason
                    else:
                        self._xarm6_cartesian_jog_state_uncertain = True
                        self._xarm6_cartesian_jog_state_uncertain_reason = failure_reason
                return ok, message
            if not ok:
                stop_ok, stop_message, _stop_response = self._teleop_request_payload(
                    {
                        **payload,
                        "command": "stop",
                        "speed_mm_s": 0.0,
                    },
                    timeout_sec=(
                        _XARM6_CARTESIAN_SMOOTH_HANDOFF_TIMEOUT_SEC
                        if key == "xarm6"
                        else 4.0
                    ),
                    ros_domain_id=session.get("ros_domain_id"),
                )
                self._release_teleop_smooth_session()
                if key == "xarm6":
                    with self._teleop_xarm6_cartesian_session_lock:
                        xarm6_session = self._teleop_xarm6_cartesian_session
                        if xarm6_session is not None:
                            xarm6_session["busy"] = False
                            self._touch_xarm6_cartesian_session_locked()
                stop_motion_confirmed = bool(
                    stop_ok or _stop_response.get("state_uncertain") is False
                )
                if stop_motion_confirmed:
                    message = f"{message}; motion stop confirmed: {stop_message}"
                else:
                    failure_reason = (
                        f"Cartesian Smooth Hold command failed: {message}; "
                        f"stop failed: {stop_message}"
                    )
                    if key == "ur5e":
                        self._ur5e_cartesian_jog_state_uncertain = True
                        self._ur5e_cartesian_jog_state_uncertain_reason = failure_reason
                    else:
                        self._xarm6_cartesian_jog_state_uncertain = True
                        self._xarm6_cartesian_jog_state_uncertain_reason = failure_reason
            elif key == "xarm6":
                with self._teleop_xarm6_cartesian_session_lock:
                    xarm6_session = self._teleop_xarm6_cartesian_session
                    if xarm6_session is not None:
                        xarm6_session["busy"] = False
                        self._touch_xarm6_cartesian_session_locked()
            return ok, message

    def teleop_gripper(
        self,
        robot: str,
        action: str,
        step: float | None = None,
        velocity_scale: float = 1.0,
    ) -> tuple[bool, str]:
        robot = str(robot).strip().lower()
        action = str(action).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}"
        if action not in {"open", "close"}:
            return False, f"unknown gripper action: {action}"
        target = self._teleop_preflight(robot, "gripper")
        warning = str(target.get("warning") or "")
        if warning:
            return False, warning
        # Fast path: persistent backend for low-latency repeated clicks.
        payload: dict[str, Any] = {
            "op": "gripper",
            "robot": robot,
            "action": action,
            "velocity_scale": float(velocity_scale),
        }
        if step is not None:
            payload["step"] = float(step)
        ok, msg = self._teleop_request(
            payload=payload,
            timeout_sec=10.0 if robot == "xarm6" else 3.0,
        )
        if ok:
            return True, msg
        if str(target.get("environment") or "") == "real":
            return False, msg

        # Fallback to one-shot command only for backend/channel failures.
        transient_markers = (
            "teleop server",
            "stdin unavailable",
            "failed to send",
            "timeout",
            "exited",
            "closed stdout",
        )
        if not any(marker in msg.lower() for marker in transient_markers):
            return False, msg

        once_args = [
            "--once",
            "gripper",
            "--robot",
            robot,
            "--gripper-action",
            action,
            "--service-timeout-sec",
            "6",
            "--tf-warmup-sec",
            "0.1",
        ]
        if step is not None:
            once_args += ["--gripper-step", str(float(step))]
        execution_lock_acquired = False
        agent_motion_lock = None
        agent_lock_acquired = False
        if robot in {"xarm6", "ur5e"}:
            if not self._ur5e_robot_function_execution_lock.acquire(blocking=False):
                active = str(
                    self._ur5e_robot_function_execution_active
                    or "Physical robot motion"
                )
                return False, f"Physical robot motion is already active: {active}."
            execution_lock_acquired = True
            resource_agent = (
                self._physical_ur5e_robot_agent()
                if robot == "ur5e"
                else self._physical_xarm6_robot_agent()
            )
            agent_motion_lock = getattr(resource_agent, "_robot_motion_lock", None)
            if agent_motion_lock is not None:
                agent_lock_acquired = bool(agent_motion_lock.acquire(blocking=False))
                if not agent_lock_acquired:
                    self._ur5e_robot_function_execution_lock.release()
                    return False, (
                        f"The {robot} RobotAgent is already executing a robot task."
                    )
            self._ur5e_robot_function_execution_active = "Interactive Teleop gripper"
        try:
            return self._run_teleop_once(
                once_args,
                timeout_sec=10.0,
                ros_domain_id=target.get("ros_domain_id"),
            )
        finally:
            if agent_lock_acquired:
                agent_motion_lock.release()
            if execution_lock_acquired:
                self._ur5e_robot_function_execution_active = None
                self._ur5e_robot_function_execution_lock.release()

    def teleop_home(self, robot: str) -> tuple[bool, str]:
        robot = str(robot).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}"
        timeout_sec = (
            _UR5E_RTDE_CLIENT_RESULT_TIMEOUT_SEC + 5.0
            if robot == "ur5e"
            else 25.0
        )
        return self._teleop_request(
            payload={
                "op": "home",
                "robot": robot,
            },
            timeout_sec=timeout_sec,
        )

    def list_named_positions(self, robot: str) -> dict[str, list[float]]:
        """Return named positions for *robot* in the current environment."""
        robot = str(robot).strip().lower()
        env = str(self.teleop_target(robot).get("environment") or self.teleop_target_environment())
        # Map "real" → JSON key "real", "gazebo" → "gazebo"
        env_key = env if env in ("gazebo", "real") else "gazebo"
        path = _RESOURCE_DIR / f"robot_{robot}.json"
        if not path.exists():
            return {}
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            robot_block = data.get(robot, {})
            return dict(robot_block.get(env_key, {}).get("named_positions", {}))
        except Exception:
            log.exception("Failed to read named positions for %s", robot)
            return {}

    def teleop_go_to_position(self, robot: str, name: str) -> tuple[bool, str]:
        """Move *robot* to a stored named position by sending joint targets."""
        robot = str(robot).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}"
        positions = self.list_named_positions(robot)
        joints = positions.get(name)
        if not joints or not isinstance(joints, list):
            return False, f"named position '{name}' not found for {robot}"
        ready, readiness_message = self.teleop_named_position_readiness(robot)
        if not ready:
            return False, readiness_message
        timeout_sec = (
            _UR5E_RTDE_CLIENT_RESULT_TIMEOUT_SEC + 5.0
            if robot == "ur5e"
            else 25.0
        )
        return self._teleop_request(
            payload={
                "op": "move_joints",
                "robot": robot,
                "positions": [float(j) for j in joints],
                "named_position": str(name),
            },
            timeout_sec=timeout_sec,
        )

    def teleop_joint(
        self,
        robot: str,
        joint_idx: int,
        delta_deg: float,
        velocity_scale: float = 1.0,
        *,
        speed_deg_s: float | None = None,
    ) -> tuple[bool, str]:
        robot = str(robot).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}"
        idx = int(joint_idx)
        if idx < 1 or idx > 6:
            return False, f"invalid joint index: {joint_idx}"
        if speed_deg_s is not None:
            try:
                exact_speed_deg_s = float(speed_deg_s)
            except (TypeError, ValueError):
                return False, f"{robot} joint jog speed is not finite"
            settings = self.teleop_motion_settings(robot)
            minimum = float(settings["joint_speed_min_deg_s"])
            maximum = float(settings["joint_speed_max_deg_s"])
            if not math.isfinite(exact_speed_deg_s):
                return False, f"{robot} joint jog speed is not finite"
            if not minimum <= exact_speed_deg_s <= maximum:
                return False, (
                    f"{robot} joint jog speed {exact_speed_deg_s:.3f} deg/s is outside "
                    f"[{minimum:.3f}, {maximum:.3f}] deg/s"
                )
            if exact_speed_deg_s == 0.0:
                return False, f"{robot} joint jog speed is 0; no motion was commanded"
            speed_deg_s = exact_speed_deg_s
        estimated_motion_sec = (
            abs(float(delta_deg)) / float(speed_deg_s)
            if speed_deg_s is not None
            else 0.0
        )
        payload: dict[str, Any] = {
            "op": "joint",
            "robot": robot,
            "joint": idx,
            "delta_deg": float(delta_deg),
            "velocity_scale": float(velocity_scale),
        }
        if speed_deg_s is not None:
            payload["speed_deg_s"] = float(speed_deg_s)
        return self._teleop_request(
            payload=payload,
            timeout_sec=max(
                8.0,
                estimated_motion_sec + 25.0,
                (
                    _UR5E_RTDE_CLIENT_RESULT_TIMEOUT_SEC + 5.0
                    if robot == "ur5e"
                    else 0.0
                ),
            ),
        )

    def teleop_save_position(self, robot: str, name: str) -> tuple[bool, str]:
        robot = str(robot).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}"
        position_name = str(name).strip()
        if not position_name:
            return False, "position name is empty"
        if len(position_name) > 64:
            return False, "position name too long (max 64 chars)"
        target = self._teleop_preflight(robot, "save_position")
        warning = str(target.get("warning") or "")
        if warning:
            return False, warning
        return self._teleop_request(
            payload={
                "op": "save_position",
                "robot": robot,
                "name": position_name,
                "env": str(target.get("environment") or self.teleop_target_environment()),
            },
            timeout_sec=6.0,
        )

    def teleop_state(self, robot: str) -> tuple[bool, str, dict[str, Any]]:
        robot = str(robot).strip().lower()
        if robot not in {"xarm6", "ur5e"}:
            return False, f"unknown robot: {robot}", {}
        target = self._teleop_preflight(robot, "state")
        warning = str(target.get("warning") or "")
        if warning:
            return False, warning, {}
        ok, msg, payload = self._teleop_request_payload(
            payload={
                "op": "state",
                "robot": robot,
            },
            timeout_sec=4.0,
            ros_domain_id=target.get("ros_domain_id"),
        )
        if not ok:
            return False, msg, {}
        state = payload.get("state", {})
        if not isinstance(state, dict):
            return False, "invalid state payload", {}
        return True, msg, state

